(window.EXPRES_T=window.EXPRES_T||{})[2]={"html":"<div class=\"bloque-titulo\">CAPÍTULO I. RÉGIMEN <mark class=\"m-autoridad\">GENERAL</mark> DE LOS <mark class=\"m-personalizado\"><u class=\"m-clave\">MOVIMIENTOS</u> DE CAPITALES</mark> Y DE LAS <mark class=\"m-personalizado\">TRANSACCIONES</mark> ECONÓMICAS <mark class=\"m-personalizado\">CON EL EXTERIOR</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 1 — Principio de libertad de los movimientos de capitales y de las transacciones económicas con el exterior</div><div class=\"ex-fb\"><p><b>1.</b> Esta ley tiene por <mark class=\"m-destacable\">objeto</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">establecer el régimen jurídico</u> de los movimientos</mark> de capitales y de las</span></span> <mark class=\"m-personalizado\">transacciones</mark> económicas <mark class=\"m-personalizado\">con el exterior</mark>, <mark class=\"m-personalizado\">así como</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1004,2-ia-1009,2-ia-1122,2-ia-1932\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">establecer determinadas medidas de prevención del blanqueo de capitales</mark>.</p><p><b>2.</b> <mark class=\"m-destacable\">Son libres</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1418,2-ia-2026\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualesquiera actos, negocios, transacciones y operaciones entre residentes y no residentes que supongan o de cuyo cumplimiento puedan derivarse cobros y pagos exteriores</mark>, <mark class=\"m-personalizado\">así como las transferencias</mark> de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o al exterior y las <mark class=\"m-personalizado\">variaciones en cuentas o posiciones financieras</mark> deudoras o acreedoras frente al exterior, <mark class=\"m-personalizado\"><u class=\"m-clave\">sin más limitaciones</u></mark> que las dispuestas en <mark class=\"m-personalizado\"><u class=\"m-clave\">esta ley y</u> en la legislación sectorial específica</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1008,2-ia-1939,2-ia-2411\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 3 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 2 — Definiciones de residencia y no residencia</div><div class=\"ex-fb\"><p><b>A) <mark class=\"m-destacable\">«Residentes»:</mark></b> a. Las <mark class=\"m-personalizado\"><u class=\"m-clave\">personas</u> físicas que residan habitualmente en España</mark>, <mark class=\"m-personalizado\">salvo</mark> lo dispuesto en el <mark class=\"m-personalizado\">párrafo b)</mark> de «<mark class=\"m-personalizado\">No residentes</mark>». b. <mark class=\"m-resp\" data-q=\"2-62,2-ia-1014,2-ia-1507\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Los diplomáticos españoles acreditados en el extranjero y el personal español que preste servicios en embajadas y consulados españoles o en organizaciones internacionales en el extranjero</mark>. c. <mark class=\"m-resp r-ia\" data-q=\"2-ia-1104,2-ia-1410\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Las personas jurídicas con domicilio social en España</mark>. d. <mark class=\"m-personalizado\">Las sucursales y <u class=\"m-clave\">los establecimientos</u></mark> <mark class=\"m-destacable\">permanentes</mark> <mark class=\"m-personalizado\">en territorio español de personas físicas</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">jurídicas residentes en el extranjero</mark>. e. Otros que se determinen reglamentariamente en casos análogos.</p><p><b>B) <mark class=\"m-destacable\">«No residentes»:</mark></b> a. Las <mark class=\"m-personalizado\"><u class=\"m-clave\">personas físicas</u></mark> que tengan su <mark class=\"m-personalizado\">residencia habitual en territorio extranjero</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, salvo lo dispuesto en el párrafo b) correspondiente al epígrafe de «Residentes»</span></span>. b. <mark class=\"m-resp\" data-q=\"2-11,2-82,2-ia-1010\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Los diplomáticos extranjeros acreditados ante el Gobierno español y el personal extranjero que preste servicios en embajadas y consulados extranjeros o en organizaciones internacionales en España</mark>. c. <mark class=\"m-resp\" data-q=\"2-11\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Las personas jurídicas con domicilio social en el extranjero</mark>. d. <mark class=\"m-resp r-ia\" data-q=\"2-ia-1011,2-ia-1409,2-ia-1422\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Las sucursales y los establecimientos permanentes en el extranjero de personas físicas o jurídicas residentes en España</mark>. e. Otros que se determinen reglamentariamente en casos análogos. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1136,2-ia-1907\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>2.</b> Por <mark class=\"m-destacable\">residencia habitual</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">lo establecido en la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1012\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">normativa fiscal con las adaptaciones que reglamentariamente se determinen</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">La condición de</mark> residente o no residente (…) se <mark class=\"m-accion\">acreditará</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"2-ia-1013\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">en la forma <u class=\"m-clave\">que</u> reglamentariamente se establezca</mark></mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 3 — Obligaciones de información <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p><b>1.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Los actos, negocios</u></mark>, <mark class=\"m-personalizado\">transacciones y operaciones</mark> (…) <mark class=\"m-accion\">deberán</mark> <mark class=\"m-personalizado\">ser <u class=\"m-clave\">declarados</u> por los</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1449,2-ia-1621\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sujetos obligados</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">mencionados</mark> en el apartado siguiente (…), a los <mark class=\"m-personalizado\">efectos de información administrativa y estadística de las operaciones</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1015\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b><mark class=\"m-destacable\">2.</mark></b> <mark class=\"m-personalizado\">Las</mark> personas físicas o jurídicas residentes o no residentes en España que realicen las <mark class=\"m-personalizado\">operaciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">señaladas en el apartado 2 del artículo 1</span></span> quedan <mark class=\"m-accion\">obligadas</mark> a facilitar <mark class=\"m-resp\" data-q=\"2-29,2-107,2-155,2-ia-1712,2-ia-1724,2-ia-1929\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">al Ministerio de Economía y al Banco de España</mark>, en la forma y plazos que se establezcan, los datos que se les requieran <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">, a los efectos de lo dispuesto en el apartado anterior. A\u0007 demás, las entidades de crédito, las empresas de servicios de inversión y otros intermediarios financieros, que intervengan en la realización de las operaciones mencionadas por cuenta de sus clientes, vendrán obligados a remitir al Ministerio de Economía y al Banco de España la información correspondiente a las transacciones de sus clientes, en la forma y plazos que se establezcan</span></span></span>.</p><p data-ex=\"EXOF\">Además, las <mark class=\"m-autoridad\">entidades de crédito</mark>, <mark class=\"m-autoridad\">las empresas de servicios de inversión <u class=\"m-clave\">y</u></mark> otros <mark class=\"m-autoridad\">intermediarios</mark> financieros <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, que intervengan en la realización de las operaciones mencionadas por cuenta de sus clientes,</span></span> <mark class=\"m-accion\">vendrán obligados</mark> <mark class=\"m-personalizado\">a remitir</mark> <mark class=\"m-autoridad\">al Ministerio de Economía</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-autoridad\">al Banco de España</mark> <mark class=\"m-personalizado\">la información</mark> correspondiente a las <mark class=\"m-personalizado\">transacciones</mark> de sus clientes <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">, en la forma y plazos que se establezcan</span></span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1016\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 4 y 5 — Cláusulas de salvaguardia y medidas excepcionales · R1 <span class=\"ex-sello ex-sello-r\">R1</span></div><div class=\"ex-fb\"><p><b>Art. 4.</b> 1. <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-destacable\">prohibida o limitada</mark>, en los términos que señalen las normas comunitarias, la realización de determinados <mark class=\"m-personalizado\"><u class=\"m-clave\">movimientos</u> de capitales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y sus correspondientes operaciones de cobro o pago, así como las transferencias de o al exterior o las variaciones en cuentas o posiciones financieras deudoras o acreedoras frente al exterior,</span></span> <mark class=\"m-personalizado\">respecto de</mark> <mark class=\"m-autoridad\">terceros países</mark> en relación con <mark class=\"m-personalizado\">los cuales</mark> <mark class=\"m-resp\" data-q=\"2-5,2-76\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el Consejo de la Unión Europea</mark>, de conformidad con lo establecido en el <span class=\"ref-art\">artículo 59</span> del Tratado Constitutivo de la Comunidad Europea, <mark class=\"m-personalizado\"><u class=\"m-clave\">haya adoptado</u></mark> <mark class=\"m-destacable\">medidas de salvaguardia</mark>.</p><p><b>2.</b> (…) <mark class=\"m-autoridad\">el Gobierno</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">mediante</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">acuerdo</mark> <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Consejo</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">de</mark></span> <mark class=\"m-autoridad\">Ministros</mark>, <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">las especificaciones ulteriores</mark> que resulten <mark class=\"m-personalizado\">precisas</mark>, <mark class=\"m-personalizado\">incluido el procedimiento de autorización</mark> aplicable, <mark class=\"m-personalizado\"><u class=\"m-clave\">si</u> procediera</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1017\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-r=\"R1\"><span class=\"ex-sello ex-sello-r\">R1</span> <b>3.</b> <mark class=\"m-resp\" data-q=\"2-10,2-69,2-81,2-119,2-ia-1108\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">El Gobierno, mediante acuerdo del Consejo de Ministros, a propuesta del Ministro de Economía</mark>, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">prohibir o limitar</mark> la realización de determinados <mark class=\"m-personalizado\">movimientos</mark> de capitales <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y sus correspondientes operaciones de cobro o pago, así como transferencias de o al exterior o variaciones en cuentas o posiciones financieras deudoras o acreedoras frente al exterior,</span></span> <mark class=\"m-personalizado\">respecto de</mark> <mark class=\"m-autoridad\">un Estado, un territorio o centro <u class=\"m-clave\">extraterritorial</u></mark>, <mark class=\"m-autoridad\"><u class=\"m-clave\">o</u> grupo de Estados</mark> <mark class=\"m-personalizado\">en aplicación de medidas adoptadas</mark> <mark class=\"m-autoridad\">por</mark> <mark class=\"m-personalizado\">organismos</mark> <mark class=\"m-autoridad\">internacionales,</mark> <mark class=\"m-personalizado\">distintos de la</mark> <mark class=\"m-autoridad\">Comunidad Europea</mark>, de los que España sea miembro. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1007,2-ia-1018,2-ia-1559,2-ia-1107,2-ia-1116,2-ia-1119,2-ia-1125\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 7 preguntas</mark></p><p><b>4.</b> De conformidad con lo establecido <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en el <span class=\"ref-art\">artículo 60.2</span> del Tratado (…), el <mark class=\"m-autoridad\">Gobierno,</mark> mediante acuerdo del <mark class=\"m-autoridad\">Consejo de Ministros,</mark> a propuesta del Ministro de Economía, <mark class=\"m-accion\">podrá</mark> en tanto no se hayan adoptado las medidas a que se refiere</span></span> el <span class=\"ref-art\">artículo 60.1</span> del citado Tratado, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1020\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">por razones políticas graves y por motivos de urgencia</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">tomar medidas</mark> <mark class=\"m-personalizado\">unilaterales contra un</mark> <mark class=\"m-autoridad\">tercer país</mark> en lo relativo a los movimientos de capitales y a los pagos.</span></span></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 6</mark> — Autorizaciones sobre actos afectados por cláusulas de salvaguardia o <mark class=\"m-personalizado\">medidas</mark> excepcionales: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1021,2-ia-1023\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\">Artículo 7 — <mark class=\"m-destacable\">Suspensión del régimen de liberalización</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1005,2-ia-1024,2-ia-1025,2-ia-1032\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 4 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 7 bis — Suspensión de la liberalización de determinadas inversiones extranjeras directas en España <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p><b><mark class=\"m-destacable\">1.</mark></b> (…) <mark class=\"m-destacable\">se consideran inversiones extranjeras directas en España</mark> todas <mark class=\"m-destacable\">aquellas como</mark> consecuencia <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de las cuales el inversor</span></span> pase a ostentar una participación <mark class=\"m-resp r-ia\" data-q=\"2-ia-1026\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">igual o superior al 10 por 100</mark> del <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">capital social de una sociedad española, y todas aquéllas otras que (…) <mark class=\"m-destacable\">se <u class=\"m-clave\">adquiera el control</u></mark> (…) <mark class=\"m-destacable\">por aplicación</mark> de los criterios establecidos en <u class=\"m-clave\">el</u> <span class=\"ref-art\">artículo 7</span> de la Ley 15/2007, de 3 de julio, de Defensa de la Competencia, <mark class=\"m-personalizado\"><u class=\"m-clave\">siempre que</u> concurra una de estas circunstancias</mark></span></span> : <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a) que se realicen <mark class=\"m-personalizado\">por residentes de países fuera de la Unión</mark> Europea <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u> de la Asociación Europea de Libre Comercio</mark>; b) que se <mark class=\"m-personalizado\">realicen <u class=\"m-clave\">por residentes</u> de países de la UE o de la AELC cuya <u class=\"m-clave\">titularidad real</u> corresponda a <u class=\"m-clave\">residentes</u> de países <u class=\"m-clave\">de</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">fuera</mark></span> (…).</span></span> Se <mark class=\"m-accion\">entenderá</mark> que existe esa <mark class=\"m-personalizado\"><u class=\"m-clave\">titularidad</u> real cuando</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">estos últimos <mark class=\"m-personalizado\">posean o controlen</mark></span></span> en último <mark class=\"m-personalizado\"><u class=\"m-clave\">término</u></mark> (…) <mark class=\"m-destacable\">un porcentaje</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1027\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">superior al 25%</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">del <u class=\"m-clave\">capital</u> o de los derechos</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">de</mark></span> voto del inversor (…).</span></span></p><p><b>2.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Queda <mark class=\"m-destacable\">suspendido</mark> <mark class=\"m-personalizado\">el régimen de</mark> <mark class=\"m-destacable\">liberalización</mark> <mark class=\"m-personalizado\">de las inversiones extranjeras directas</mark> (…) <mark class=\"m-personalizado\">en los <u class=\"m-clave\">sectores</u> que se citan <u class=\"m-clave\">a continuación</u> y que <u class=\"m-clave\">afectan</u> al</mark> <mark class=\"m-destacable\">orden público, la seguridad pública</mark> y <mark class=\"m-destacable\">a la salud pública</mark>:</span></span> a) <mark class=\"m-destacable\"><u class=\"m-clave\">Infraestructuras críticas</u></mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">ya sean físicas</u></mark> o virtuales (…), entendiendo por tales, las contempladas en la <mark class=\"m-resp r-ia\" data-q=\"2-ia-2425\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Ley 8/2011, de 28 de abril</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por la que se establecen medidas para la protección de las infraestructuras críticas.</span></span>  b) <mark class=\"m-personalizado\"><u class=\"m-clave\">Tecnologías</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">críticas y de doble uso</u></mark> (…), incluidas las <mark class=\"m-personalizado\">telecomunicaciones</mark>, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1028\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">inteligencia artificial</mark>, <mark class=\"m-personalizado\">la robótica</mark>, <mark class=\"m-personalizado\">los</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1028\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">semiconductores</mark>, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1029\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">ciberseguridad</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">las tecnologías aeroespaciales</mark>, <mark class=\"m-personalizado\">de defensa</mark>, <mark class=\"m-personalizado\">de almacenamiento de energía</mark>,</span></span> <mark class=\"m-personalizado\">cuántica y nuclear</mark>, <mark class=\"m-personalizado\">las nanotecnologías</mark>, <mark class=\"m-personalizado\">las</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1028\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">biotecnologías</mark> (…). <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">c) <mark class=\"m-destacable\"><u class=\"m-clave\">Suministro de insumos</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">fundamentales</u></mark>, en particular energía (…) así como a la <mark class=\"m-personalizado\">seguridad</mark> alimentaria.</span></span> d) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1619,2-ia-2135\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Sectores con acceso a información sensible</mark>, en <mark class=\"m-personalizado\">particular a <u class=\"m-clave\">datos</u> personales</mark> (…) de acuerdo con la LO 3/2018 (…). e) <mark class=\"m-destacable\">Medios de comunicación</mark>, sin perjuicio de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que los servicios de comunicación audiovisual (…) se <mark class=\"m-accion\">regirán</mark></span></span> por lo dispuesto en la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1030,2-ia-1321\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Ley 7/2010, de 31 de marzo, General de la Comunicación Audiovisual</mark>.</p><p><b>3.</b> Asimismo, queda <mark class=\"m-destacable\">suspendido</mark> (…): <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a) si el inversor extranjero está controlado directa o indirectamente por <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">gobierno</mark> (…) <mark class=\"m-personalizado\">de <u class=\"m-clave\">un</u> tercer</mark> <mark class=\"m-destacable\">país</mark> <mark class=\"m-personalizado\">aplicándose</mark> (…) <mark class=\"m-personalizado\">los criterios establecidos en el</mark> <span class=\"ref-art\">artículo 7.2</span> de la Ley de Defensa de la Competencia; b) si el inversor (…) ha participado en actividades en los sectores que afecten a la <mark class=\"m-personalizado\"><u class=\"m-clave\">seguridad</u></mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">al orden público</u> y a la salud pública en</mark> <mark class=\"m-autoridad\">otro Estado miembro</mark> (…); c) <mark class=\"m-personalizado\">si existe un <u class=\"m-clave\">riesgo grave</u> de que el inversor extranjero ejerza actividades delictivas o <u class=\"m-clave\">ilegales</u></mark> (…).</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1031\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>5.</b> <mark class=\"m-destacable\">La suspensión</mark> (…) <mark class=\"m-accion\">determinará</mark> <mark class=\"m-personalizado\">el sometimiento</mark> de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">las referidas operaciones de inversión <mark class=\"m-personalizado\">a la obtención de</mark> autorización (…). <mark class=\"m-destacable\">Las operaciones</mark> <mark class=\"m-personalizado\">de inversión</mark> llevadas a</span></span> cabo <span class=\"m-circulo\"><mark class=\"m-destacable\">sin</mark></span> <mark class=\"m-personalizado\">la preceptiva</mark> <mark class=\"m-destacable\">autorización</mark> <mark class=\"m-personalizado\">previa</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1033\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">carecerán de validez y efectos jurídicos</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">en tanto no se produzca su legalización</mark> (…).</span></span></p><p data-ex=\"EXOF\"><b>6.</b> <mark class=\"m-accion\">El Gobierno podrá establecer</mark> <mark class=\"m-personalizado\">reglamentariamente</mark> <mark class=\"m-destacable\">las</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1034\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">categorías de operación y los importes</mark> <mark class=\"m-personalizado\">por debajo de los cuales</mark> las operaciones de inversión directa extranjera <mark class=\"m-accion\">quedarán</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">exentas</u></mark> de someterse al régimen de <mark class=\"m-personalizado\">autorización previa</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, por su nula o escasa repercusión en los bienes jurídicos protegidos por este artículo. Asimismo, se podrá acotar reglamentariamente la definición de los sectores relacionados en el apartado 2, a los efectos de la aplicación de la presente Ley. \u0007</span></span>. Se faculta a la <mark class=\"m-resp\" data-q=\"2-90\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Ministra de Industria, Comercio y Turismo</mark> para dictar <mark class=\"m-personalizado\">las <u class=\"m-clave\">normas</u></mark> necesarias para la correcta <mark class=\"m-personalizado\"><u class=\"m-clave\">ejecución</u></mark> y aplicación de las disposiciones <mark class=\"m-personalizado\">de <u class=\"m-clave\">desarrollo</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que dicte el Gobierno en desarrollo y ejecución de este artículo</span></span>.</p></div></div><div class=\"bloque-titulo\">CAPÍTULO II. RÉGIMEN SANCIONADOR</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 8 — Infracciones <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p><b>2.</b> <mark class=\"m-accion\">Constituirán</mark> <mark class=\"m-destacable\">infracciones muy graves</mark>: a) <mark class=\"m-personalizado\">la realización de actos</mark> (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1813\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">prohibidas</mark> <mark class=\"m-personalizado\">en virtud de la adopción de las medidas a que</mark> se refieren <mark class=\"m-personalizado\">los</mark> <span class=\"ref-art\">artículos 4 y 5</span>; b) <mark class=\"m-personalizado\">la realización de actos</mark> (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1035\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sin solicitar autorización</mark> cuando sea <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">preceptiva conforme a los <span class=\"ref-art\">artículos 6, 7 y 7 bis</span>, <mark class=\"m-personalizado\">o con</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">carácter</u> previo</mark> a su concesión o <mark class=\"m-personalizado\">con</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">incumplimiento</u> de las condiciones</mark> establecidas en la autorización;</span></span>  c) <span class=\"m-circulo\"><mark class=\"m-destacable\">la falta de</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">veracidad en las</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">solicitudes</mark></span> <mark class=\"m-personalizado\">de autorización</mark> (…), siempre que pueda estimarse como <mark class=\"m-resp r-ia\" data-q=\"2-ia-1036\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">especialmente relevante</mark>.</p><p data-ex=\"EXOF\"><b>3.</b> <mark class=\"m-accion\">Constituirán</mark> <mark class=\"m-destacable\">infracciones graves</mark>: a) <mark class=\"m-resp\" data-q=\"2-1,2-72,2-ia-1035,2-ia-1038,2-ia-1040\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">La falta de declaración de operaciones cuya cuantía supere los 6.000.000 de euros</mark>. b) <mark class=\"m-personalizado\">La falta de veracidad</mark>, <mark class=\"m-personalizado\">la omisión o inexactitud en los datos</mark> de las <mark class=\"m-destacable\">declaraciones</mark> respecto de <mark class=\"m-personalizado\">operaciones cuya cuantía supere los 6.000.000 de euros</mark>. c) <mark class=\"m-personalizado\">Los incumplimientos de los</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">requerimientos</u></mark> efectuados, de <mark class=\"m-personalizado\">modo expreso y por escrito</mark>, por <mark class=\"m-autoridad\">los organismos competentes</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en el cumplimiento de sus funciones</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1037\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>4.</b> <mark class=\"m-accion\">Constituirán</mark> <mark class=\"m-destacable\">infracciones leves</mark>: a) <mark class=\"m-personalizado\">las declaraciones</mark> realizadas por los sujetos obligados <mark class=\"m-personalizado\">fuera de los plazos</mark> reglamentariamente establecidos. b) <mark class=\"m-personalizado\">La <u class=\"m-clave\">falta de</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">declaración</u> de operaciones</mark> cuya cuantía <mark class=\"m-personalizado\">no <u class=\"m-clave\">supere 6.000.000</u> de euros</mark> (…).  <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1039\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 9 y 10 — Sanciones y graduación <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R2</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 9.</b> 2. Por la <mark class=\"m-autoridad\">comisión</mark> de <mark class=\"m-destacable\">infracciones muy</mark> <mark class=\"m-personalizado\">graves se</mark> <mark class=\"m-accion\">impondrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">simultáneamente</u></mark>: a) <mark class=\"m-personalizado\">multa</mark>, que <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ascender</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1041,2-ia-1117\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">hasta el tanto del contenido económico de la operación sin que pueda ser inferior a 30.000 euros</mark>, y b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1043\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">amonestación pública o privada</mark>. 3. Por la <mark class=\"m-autoridad\">comisión</mark> de <mark class=\"m-destacable\">infracciones</mark> graves <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">se impondrán simultáneamente las siguientes sanciones</span></span>: a) <mark class=\"m-personalizado\">multa</mark>, que <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ascender</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1042\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">hasta la mitad del contenido económico de la operación</mark> sin que <mark class=\"m-personalizado\">pueda ser <u class=\"m-clave\">inferior a 6.000</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">euros</mark></span>, <mark class=\"m-plazo\">y</mark> b) <mark class=\"m-personalizado\"><u class=\"m-clave\">amonestación</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">pública o privada</mark></span>. 4. <mark class=\"m-personalizado\">Por la</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">comisión</u></mark> de infracciones leves <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">se impondrán simultáneamente las siguientes sanciones</span></span>: a) <mark class=\"m-destacable\">multa</mark>, <mark class=\"m-destacable\">que</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">ascender</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1041\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">hasta un cuarto del contenido económico de la operación sin que pueda ser inferior a 3.000 euros</mark>, <mark class=\"m-personalizado\">y</mark> b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1043\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">amonestación privada</mark>.</p><p data-ex=\"*\" data-r=\"R2\"><span class=\"ex-sello ex-sello-r\">R2</span> <b>5.</b> Cuando <mark class=\"m-personalizado\">la infracción</mark> consista en la <mark class=\"m-destacable\">presentación fuera de plazo</mark> de las <mark class=\"m-destacable\">declaraciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por los sujetos obligados,</span></span> <mark class=\"m-personalizado\">sin actuación o requerimiento previo de la Administración</mark>: a) si <mark class=\"m-destacable\">no</mark> han transcurrido <mark class=\"m-destacable\">más de <u class=\"m-clave\">seis</u> meses</mark>, <mark class=\"m-personalizado\">hasta 300 euros</mark>, <span class=\"m-circulo\"><mark class=\"m-personalizado\">sin</mark></span> que pueda <mark class=\"m-personalizado\">ser inferior a 150 euros</mark>; b) si han transcurrido <mark class=\"m-destacable\">más de seis meses</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1045\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">hasta 600 euros</mark>, sin que pueda ser <mark class=\"m-personalizado\">inferior a 300</mark> euros. <mark class=\"m-resp ex-q\" data-q=\"2-120,2-ia-1044,2-ia-1123,2-ia-1131,2-ia-2316\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 5 preguntas</mark></p><p data-ex=\"EXOF,EX,*\"><b>Art. 10.</b> <mark class=\"m-destacable\">Las sanciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">aplicables en cada caso por la comisión de infracciones muy graves, graves o leves</span></span> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">determinarán</mark> considerándose <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, además de los criterios establecidos en el artículo 131.3 de la Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común,</span></span> <mark class=\"m-personalizado\">las siguientes circunstancias</mark>: a) <mark class=\"m-personalizado\">La</mark> <mark class=\"m-resp\" data-q=\"2-22\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">naturaleza y entidad</mark> <mark class=\"m-personalizado\">de la</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">infracción</mark></span>. b) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-resp\" data-q=\"2-22\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">grado de responsabilidad e intencionalidad</mark> en los <mark class=\"m-personalizado\">hechos</mark> que concurran en el interesado. c) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-resp\" data-q=\"2-22,2-ia-1047\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">tiempo que haya mediado entre la comisión de la infracción y el intento de subsanación de ésta por iniciativa propia</mark> del interesado. d) <mark class=\"m-personalizado\">La</mark> <mark class=\"m-resp r-vec\" data-q=\"2-22,2-ia-1047\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">capacidad económica</mark> del interesado. e) <mark class=\"m-personalizado\">La</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1048\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">conducta anterior</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">del</mark></span> <mark class=\"m-personalizado\">interesado</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en relación con las normas en materia de movimientos de capitales y pagos exteriores</span></span>, tomando en consideración <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">al efecto</span></span> las sanciones firmes que le hubieran sido impuestas <mark class=\"m-plazo\">durante los últimos cinco años</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 11 y 12 — Prescripción y procedimiento sancionador · R2 R3 R4 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R3</span> <span class=\"ex-sello ex-sello-r\">R4</span></div><div class=\"ex-fb\"><p data-r=\"R3,R4\"><span class=\"ex-sello ex-sello-r\">R3</span> <span class=\"ex-sello ex-sello-r\">R4</span> <b>Art. 11.</b> 1. Las infracciones muy graves <mark class=\"m-accion\">prescribirán</mark> a los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1046\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cinco años</mark>; las graves, a los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1051\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">tres años</mark>, y las leves, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1049\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">al año</mark>. 2. El plazo de prescripción se <mark class=\"m-accion\">contará</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1050\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">desde la fecha en que la infracción hubiera sido cometida</mark>. 3. Las sanciones que se impongan, en virtud de <mark class=\"m-plazo\">resolución</mark> firme <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, conforme a esta ley</span></span> <mark class=\"m-accion\">prescribirán</mark> a los cinco años, las muy graves; a los <mark class=\"m-resp\" data-q=\"2-122\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cuatro años</mark>, las graves, y a los tres años, las <mark class=\"m-destacable\">leves.</mark> <mark class=\"m-resp ex-q\" data-q=\"2-91,2-121\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 12.</b> <mark class=\"m-destacable\">2. a)</mark> <mark class=\"m-autoridad\">La competencia</mark> para la incoación e instrucción <mark class=\"m-autoridad\">de</mark> <mark class=\"m-personalizado\">los procedimientos sancionadores</mark> <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">a la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1052,2-ia-1109,2-ia-1118\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Secretaría de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark>, <mark class=\"m-resp\" data-q=\"2-156\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">salvo en materia de inversiones extranjeras directas en España</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">órgano</mark> que designe el titular <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-destacable\">Dirección General de Comercio Internacional e</mark> Inversiones.</p><p data-ex=\"*\">b) La <mark class=\"m-destacable\">imposición</mark> de sanciones por infracciones <mark class=\"m-destacable\">muy graves</mark> <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-resp\" data-q=\"2-156,2-ia-1054\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Consejo de Ministros</mark>, <mark class=\"m-autoridad\">a propuesta del titular del Ministerio de Asuntos <u class=\"m-clave\">Económicos</u> y Transformación</mark> Digital. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">N\u0007 o obstante, cuando se trate de infracciones muy graves</span></span> en materia de inversiones extranjeras directas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en España, la imposición de sanciones corresponderá</span></span> al <mark class=\"m-autoridad\">Consejo de Ministros,</mark> a propuesta del titular del <mark class=\"m-resp r-ia\" data-q=\"2-ia-1055\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Ministerio de Industria, Comercio y Turismo</mark>.</p><p data-ex=\"*\">c) La imposición <mark class=\"m-personalizado\">de sanciones por infracciones graves</mark> <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">al titular del</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Asuntos Económicos y Transformación Digital</mark>, a <mark class=\"m-personalizado\">propuesta del titular de la</mark> <mark class=\"m-autoridad\">Secretaría de Estado</mark> de Economía. En el <mark class=\"m-personalizado\">supuesto de infracciones graves</mark> en materia de inversiones extranjeras directas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en España, la imposición de sanciones corresponderá</span></span>, al titular del <mark class=\"m-resp\" data-q=\"2-90\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Ministerio de Industria, Comercio y Turismo</mark>, a propuesta del titular de la <mark class=\"m-autoridad\">Secretaría de Estado</mark> de Comercio.</p><p data-ex=\"*\">d) La imposición de sanciones por infracciones leves <mark class=\"m-accion\">corresponderá</mark> al titular de la Dirección General del Tesoro y Política Financiera, a propuesta <mark class=\"m-resp r-ia\" data-q=\"2-ia-1057\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">del <mark class=\"m-autoridad\">órgano</mark> instructor</mark>. En el caso de infracciones leves en materia de inversiones extranjeras directas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en España, la imposición de sanciones corresponderá</span></span>, al titular de la <mark class=\"m-resp\" data-q=\"2-157,2-ia-1053,2-ia-1730\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Dirección General de Comercio Internacional e Inversiones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, a propuesta del órgano instructor</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1059\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>3.</b> (…) El plazo máximo para resolver el procedimiento y notificar la resolución <mark class=\"m-accion\">será</mark> de <mark class=\"m-resp r-ia\" data-q=\"2-ia-1058,2-ia-1853\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">un año a contar desde la fecha del acuerdo de incoación</mark> (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Disposición adicional primera — Modificación de la Ley 19/1993 (declaración de medios de pago) <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>b)</b> <mark class=\"m-personalizado\">Movimientos por territorio nacional de medios de pago</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">consistentes en moneda metálica, billetes de banco y cheques bancarios al portador, denominados en moneda nacional o en cualquier otra moneda o cualquier medio físico, incluidos los electrónicos, concebido para ser utilizado como medio</span></span> de pago, por <mark class=\"m-destacable\">importe superior a <mark class=\"m-resp r-ia\" data-q=\"2-ia-1106\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">80.500 euros</mark>.</mark></p></div></div><div class=\"bloque-titulo\">2.2 — <mark class=\"m-destacable\">CONVENIO</mark> DEL <mark class=\"m-autoridad\">CONSEJO</mark> DE EUROPA PARA LA PREVENCIÓN <mark class=\"m-personalizado\">DEL TERRORISMO</mark> (<mark class=\"m-destacable\">CONVENIO</mark> N.º 196), HECHO EN VARSOVIA EL 16 <mark class=\"m-personalizado\">DE MAYO</mark> DE 2005</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 1 y 2 — Terminología y objetivo</div><div class=\"ex-fb\"><p><b>Art. 1.</b> 1. A los efectos del presente Convenio, se <mark class=\"m-accion\">entenderá</mark> por <mark class=\"m-destacable\">«delito terrorista»</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1138,2-ia-1552\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualquiera de los delitos incluidos en el ámbito de aplicación y definidos en uno de los tratados enumerados en el anexo</mark>. 2. <mark class=\"m-resp r-ia\" data-q=\"2-ia-1235,2-ia-1252,2-ia-1318,2-ia-2120\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Al depositar su instrumento de ratificación</mark>, aceptación, aprobación o <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">adhesión, un <mark class=\"m-autoridad\">Estado</mark> o la Comunidad Europea, que no sea parte en alguno de los tratados enumerados en el anexo, <mark class=\"m-accion\">podrá</mark> declarar que (…) se <mark class=\"m-accion\">considerará</mark> que el mencionado tratado no figura en ese anexo.</span></span>  La declaración <mark class=\"m-accion\">quedará</mark> sin efecto <mark class=\"m-resp r-ia\" data-q=\"2-ia-1139\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">desde el momento de la entrada en vigor del tratado para la Parte que la haya efectuado</mark> (…). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1231\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 2.</b> <mark class=\"m-destacable\">El objetivo del</mark> presente Convenio <mark class=\"m-destacable\">es</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1141\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">mejorar los esfuerzos de las Partes para la prevención del terrorismo y de sus efectos negativos</mark> <mark class=\"m-personalizado\">sobre el <u class=\"m-clave\">pleno</u> disfrute de los <u class=\"m-clave\">derechos</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">humanos</mark></span> <mark class=\"m-personalizado\">y <u class=\"m-clave\">en</u> particular sobre el</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1141\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">derecho a la vida</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por medio de la adopción de medidas, tanto a nivel nacional como en el marco de <mark class=\"m-personalizado\">la</mark> cooperación internacional (…).</span></span></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 3 y 4 — Políticas nacionales de prevención y cooperación internacional <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p><b>1.</b> Cada Parte <mark class=\"m-accion\">tomará</mark> <mark class=\"m-personalizado\">las medidas apropiadas</mark>, <mark class=\"m-personalizado\">en particular en</mark> el ámbito de la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1124,2-ia-1145,2-ia-1919\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">formación de las autoridades encargadas del cumplimiento de la ley y otros órganos, así como en el ámbito de la educación, la cultura, la información, los medios de comunicación y la sensibilización del público</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con <mark class=\"m-personalizado\"><u class=\"m-clave\">vistas a prevenir</u> los delitos terroristas</mark> y sus efectos negativos, <mark class=\"m-personalizado\">respetando</mark> (…) <mark class=\"m-personalizado\">las</mark> obligaciones relativas a los <mark class=\"m-personalizado\"><u class=\"m-clave\">derechos humanos</u></mark> (…).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1142,2-ia-1549,2-ia-1655,2-ia-1709,2-ia-2414\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 5 preguntas</mark></p><p data-ex=\"EXOF\"><b>2.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Cada Parte tomará las medidas necesarias para</span></span> <mark class=\"m-personalizado\">mejorar y desarrollar la cooperación entre las</mark> <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-personalizado\">nacionales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con vistas a prevenir los delitos terroristas y sus efectos negativos,</span></span> en particular <span class=\"m-caja\">mediante</span>: a) <mark class=\"m-personalizado\">el</mark> <mark class=\"m-resp\" data-q=\"2-92\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">intercambio de información</mark>; b) <mark class=\"m-personalizado\">el</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1868\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">refuerzo de la protección física</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u> las personas y de los bienes;</mark> c) <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp\" data-q=\"2-92,2-ia-1143\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">mejora de los planes de formación y coordinación para situaciones de crisis</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1720,2-ia-2160\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-autoridad\">Cada Parte</mark> <mark class=\"m-accion\">promoverá</mark> <mark class=\"m-destacable\">la tolerancia</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">fomentando el</u></mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1144\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">diálogo interreligioso y transcultural</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">fomentando, en su caso, <mark class=\"m-personalizado\">la participación de organizaciones</mark> no <mark class=\"m-personalizado\">gubernamentales <u class=\"m-clave\">y</u> otros</mark> actores de la sociedad civil (…).</span></span></p><p><b>Art. 4.</b> <mark class=\"m-autoridad\">Las Partes</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">prestarán</mark> <mark class=\"m-personalizado\">asistencia y apoyo mutuos</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) incluido el <mark class=\"m-personalizado\">intercambio</mark> de información y <mark class=\"m-destacable\">de buenas prácticas</mark>, así como mediante la <mark class=\"m-destacable\">formación y otros</mark> esfuerzos conjuntos de carácter preventivo.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1146\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"2-17\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 5, 6 y 7 — Provocación pública, reclutamiento y adiestramiento con fines terroristas · R5 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R5</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\" data-r=\"R5\"><span class=\"ex-sello ex-sello-r\">R5</span> <b>Art. 5.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 5. <mark class=\"m-resp r-ia\" data-q=\"2-ia-1208\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">PROVOCACIÓN PÚBLICA PARA COMETER DELITOS TERRORISTAS</mark>. 1. A\u0007 los efectos del presente Convenio,</span></span> <mark class=\"m-accion\">se entenderá</mark> por <mark class=\"m-destacable\">«provocación pública</mark> para cometer delitos <mark class=\"m-destacable\">terroristas»</mark>: <mark class=\"m-resp\" data-q=\"2-6,2-77,2-ia-1201\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">la difusión o cualquier otra forma de puesta a disposición del público de mensajes con la intención de incitar a cometer delitos terroristas, cuando ese comportamiento, ya preconice directamente o no la comisión de delitos terroristas, cree peligro de que se puedan cometer uno o varios delitos</mark>. 2. <mark class=\"m-autoridad\">Cada</mark> Parte <mark class=\"m-accion\">adoptará</mark> las medidas <mark class=\"m-destacable\">necesarias</mark> para <mark class=\"m-destacable\"><u class=\"m-clave\">tipificar</u></mark> <mark class=\"m-personalizado\">como delito</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con su derecho interno,</span></span> <span class=\"m-caja\">la</span> <mark class=\"m-destacable\">provocación</mark> pública <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">para cometer delitos terroristas tal como se define en el apartado 1</span></span>, <mark class=\"m-personalizado\">cuando se cometa</mark> <mark class=\"m-resp\" data-q=\"2-79,2-ia-1202\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">ilegal e intencionadamente</mark>.</p><p data-ex=\"*\"><b>Art. 6.</b> <mark class=\"m-destacable\"><u class=\"m-clave\">1.</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 6. RECLUTAMIENTO CON FINES TERRORISTAS.1 1. \u0007A los efectos del presente Convenio,</span></span> <mark class=\"m-destacable\">se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-destacable\">por «reclutamiento con fines terroristas»</mark>: <mark class=\"m-resp r-ia\" data-q=\"2-ia-1144,2-ia-1203,2-ia-1446\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el hecho de incitar a otra persona a cometer o participar en la comisión de delitos terroristas, o a unirse a una asociación o a un grupo para contribuir a que éstos cometan uno o varios delitos terroristas</mark> (aquí no se <mark class=\"m-destacable\">exige la difusión</mark>). <mark class=\"m-personalizado\">2.</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">C\u0007 ada Parte adoptará las medidas necesarias para tipificar como delito, de conformidad con su derecho interno, el reclutamiento con fines terroristas, tal como se define en el apartado 1 del presente artículo,</span></span> <mark class=\"m-personalizado\">cuando se cometa</mark> <mark class=\"m-resp\" data-q=\"2-8\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">ilegal e intencionadamente</mark>.</p><p data-ex=\"*\"><b>Art. 7.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 7. ADIESTRAMIENTO CON FINES TERRORISTAS. 1. A\u0007 los efectos del presente Convenio,</span></span> se <mark class=\"m-accion\">entenderá</mark> por <mark class=\"m-destacable\">«adiestramiento</mark> con fines terroristas»: <mark class=\"m-resp r-ia\" data-q=\"2-ia-1204\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el hecho de dar instrucciones para la fabricación o el uso de explosivos, armas de fuego u otras armas o sustancias nocivas o peligrosas</mark>, <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">para otros métodos y técnicas específicos con <u class=\"m-clave\">vistas</u> a <u class=\"m-clave\">cometer</u> delitos <u class=\"m-clave\">terroristas o a</u></mark> contribuir a <mark class=\"m-personalizado\"><u class=\"m-clave\">su</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">comisión</u></mark>, <mark class=\"m-personalizado\">sabiendo que la</mark> <mark class=\"m-destacable\">formación facilitada</mark> tiene por <mark class=\"m-destacable\">objeto</mark> <mark class=\"m-personalizado\">servir para la realización de tales objetivos</mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Cada Parte adoptará las medidas necesarias para tipificar como delito, de conformidad con su derecho interno, el adiestramiento con fines terroristas, tal como se define en el apartado 1 del presente artículo,</span></span> cuando se cometa <mark class=\"m-resp\" data-q=\"2-8\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">ilegal e intencionadamente</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 8 y 9 — Irrelevancia del resultado y delitos accesorios <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 8.</b> Para que un acto <mark class=\"m-personalizado\">constituya delito</mark> en virtud de los <span class=\"ref-art\">artículos 5 a 7</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio</span></span>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1205\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no será necesario que el delito terrorista se haya cometido efectivamente</mark>.</p><p data-ex=\"EX\"><b>Art. 9.</b> <mark class=\"m-destacable\">1. Cada Parte</mark> <mark class=\"m-accion\">adoptará</mark> las <mark class=\"m-destacable\">medidas necesarias</mark> para <mark class=\"m-destacable\"><u class=\"m-clave\">tipificar</u></mark> <mark class=\"m-personalizado\">como</mark> delito <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con su dere- cho interno</span></span>: a) la participación <mark class=\"m-destacable\">como cómplice en</mark> un delito con arreglo a los <mark class=\"m-personalizado\"><span class=\"ref-art\">artículos 5 a 7</span></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio</span></span>; b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1206,2-ia-1209\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la organización de la comisión de delitos con arreglo a los <span class=\"ref-art\">artículos 5 a 7</span> del presente Convenio o la orden de cometerlos por otras personas</mark>; c) <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u></mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">contribución</mark></span> <mark class=\"m-personalizado\">a la</mark> <mark class=\"m-autoridad\">comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de uno o varios de los delitos previstos en los artículos 5 a 7 del presente Convenio</span></span> por un grupo de personas que actúe con un objetivo común. Esta contribución <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">ser</mark> <mark class=\"m-destacable\">deliberada</mark> y: i) tener como <mark class=\"m-personalizado\">objetivo</mark> <mark class=\"m-destacable\">facilitar</mark> <mark class=\"m-personalizado\">la actividad criminal del grupo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o servir a su objetivo, cuando esa actividad o ese objetivo supongan la comisión de un delito de los previstos en los artículos 5 a 7 del presente Convenio</span></span>; <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u> bien</mark> ii) <mark class=\"m-personalizado\">efectuarla</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">sabiendo</u></mark> que el grupo tiene <mark class=\"m-destacable\"><u class=\"m-clave\">intención</u></mark> <mark class=\"m-personalizado\">de cometer</mark> un delito previsto en los <span class=\"ref-art\">artículos 5 a 7</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1207\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 10 y 11 — Responsabilidad de las personas jurídicas y sanciones · R6 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R6</span></div><div class=\"ex-fb\"><p data-ex=\"EX\" data-r=\"R6\"><span class=\"ex-sello ex-sello-r\">R6</span> <b>Art. 10.</b> 1. <mark class=\"m-autoridad\">Cada Parte</mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-destacable\">las medidas necesarias</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con sus principios jurídicos,</span></span> para <mark class=\"m-personalizado\">establecer la responsabilidad de las personas jurídicas</mark> que participen en los delitos a que se refieren los <span class=\"ref-art\">artículos 5 a 7 y 9</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio (Provocación, reclutamiento y adiestramiento, además de los delitos accesorios: participación como cómplice, organización de la comisión…)</span></span>. 2. Sin perjuicio de los principios jurídicos de la Parte, la <mark class=\"m-destacable\">responsabilidad</mark> <mark class=\"m-personalizado\">de las personas jurídicas</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser:</mark> <mark class=\"m-resp\" data-q=\"2-20\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">penal, civil o administrativa</mark>. <mark class=\"m-destacable\">3.</mark> Esta responsabilidad <mark class=\"m-accion\">se entenderá</mark> sin <mark class=\"m-personalizado\">perjuicio de la responsabilidad penal de las personas</mark> físicas que hayan cometido los delitos. <mark class=\"m-resp ex-q\" data-q=\"2-89\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 11.</b> 1. Cada Parte <mark class=\"m-accion\">adoptará</mark> las medidas <mark class=\"m-destacable\">necesarias</mark> para que a los delitos a que se refieren los <span class=\"ref-art\">artículos 5 a 7 y 9</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio</span></span> <mark class=\"m-personalizado\">sean aplicables penas</mark>: <mark class=\"m-resp\" data-q=\"2-32,2-ia-1211\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">efectivas, proporcionadas y disuasorias</mark>. 2. <mark class=\"m-personalizado\">Toda <u class=\"m-clave\">condena firme</u> anterior dictada en un</mark> <mark class=\"m-autoridad\">Estado extranjero</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por los delitos a que se refiere el presente Convenio</span></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1212\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">podrá tenerse en cuenta en la determinación de la pena</mark>, en la medida en que lo <mark class=\"m-personalizado\">permita el derecho interno</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y de conformidad con el mismo</span></span>. 3. <mark class=\"m-autoridad\">Cada Parte</mark> <mark class=\"m-accion\">velará</mark> por que <mark class=\"m-personalizado\">las <u class=\"m-clave\">personas jurídicas</u></mark> consideradas <mark class=\"m-personalizado\">responsables</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con el artículo 10,</span></span> <u class=\"m-clave\">sean</u> <mark class=\"m-personalizado\">objeto de sanciones efectivas</mark>, <mark class=\"m-personalizado\">proporcionadas y disuasorias</mark> de naturaleza penal o no penal, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1213\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">incluidas las sanciones pecuniarias</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 12 y 13 — Condiciones y salvaguardias y protección de las víctimas <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b>Art. 12.</b> 1. <mark class=\"m-autoridad\">Cada Parte</mark> <mark class=\"m-accion\">deberá asegurarse</mark> de que el establecimiento, la ejecución y la aplicación de los tipos <mark class=\"m-personalizado\">penales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a que se refieren los artículos 5 a 7 y 9 del presente Convenio</span></span> se efectúen respetando las obligaciones <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que le incumban</span></span> relativas a los derechos humanos, en particular <mark class=\"m-resp r-ia\" data-q=\"2-ia-1137,2-ia-1214\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la libertad de expresión, la libertad de asociación y la libertad de religión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, tal como se establecen en el Convenio para la protección de los derechos humanos y de las libertades fundamentales, en el Pacto Internacional de derechos civiles y políticos, y otras obligaciones dimanantes del derecho internacional, cuando le sean aplicables</span></span>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">E\u0007 l establecimiento, la ejecución y la aplicación de los tipos penales a que se refieren los artículos 5 a 7 y 9 del presente Convenio</span></span> <mark class=\"m-personalizado\">deberían</mark> supeditarse además al <mark class=\"m-personalizado\">principio de proporcionalidad</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, teniendo en cuenta los objetivos legítimos perseguidos y su necesidad en una sociedad democrática,</span></span> <mark class=\"m-personalizado\">y deberían</mark> excluir toda forma de arbitrariedad o de tratamiento discriminatorio <mark class=\"m-destacable\"><u class=\"m-clave\">o racista</u></mark>. <mark class=\"m-resp ex-q\" data-q=\"2-86,2-ia-1215\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 13.</b> <mark class=\"m-destacable\">Cada Parte</mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-destacable\">las</mark> <mark class=\"m-personalizado\">medidas necesarias para <u class=\"m-clave\">proteger y apoyar</u> a las</mark> <mark class=\"m-resp\" data-q=\"2-158,2-ia-1216\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">víctimas de acciones terroristas cometidas en su propio territorio</mark>. <mark class=\"m-personalizado\">Esas medidas</mark> <mark class=\"m-accion\">incluirán</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, según los sistemas nacionales adecuados y de conformidad con su legislación interna,</span></span> <mark class=\"m-personalizado\">en particular la ayuda <u class=\"m-clave\">económica</u> y la <u class=\"m-clave\">indemnización</u> a las víctimas del terrorismo y a sus familiares</mark> próximos.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 14 y 15 — Competencia y deber de investigación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 14.</b> 1. <mark class=\"m-personalizado\">Cada Parte</mark> <mark class=\"m-accion\">adoptará</mark> las medidas <mark class=\"m-destacable\">necesarias</mark> <mark class=\"m-personalizado\">para establecer su</mark> <mark class=\"m-destacable\">competencia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con respecto a todo delito tipificado de conformidad con el presente Convenio</span></span>: a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1217\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando se haya cometido el delito en su territorio</mark>; b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1217\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando se haya cometido el delito a bordo de un buque con pabellón de esa Parte</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">a bordo de una</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">aeronave</mark></span> matriculada en <mark class=\"m-personalizado\">esa Parte;</mark> c) cuando haya <mark class=\"m-personalizado\">cometido</mark> el delito uno <mark class=\"m-personalizado\">de sus nacionales</mark>.</p><p data-ex=\"EX\"><b>2.</b> <mark class=\"m-autoridad\">Cada Parte</mark> <mark class=\"m-accion\">podrá</mark> asimismo <mark class=\"m-personalizado\">establecer su</mark> <mark class=\"m-destacable\">competencia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con respecto a todo delito tipificado de confor- midad con el presente Convenio</span></span>: a) cuando el delito tuviera como <mark class=\"m-personalizado\">finalidad o resultado la</mark> <mark class=\"m-autoridad\">comisión</mark> de un delito <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">previsto en el artículo 1 del presente Convenio,</span></span> <mark class=\"m-personalizado\">en</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">su territorio o contra uno</u></mark> <mark class=\"m-personalizado\">de sus nacionales</mark>; b) cuando el delito tuviera como <mark class=\"m-personalizado\"><u class=\"m-clave\">finalidad</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">resultado</u> la</mark> <mark class=\"m-autoridad\">comisión</mark> de un delito <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">previsto en el artículo 1 del presente Convenio,</span></span> <mark class=\"m-personalizado\">contra una <u class=\"m-clave\">instalación</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">pública</u></mark> <mark class=\"m-personalizado\">de esa</mark> <mark class=\"m-autoridad\">Parte</mark> <mark class=\"m-personalizado\">situada <u class=\"m-clave\">fuera</u> de su territorio</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1219\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">incluidos los locales diplomáticos y consulares</mark>; (…)</p><p data-ex=\"EX\"><b>5.</b> Cuando <mark class=\"m-autoridad\">varias Partes</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">reivindiquen una</u></mark> competencia <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con respecto a un presunto delito previsto en el presente Convenio</span></span>, las Partes implicadas <mark class=\"m-resp r-ia\" data-q=\"2-ia-1221\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se pondrán de acuerdo</mark>, cuando sea oportuno, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1221\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">para determinar cuál de ellas está en mejores condiciones para ejercer las actuaciones correspondientes</mark>.</p><p><b>Art. 15.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">3. <mark class=\"m-autoridad\">Cualquier persona</mark> a cuyo respecto se adopten las <mark class=\"m-personalizado\">medidas</mark> (…) <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-destacable\">derecho a:</mark> a) <mark class=\"m-destacable\">comunicarse sin</mark> demora con el <mark class=\"m-personalizado\">representante</mark> competente más próximo del <mark class=\"m-autoridad\">Estado</mark> del que sea nacional (…);</span></span> b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1223\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">recibir la visita de un representante de ese Estado</mark>; <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">c) <mark class=\"m-destacable\">ser informada de los derechos</mark> que le confieren los <mark class=\"m-personalizado\">puntos a) y b).</mark> 5. (…) <mark class=\"m-personalizado\"><u class=\"m-clave\">invitar</u> al</mark> <mark class=\"m-autoridad\">Comité Internacional de la Cruz Roja</mark> a <mark class=\"m-destacable\">comunicarse</mark> con el presunto autor del delito <mark class=\"m-destacable\">y a visitarlo</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1224\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Arts. 16 a 19 — Ámbito, cooperación y extradición</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Cooperación penal entre <mark class=\"m-autoridad\">las Partes</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><b>Art. 16 — NO se aplica</b> <mark class=\"m-personalizado\">si</mark> el <u class=\"m-clave\">delito</u> <mark class=\"m-personalizado\">se comete</mark> dentro de un único <mark class=\"m-autoridad\">Estado</mark>, el presunto <mark class=\"m-personalizado\">autor</mark> es <u class=\"m-clave\">nacional</u> de ese <mark class=\"m-autoridad\">Estado</mark> y está en su territorio, y ningún otro <mark class=\"m-autoridad\">Estado</mark> tiene razones para <mark class=\"m-personalizado\">ser</mark> competente (sí se aplican los arts. 17 y 20 a 22)</div><div class=\"vis-rama\"><b>Art. 17</b> — <mark class=\"m-personalizado\">La asistencia más amplia posible</mark>; <u class=\"m-clave\">sin</u> tratado, de conformidad con su legislación interna</div><div class=\"vis-rama\"><b>Art. 18 — Extraditar o juzgar:</b> <mark class=\"m-personalizado\">si</mark> <mark class=\"m-personalizado\">no</mark> <mark class=\"m-destacable\">extradita</mark>, somete <mark class=\"m-personalizado\">el asunto</mark> <u class=\"m-clave\">sin</u> dilación excesiva a sus <mark class=\"m-autoridad\">autoridades</mark> para la <mark class=\"m-personalizado\">acción penal</mark> · basta la <mark class=\"m-destacable\">entrega condicional</mark> del <u class=\"m-clave\">nacional</u> a condición de que le <mark class=\"m-personalizado\">sea</mark> entregado para cumplir la pena impuesta</div><div class=\"vis-rama\"><b>Art. 19</b> — <mark class=\"m-personalizado\">Los delitos</mark> de los arts. 5 a 7 y 9 son de <u class=\"m-clave\">pleno</u> <mark class=\"m-personalizado\">derecho</mark> <mark class=\"m-plazo\"><u class=\"m-clave\">casos</u> de extradición</mark>; el <mark class=\"m-destacable\">Convenio</mark> puede servir de base jurídica</div></div></div></div><div class=\"ex-linea\">Artículos 16 y 17 — <mark class=\"m-personalizado\">No</mark> aplicabilidad del <mark class=\"m-destacable\">Convenio</mark> y cooperación internacional en materia penal: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1227\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 18 y 19 — Extradición o iniciación de actuaciones penales y extradición <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>Art. 18.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 18. EXTRADICIÓN O INICIACIÓN DE ACTUACIONES PENALES. 1. E\u0007 n los casos en que sea competente en virtud del artículo 14,</span></span> <mark class=\"m-autoridad\">aquella Parte</mark> <mark class=\"m-personalizado\">en cuyo territorio se encuentre</mark> el presunto <mark class=\"m-personalizado\">autor</mark> del delito <mark class=\"m-accion\">vendrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">obligada</u></mark>, en el <mark class=\"m-personalizado\">caso</mark> de que no <mark class=\"m-personalizado\">proceda a su extradición</mark>, <mark class=\"m-personalizado\">a someter</mark> el asunto <mark class=\"m-personalizado\">sin</mark> dilación excesiva y sin aplicar excepción alguna <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, haya sido o no cometido el delito dentro de su territorio,</span></span> <mark class=\"m-personalizado\">a sus</mark> <mark class=\"m-autoridad\">autoridades competentes</mark> para el ejercicio de la <mark class=\"m-personalizado\">acción penal</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en virtud de un procedimiento conforme a la legislación de esa Parte. Dichas autoridades adoptarán su decisión en las mismas condiciones que para cualquier otro delito de carácter grave en virtud de las leyes de esa Parte</span></span>. 2. Siempre que <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en virtud de su legislación interna,</span></span> <mark class=\"m-autoridad\">una Parte sólo esté</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">autorizada</u></mark> a extraditar o a entregar <mark class=\"m-personalizado\">a uno de</mark> sus nacionales <mark class=\"m-resp r-ia\" data-q=\"2-ia-1616,2-ia-1925\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a condición de que el interesado le sea entregado para cumplir la pena impuesta de resultas de un proceso o de unas diligencias en los que se haya solicitado la extradición</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o la entrega, y que dicha Parte y la Parte que solicita la extradición acepten dicha opción y las demás condiciones que puedan considerar adecuadas</span></span>, la extradición o la <mark class=\"m-destacable\">entrega condicional</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">suficientes para dispensar</mark> a la Parte requerida de <mark class=\"m-personalizado\">la obligación</mark> prevista en el <mark class=\"m-personalizado\">apartado 1.</mark> <mark class=\"m-resp ex-q\" data-q=\"2-93,2-ia-1229,2-ia-1230\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 3 preguntas</mark></p><p><b>Art. 19.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-personalizado\">Los delitos</mark> previstos en <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">los <span class=\"ref-art\">artículos 5</span> <span class=\"m-caja\">a 7 y</span> 9 (…) se <mark class=\"m-accion\">considerarán</mark> de pleno derecho como <mark class=\"m-plazo\">casos de extradición</mark> en cualquier tratado de extradición (…). 2. (…) <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Parte</mark> requerida <mark class=\"m-accion\">tendrá</mark> la <mark class=\"m-personalizado\">facultad de considerar</mark> <mark class=\"m-destacable\">el presente Convenio como base jurídica</mark> <mark class=\"m-personalizado\">constitutiva de la extradición</mark> (…).</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1232\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 20 — Exclusión de la cláusula de excepción política · R7 <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\">Ninguno de</mark> los delitos mencionados en <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">los <mark class=\"m-personalizado\"><span class=\"ref-art\">artículos 5 a 7 y 9</span></mark> (…) se</span></span> <mark class=\"m-accion\">considerará,</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">a</mark></span> <mark class=\"m-personalizado\">efectos de los requisitos necesarios para la extradición o la asistencia judicial</mark>, <mark class=\"m-personalizado\">como</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1234\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">delito político o como delito conexo a un delito político, o como un delito inspirado por móviles políticos</mark>. (…)</p><p data-ex=\"*\"><b>2.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">S\u0007 in perjuicio de la aplicación de los artículos 19 a 23 de la Convención de Viena sobre el derecho de los tratados, de 23 de mayo de 1969, a los demás artículos del presente Convenio,</span></span> <mark class=\"m-autoridad\">cualquier Estado,</mark> o la Comunidad Europea, <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">declarar</u></mark>, en el momento de la firma o del depósito de su instrumento <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de ratificación, aceptación, aprobación o adhesión al Convenio</span></span>, <mark class=\"m-personalizado\">que se</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">reservan</u></mark> <mark class=\"m-personalizado\">el derecho de no <u class=\"m-clave\">aplicar</u> el apartado 1</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de este artículo</span></span> <mark class=\"m-personalizado\">a la extradición</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">relacionada con cualquiera de los delitos que se mencionan en el presente Convenio</span></span>. La Parte <mark class=\"m-personalizado\">se compromete a aplicar esta reserva</mark> <mark class=\"m-resp\" data-q=\"2-159\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">caso por caso, sobre la base de una decisión debidamente motivada</mark>.</p><p><b>3.</b> Cualquiera de las Partes <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">retirar</u></mark>, <mark class=\"m-personalizado\">total <u class=\"m-clave\">o</u> parcialmente</mark>, <mark class=\"m-personalizado\">una</mark> <mark class=\"m-destacable\">reserva</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">formulada en virtud del apartado 2</span></span>, por medio de una <mark class=\"m-personalizado\">declaración dirigida</mark> <mark class=\"m-resp\" data-q=\"2-15,2-85,2-97,2-ia-1140,2-ia-1236,2-ia-1253,2-ia-1911,2-ia-1926\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">al Secretario General del Consejo de Europa, que entrará en vigor en la fecha de su recepción</mark>.</p><p><b>5.</b> <mark class=\"m-destacable\">Las reservas</mark> formuladas <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">válidas por un</mark> <mark class=\"m-plazo\">período de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1051\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">tres años</mark> <mark class=\"m-plazo\">a</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"m-caja\"><mark class=\"m-plazo\">partir</mark></span> <mark class=\"m-plazo\">del primer día de la entrada en vigor del presente Convenio</mark> para la Parte de que se trate.</span></span>  No obstante, dichas reservas <mark class=\"m-resp r-ia\" data-q=\"2-ia-1237\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">podrán ser renovadas por períodos de igual duración</mark>.</p><p data-ex=\"*\"><b>6.</b> <mark class=\"m-plazo\">Doce meses antes de la expiración</mark> de la reserva, <mark class=\"m-autoridad\">el Secretario General del Consejo</mark> <mark class=\"m-personalizado\">de</mark> Europa <mark class=\"m-accion\">informará</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1312\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a la Parte de que se trate</mark> de dicha expiración. Tres meses antes de la fecha de expiración, la Parte <mark class=\"m-accion\">deberá</mark> notificar al <mark class=\"m-autoridad\">Secretario</mark> General <mark class=\"m-resp\" data-q=\"2-160\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">su intención de mantener, modificar o retirar la reserva</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Cuando una Parte notifique al Secretario General que mantendrá su reserva, proporcionará explicaciones sobre los motivos que justifican su mantenimiento.</span></span> <mark class=\"m-personalizado\">A falta de notificación</mark> por la Parte de que se trate, el <mark class=\"m-autoridad\">Secretario</mark> General <mark class=\"m-resp\" data-q=\"2-161,2-ia-1238,2-ia-1239,2-ia-1714\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">informará a dicha Parte de que su reserva queda automáticamente prorrogada por un período de seis meses</mark>. <mark class=\"m-personalizado\">Si la Parte afectada no notifica su decisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de mantener o modificar sus reservas</span></span> <mark class=\"m-personalizado\">antes de la expiración de</mark> ese período, la reserva <mark class=\"m-accion\">quedará</mark> <mark class=\"m-personalizado\">sin efecto</mark>.</p><p><b>8.</b> (…) <mark class=\"m-personalizado\">Si no se adopta ninguna decisión judicial</mark> sobre el fondo del asunto <mark class=\"m-personalizado\">en</mark> <mark class=\"m-autoridad\">la Parte requerida</mark> (…) dentro de un plazo razonable, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1240\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la Parte requirente podrá informar de ello al Secretario General del Consejo de Europa, que someterá la cuestión a la Consulta entre las Partes</mark> prevista en el <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 30</span>.</mark> Esta Consulta <mark class=\"m-accion\">examinará</mark> la cuestión, <mark class=\"m-personalizado\">emitiendo un</mark> <mark class=\"m-destacable\">dictamen</mark> (…) <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u> lo</mark> <mark class=\"m-accion\">someterá</mark> <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp\" data-q=\"2-124\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Comité de Ministros</mark> con el <mark class=\"m-personalizado\">fin de que adopte una</mark> <mark class=\"m-destacable\">declaración</mark> al respecto (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 21 y 22 — Cláusula de discriminación e información espontánea <span class=\"ex-sello ex-sello-r\">R7</span></div><div class=\"ex-fb\"><p data-r=\"R7\"><span class=\"ex-sello ex-sello-r\">R7</span> <b>Art. 21.</b> 1. <mark class=\"m-personalizado\">Ninguna disposición</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Convenio se interpretará en el sentido de que</span></span> implique una <mark class=\"m-personalizado\"><u class=\"m-clave\">obligación</u> de <u class=\"m-clave\">extraditar</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">de conceder la asistencia judicial</mark>, si la Parte requerida tiene <mark class=\"m-destacable\">serias razones</mark> para considerar que la demanda <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de extradición motivada por un delito de los previstos en los artículos 5 a 7 y 9, o de asistencia judicial con respecto a tales delitos,</span></span> <mark class=\"m-personalizado\">ha sido presentada para</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">perseguir o</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">castigar</u> a una persona</mark> por consideraciones de <mark class=\"m-destacable\"><u class=\"m-clave\">raza,</u></mark> <mark class=\"m-personalizado\">religión, nacionalidad, origen étnico o de opiniones políticas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, o que la situación de dicha persona corra el riesgo de agravarse por una u otra de dichas razones</span></span>. <mark class=\"m-personalizado\">2.</mark> (…) <mark class=\"m-personalizado\">si la</mark> persona <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">objeto de la demanda de extradición</span></span> corre el <mark class=\"m-personalizado\">riesgo de quedar expuesta a la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">tortura</u></mark> <mark class=\"m-personalizado\">o a penas o</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">tratos inhumanos o</u> degradantes</mark>. 3. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">N\u0007 inguna disposición del presente Convenio se interpretará en el sentido de que implique una obliga- ción de extraditar</span></span> si la persona <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">objeto de la demanda de extradición</span></span> corre el riesgo de que <mark class=\"m-personalizado\">se le imponga la</mark> <mark class=\"m-destacable\">pena de muerte</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">o,</u></mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1043\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando la ley de la Parte requerida no permita la pena privativa de libertad a perpetuidad</mark>, <mark class=\"m-personalizado\">de que se le imponga</mark> la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1244\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">pena privativa de libertad a perpetuidad sin posibilidad de remisión</mark> <mark class=\"m-personalizado\">de la pena</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">a menos</u></mark> que la Parte requerida tenga la obligación <mark class=\"m-personalizado\">de</mark> extraditar <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">conforme a los tratados de extradición aplicables</span></span>, <u class=\"m-clave\">si la</u> Parte requirente <mark class=\"m-personalizado\">proporciona</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1847\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">garantías consideradas suficientes</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por la Parte requerida de que no se impondrá la pena capital o, en el caso de que se imponga, la misma no será ejecutada, o de que la persona afectada no será sometida a una pena privativa de libertad a perpetuidad sin posibilidad de remisión de la pena</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-ia-1242,2-123,2-ia-1243,2-ia-2413\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 4 preguntas</mark></p><p><b>Art. 22.</b> 1. (…) las <mark class=\"m-autoridad\">autoridades</mark> competentes de una Parte <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">transmitir</u></mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1245\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sin necesidad de previa solicitud</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a las <mark class=\"m-autoridad\">autoridades</mark> competentes de otra Parte, <mark class=\"m-personalizado\"><u class=\"m-clave\">informaciones obtenidas</u> en el marco de su propia investigación</mark> (…) (información espontánea).</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">2. <mark class=\"m-autoridad\">La Parte que proporcione</mark> las informaciones <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">supeditar</u> su utilización</mark> (…) <mark class=\"m-personalizado\">a determinadas condiciones</mark> (…).</span></span> 3. <mark class=\"m-autoridad\">La Parte que reciba</mark> las informaciones <mark class=\"m-accion\">vendrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">obligada a respetar</u> dichas condiciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. <mark class=\"m-personalizado\">4.</mark> <mark class=\"m-accion\">No</mark> obstante, cualquiera de las Partes <mark class=\"m-accion\">podrá</mark> declarar</span></span> (…) que se <mark class=\"m-destacable\">reserva el derecho</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1246\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no someterse a las condiciones</mark> (…), <mark class=\"m-resp r-ia r-vec\" data-q=\"2-ia-1246\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a menos que se le notifique previamente la naturaleza de la información que se vaya a facilitar y que acepte que se le transmita esta última</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 23, 24 y 25 — Firma, entrada en vigor, adhesión y aplicación territorial <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>Art. 23.</b> <mark class=\"m-destacable\">1.</mark> El presente <mark class=\"m-destacable\">Convenio</mark> <mark class=\"m-accion\">quedará</mark> <mark class=\"m-personalizado\">abierto a la firma</mark> de los <span class=\"m-caja\"><mark class=\"m-autoridad\">Estados</mark></span> <span class=\"m-caja\">miembros</span> del <mark class=\"m-autoridad\">Consejo</mark> de Europa, de la <mark class=\"m-personalizado\">Comunidad <u class=\"m-clave\">Europea</u> y</mark> de los <mark class=\"m-autoridad\"><u class=\"m-clave\">Estados</u></mark> no <mark class=\"m-personalizado\">miembros</mark> que hayan <mark class=\"m-personalizado\">participado en su elaboración</mark>. <mark class=\"m-personalizado\">2.</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007El presente Convenio estará sujeto a ratificación, aceptación o aprobación.</span></span> Los instrumentos de ratificación, aceptación o aprobación <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">depositados</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1248,2-ia-1251\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">en poder del Secretario General del Consejo de Europa</mark>. 3. El presente <mark class=\"m-personalizado\">Convenio</mark> <mark class=\"m-accion\">entrará</mark> en <mark class=\"m-destacable\">vigor:</mark> <mark class=\"m-resp\" data-q=\"2-94,2-95,2-ia-1132,2-ia-1133,2-ia-1249,2-ia-1908\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el primer día del mes siguiente a la expiración de un período de tres meses después de la fecha en que seis Signatarios, de los que al menos cuatro deberán ser miembros del Consejo de Europa</mark>, <mark class=\"m-plazo\">hayan expresado su</mark> consentimiento <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en quedar vinculados por el presente Convenio, conforme a lo dispuesto en el apartado 2</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1247\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b>Art. 24.</b> 1. <span class=\"m-caja\"><mark class=\"m-plazo\">Después</mark></span> <mark class=\"m-plazo\">de la entrada en vigor del presente Convenio</mark>, <mark class=\"m-destacable\">el</mark> <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-destacable\">de</mark> <mark class=\"m-autoridad\">Ministros del Consejo de Europa</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-autoridad\">invitar a todo Estado que</mark> no sea miembro del <mark class=\"m-autoridad\">Consejo</mark> de Europa y que no haya participado en la elaboración del Convenio, previa consulta <mark class=\"m-plazo\">a las Partes</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en el presente Convenio</span></span> <mark class=\"m-plazo\">y</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1250\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">después de haber obtenido su consentimiento unánime</mark>, a adherirse al presente Convenio. La decisión se <mark class=\"m-accion\">adoptará</mark> por la mayoría prevista en el <span class=\"ref-art\">artículo 20.d)</span> del Estatuto del <mark class=\"m-autoridad\">Consejo</mark> de Europa y por unanimidad de los representantes <mark class=\"m-autoridad\">de las</mark> Partes <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que tengan derecho a estar representadas en el Comité de Ministros</span></span>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">P\u0007 ara cualquier Estado que se adhiera al Convenio en virtud del apartado 1 anterior, el Convenio entrará en vigor</span></span> <mark class=\"m-accion\">el</mark> primer <mark class=\"m-destacable\">día</mark> <mark class=\"m-plazo\">del</mark> <mark class=\"m-personalizado\">mes</mark> <mark class=\"m-plazo\">siguiente a la expiración de un período de tres meses después de la fecha de depósito del instrumento de adhesión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en poder del Secretario General del Consejo de Europa</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-96\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b><mark class=\"m-plazo\">Art. 25.</mark></b> <mark class=\"m-plazo\">2. Todo</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-accion\">podrá</mark> ampliar la aplicación del presente Convenio <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en cualquier momento posterior y mediante declaración dirigida al Secretario General del Consejo de Europa,</span></span> a cualquier otro territorio <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">designado en la declaración</span></span>. El Convenio <mark class=\"m-accion\">entrará</mark> en <mark class=\"m-plazo\">vigor con respecto a</mark> dicho territorio el primer día del mes siguiente <mark class=\"m-plazo\">a</mark> la <mark class=\"m-plazo\">expiración de un período de tres meses</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">después de la fecha de recepción de la declaración por parte del Secretario General</span></span>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 26 — Efectos del Convenio</div><div class=\"ex-fb\"><p><b>1.</b> El objeto del presente Convenio <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">es <mark class=\"m-personalizado\">completar los tratados o acuerdos</mark> (…) <mark class=\"m-personalizado\">existentes entre</mark> <mark class=\"m-autoridad\">las Partes,</mark> incluidas las disposiciones de los tratados</span></span> del <mark class=\"m-autoridad\">Consejo</mark> de Europa siguientes: <mark class=\"m-resp r-ia\" data-q=\"2-ia-1304\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Convenio europeo de extradición</mark> (París, 13-12-1957); <mark class=\"m-resp r-ia\" data-q=\"2-ia-1302\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Convenio europeo de asistencia judicial en materia penal</mark> (Estrasburgo, 20-4-1959); <mark class=\"m-resp r-ia\" data-q=\"2-ia-1303\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Convenio europeo para la represión del terrorismo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(Estrasburgo, 27-1-1977); y sus Protocolos (1978, 2001 y 2003).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1301\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>3.</b> Las Partes que sean miembros de la Unión Europea <mark class=\"m-accion\">aplicarán,</mark> en sus relaciones recíprocas, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1305,2-ia-2157\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">las normas de la Comunidad y de la Unión Europea en la medida en que existan normas (…) que rijan el tema en concreto</mark> (…).</p><p><b>5.</b> Las actividades de las fuerzas armadas <mark class=\"m-personalizado\">en período</mark> de conflicto <mark class=\"m-personalizado\">armado</mark>, en el sentido <u class=\"m-clave\">dado</u> (…) por el <mark class=\"m-resp\" data-q=\"2-17\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">derecho internacional humanitario</mark>, que se rijan por dicho derecho, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1306,2-ia-1307\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no se regirán por el presente Convenio</mark> (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 27 y 28 — Enmiendas al Convenio y revisión del anexo · R8 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R8</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\" data-r=\"R8\"><span class=\"ex-sello ex-sello-r\">R8</span> <b>Art. 27.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-accion\">Podrán</mark> proponerse enmiendas al presente Convenio por <mark class=\"m-resp\" data-q=\"2-124,2-ia-1308,2-ia-1309\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cualquiera de las Partes, por el Comité de Ministros del Consejo de Europa o por la Consulta entre las Partes</mark>. 2. <mark class=\"m-personalizado\">Toda propuesta</mark> de enmienda <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">comunicada</mark> <mark class=\"m-autoridad\">a las Partes por el Secretario General del Consejo de Europa</mark>. 3. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">A\u0007 demás,</span></span> toda enmienda <mark class=\"m-personalizado\">propuesta por una Parte o</mark> por el <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">trasladada a</mark> la Consulta entre <mark class=\"m-autoridad\">las Partes</mark>, <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">someterá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-personalizado\">su</mark> <mark class=\"m-destacable\">dictamen</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">acerca de la enmienda propuesta</span></span>. 4. El <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-accion\">examinará</mark> la enmienda propuesta <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y cualquier dictamen sometido por la Consulta entre las Partes</span></span>, pudiendo aprobar la enmienda. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">5. E\u0007 l texto de toda enmienda aprobada por el Comité de Ministros conforme al apartado 4 será transmitido a las Partes para obtener su aceptación.</span></span> 6. Toda <mark class=\"m-destacable\">enmienda</mark> aprobada <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en virtud del apartado 4</span></span> <mark class=\"m-accion\">entrará</mark> en vigor <mark class=\"m-resp r-ia\" data-q=\"2-ia-1310\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el trigésimo día siguiente a la fecha en que todas las Partes hayan comunicado su aceptación</mark> al <mark class=\"m-autoridad\">Secretario General</mark>.</p><p><b>Art. 28.</b> 1. Con <mark class=\"m-personalizado\">el fin de <u class=\"m-clave\">actualizar</u> la lista de tratados en el anexo,</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">proponerse</mark> <mark class=\"m-destacable\">enmiendas</mark> por <mark class=\"m-resp\" data-q=\"2-13,2-83\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cualquiera de las Partes o por el Comité de Ministros</mark>. Estas propuestas de enmiendas <mark class=\"m-personalizado\">sólo</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">afectar a</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1311\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">tratados universales concluidos dentro del sistema de las Naciones Unidas, referidos específicamente al terrorismo internacional y que se encuentren vigentes</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Serán comunicadas a las Partes por el Secretario General del Consejo de Europa</span></span>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">D\u0007 espués de haber consultado a las Partes que no sean miembros,</span></span> <mark class=\"m-autoridad\">el Comité de</mark> <mark class=\"m-accion\">Ministros podrá</mark> <mark class=\"m-destacable\">aprobar una enmienda</mark> propuesta por la mayoría prevista en el <span class=\"ref-art\">artículo 20.d)</span> del Estatuto del <mark class=\"m-autoridad\">Consejo</mark> de Europa. Esta enmienda <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor</mark> <mark class=\"m-plazo\">a la expiración de un período de</mark> un año a partir de <mark class=\"m-plazo\">la fecha en que haya</mark> sido transmitida a las Partes <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">. Durante dicho plazo, cualquiera de las Partes podrá notificar al Secretario General del Consejo de Europa una objeción contra la entrada en vigor de la enmienda con respecto a ella</span></span></span>. 3. <mark class=\"m-plazo\">Si</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1312\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">un tercio de las Partes</mark> <mark class=\"m-personalizado\">hubiera notificado</mark> al <mark class=\"m-autoridad\">Secretario</mark> General una objeción <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">contra la entrada en vigor de la enmienda</span></span>, <mark class=\"m-personalizado\">ésta</mark> <mark class=\"m-destacable\">no</mark> <mark class=\"m-accion\">entrará</mark> <mark class=\"m-destacable\">en vigor.</mark> 4. <mark class=\"m-personalizado\">Si <u class=\"m-clave\">menos de un tercio</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de las Partes hubiera notificado una objeción,</span></span> la enmienda <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor con respecto a</mark> <mark class=\"m-autoridad\">las Partes</mark> que <mark class=\"m-personalizado\">no hubieran <u class=\"m-clave\">formulado</u> una objeción</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 29, 30 y 31 — Solución de controversias, Consulta entre las Partes y denuncia · R9 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R9</span></div><div class=\"ex-fb\"><p><b>Art. 29.</b> En caso de que exista <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">controversia</mark> (…), las mismas se <mark class=\"m-accion\">esforzarán</mark> por conseguir una <mark class=\"m-personalizado\">solución</mark> de sus divergencias <mark class=\"m-personalizado\">por medio de la</mark> <mark class=\"m-destacable\">negociación o</mark> <mark class=\"m-personalizado\">por cualquier otro</mark> <mark class=\"m-destacable\">medio pacífico</mark> que prefieran, <mark class=\"m-personalizado\"><u class=\"m-clave\">incluida</u> la sumisión</mark></span></span> de la controversia a <mark class=\"m-autoridad\">un</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1314\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">tribunal de arbitraje</mark> <mark class=\"m-autoridad\">cuyas decisiones</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-autoridad\">vinculantes para las Partes,</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1314\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">o al Tribunal Internacional de Justicia</mark>, <mark class=\"m-autoridad\">en virtud de</mark> un acuerdo común entre las Partes afectadas.</p><p data-ex=\"*\"><b>Art. 30.</b> 1. <mark class=\"m-autoridad\">Las Partes</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">consultarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">periódicamente</u> con el fin de:</mark> a) <mark class=\"m-personalizado\">efectuar <u class=\"m-clave\">propuestas</u> para <u class=\"m-clave\">facilitar o mejorar</u> la utilización y la aplicación efectivas del presente Convenio</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, incluida la identificación de cualquier problema en la materia, así como los efectos de toda declaración efectuada en virtud del presente Convenio</span></span>; b) <mark class=\"m-personalizado\">formular su <u class=\"m-clave\">opinión</u> sobre la conformidad de una negativa de extradición</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que les sea sometida en virtud</span></span> del apartado 8 del <span class=\"ref-art\">artículo 20</span>; c) <mark class=\"m-personalizado\">efectuar propuestas de enmiendas</mark> (…) (<span class=\"ref-art\">art. 27</span>); d) formular su opinión sobre cualquier propuesta de enmienda <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">al presente Convenio que les sea sometida en virtud del apartado 3 del artículo 27</span></span><span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">; e) expresar una opinión sobre cualquier cuestión relativa a la aplicación</span></span> del presente Convenio <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y facilitar el intercambio de información acerca de los avances jurídicos, políticos o técnicos importantes</span></span>. 2. La Consulta entre las Partes <mark class=\"m-accion\">será</mark> convocada por el <mark class=\"m-resp\" data-q=\"2-162,2-ia-1316\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretario General del Consejo de Europa cada vez que lo considere necesario y, en cualquier caso, si lo solicita la mayoría de las Partes o el Comité de Ministros</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1315\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"*\" data-r=\"R9\"><span class=\"ex-sello ex-sello-r\">R9</span> <b>Art. 31.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-autoridad\">Toda Parte</mark> <mark class=\"m-accion\">podrá</mark> denunciar <mark class=\"m-resp\" data-q=\"2-125\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">en cualquier momento</mark> el presente Convenio <mark class=\"m-personalizado\">mediante notificación</mark> enviada <mark class=\"m-autoridad\">al Secretario General del Consejo de Europa</mark>. 2. La denuncia <mark class=\"m-accion\">entrará</mark> en <mark class=\"m-destacable\">vigor</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1254,2-ia-1317\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el primer día del mes siguiente a la expiración de un período de tres meses después de la fecha de recepción de la notificación</mark> por el <mark class=\"m-autoridad\">Secretario</mark> General.</p><p data-ex=\"*\">Hecho en <mark class=\"m-resp\" data-q=\"2-163\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Varsovia el 16 de mayo de 2005</mark>, en <mark class=\"m-resp\" data-q=\"2-163\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">francés y en inglés</mark>, siendo igualmente auténticos ambos textos <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en un solo ejemplar que será depositado en los archivos del Consejo de Europa. El Secretario General del Consejo de Europa transmitirá copia conforme del mismo a cada uno de los Estados miembros del Consejo de Europa, a la Comunidad Europea, a los Estados no miembros que hayan participado en la elaboración del presente Convenio, así como a todo Estado que haya sido invitado a adherirse al mismo. Copia certificada conforme al ejemplar original único, en lenguas francesa e inglesa, depositado en los archivos del Consejo de Europa. Estrasburgo, 22 de septiembre de 2005. El Director General de Asuntos Jurídicos del Consejo de Europa, Guy De Vel</span></span>.</p></div></div><div class=\"bloque-titulo\">2.3 — LEY 10/2010, DE 28 DE ABRIL, DE <mark class=\"m-personalizado\">PREVENCIÓN DEL BLANQUEO DE</mark> <mark class=\"m-personalizado\">CAPITALES Y DE</mark> <mark class=\"m-destacable\">LA FINANCIACIÓN</mark> <mark class=\"m-personalizado\">DEL TERRORISMO</mark> (con la actualización del 30/09/2026: <mark class=\"m-personalizado\">Real</mark> Decreto-ley 25/2026, de 29 de septiembre)</div><div class=\"ex-linea\">🆕 Nueva actualización del 30/09/2026 — Qué cambia en <mark class=\"m-personalizado\">la Ley</mark> 10/2010: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1942,2-ia-1301\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas más de este artículo</mark></div><div class=\"bloque-titulo\">CAPÍTULO I. DISPOSICIONES GENERALES</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 1 — Objeto, definiciones y ámbito de aplicación · R10 <span class=\"ex-sello ex-sello-r\">R10</span></div><div class=\"ex-fb\"><p><b>1.</b> La presente Ley tiene por objeto la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1330\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">protección de la integridad del sistema financiero y de otros sectores de actividad económica</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">mediante el establecimiento</mark> de obligaciones de prevención del blanqueo de <mark class=\"m-personalizado\">capitales y de</mark> <mark class=\"m-destacable\">la financiación</mark> <mark class=\"m-personalizado\">del terrorismo</mark></span></span> .</p><p><b>2.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) se <span class=\"m-caja\"><mark class=\"m-accion\">considerarán</mark></span> <mark class=\"m-destacable\">blanqueo</mark> de capitales las <mark class=\"m-personalizado\">siguientes actividades</mark>:</span></span> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1332,2-ia-1333,2-ia-1344,2-ia-1462,2-ia-2016\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">La conversión o la transferencia de bienes, a sabiendas de que dichos bienes proceden de una actividad delictiva</mark> <mark class=\"m-personalizado\">o de la participación en una actividad delictiva</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1331,2-ia-2020\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">con el propósito de ocultar o encubrir el origen ilícito de los bienes o de ayudar a personas que estén implicadas a eludir las consecuencias jurídicas de sus actos</mark>. b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1806,2-ia-1918\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">La ocultación o el encubrimiento de la naturaleza, el origen, la localización, la disposición, el movimiento o la propiedad real de bienes</mark> o derechos sobre bienes, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a sabiendas de que <mark class=\"m-personalizado\">dichos bienes</mark> proceden de una actividad delictiva (…).</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">c) <mark class=\"m-destacable\">La adquisición, posesión</mark> <mark class=\"m-personalizado\">o</mark> <mark class=\"m-destacable\">utilización de bienes,</mark> <mark class=\"m-personalizado\">a sabiendas</mark>, <mark class=\"m-personalizado\">en el momento de</mark> la recepción de <mark class=\"m-personalizado\">los</mark> mismos, <mark class=\"m-personalizado\">de que proceden</mark> de una actividad delictiva (…).</span></span> d) <mark class=\"m-destacable\">La participación</mark> en alguna de las <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">actividades mencionadas (…), la asociación</span></span> <mark class=\"m-personalizado\">para cometer</mark> este tipo de actos, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1112,2-ia-1703,2-ia-2152\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">las tentativas de perpetrarlas</mark> y <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">el hecho de <mark class=\"m-personalizado\">ayudar, instigar o aconsejar a</mark> alguien <mark class=\"m-personalizado\">para realizarlas o facilitar</mark> su ejecución.</span></span></p><p>A los efectos de esta Ley se <mark class=\"m-accion\">entenderá</mark> por bienes procedentes de una actividad delictiva <mark class=\"m-resp r-ia\" data-q=\"2-ia-2037\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">todo tipo de activos cuya adquisición o posesión tenga su origen en un delito, tanto materiales como inmateriales</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">muebles o inmuebles, tangibles o intangibles, así como los documentos o instrumentos jurídicos</span></span> (…), con inclusión de la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1334\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuota defraudada</mark> en <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">el caso de los delitos contra la Hacienda Pública.</span></span></p><p>Se <mark class=\"m-accion\">considerará</mark> que hay blanqueo de capitales <mark class=\"m-resp r-ia\" data-q=\"2-ia-2161\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">aun cuando las actividades que hayan generado los bienes se hubieran desarrollado en el territorio de otro Estado</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1447\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>3.</b> (…) se <mark class=\"m-accion\">entenderá</mark> por financiación del terrorismo <mark class=\"m-resp r-ia\" data-q=\"2-ia-1406,2-ia-2332\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el suministro, el depósito, la distribución o la recogida de fondos o bienes, por cualquier medio</mark>, de forma directa o indirecta, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1843\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">con la intención de utilizarlos o con el conocimiento de que serán utilizados</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">íntegramente o en parte, para la <mark class=\"m-autoridad\">comisión</mark> de cualquiera de los delitos de terrorismo tipificados en el Código Penal.</span></span>  Se <mark class=\"m-accion\">considerará</mark> que existe financiación del terrorismo <mark class=\"m-resp r-ia\" data-q=\"2-ia-1336\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">aun cuando el suministro o la recogida de fondos o bienes se hayan desarrollado en el territorio de otro Estado</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1222,2-ia-1335,2-ia-1632,2-ia-2041\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 4 preguntas</mark></p><p data-r=\"R10\"><span class=\"ex-sello ex-sello-r\">R10</span> <b>4.</b> <mark class=\"m-accion\">Se considerarán</mark> <mark class=\"m-autoridad\">países terceros equivalentes</mark> aquellos <mark class=\"m-autoridad\">Estados</mark>, <mark class=\"m-autoridad\">territorios o jurisdicciones</mark> que, por establecer requisitos equivalentes a los de la legislación española, se <mark class=\"m-destacable\">determinen</mark> por la <mark class=\"m-autoridad\">Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</mark>, a propuesta de su <mark class=\"m-autoridad\">Secretaría</mark>. La calificación como <mark class=\"m-autoridad\">país tercero</mark> equivalente <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de un Estado, territorio o jurisdicción</span></span> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-resp\" data-q=\"2-23,2-99,2-ia-1338,2-ia-1659\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">en todo caso sin efecto retroactivo</mark>. La <mark class=\"m-resp\" data-q=\"2-9,2-80,2-ia-1339,2-ia-1660\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretaría General del Tesoro y Financiación Internacional</mark> <mark class=\"m-accion\">mantendrá</mark> en su página web una lista actualizada de los <mark class=\"m-autoridad\">Estados,</mark> territorios o jurisdicciones que gocen de <mark class=\"m-destacable\">la</mark> condición de país tercero equivalente. <mark class=\"m-resp ex-q\" data-q=\"2-126,2-ia-1460,2-ia-1540,2-ia-1665\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 4 preguntas</mark></p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> <b>5.</b> <mark class=\"m-accion\">Se entenderá</mark> <mark class=\"m-destacable\">por</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1408\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">criptoactivo</mark> <mark class=\"m-personalizado\">aquella</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1340\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">representación digital de un valor o de un derecho que puede transferirse y almacenarse electrónicamente, mediante la tecnología de registro distribuido o una tecnología similar</mark>, <mark class=\"m-destacable\">tal como se definen en el <span class=\"ref-art\">artículo 3.1</span>, punto 5, del</mark> <mark class=\"m-resp\" data-q=\"2-173\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Reglamento (UE) 2023/1114</mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Parlamento</mark> <mark class=\"m-destacable\">Europeo y del</mark> <mark class=\"m-autoridad\">Consejo,</mark> de <mark class=\"m-personalizado\">31 de mayo de 2023</mark>, <mark class=\"m-personalizado\">relativo a los mercados de criptoactivos</mark> (…), <mark class=\"m-personalizado\">excepto cuando</mark> <mark class=\"m-destacable\">entren</mark> en las categorías enumeradas en el <mark class=\"m-resp r-ia\" data-q=\"2-ia-1404\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\"><span class=\"ref-art\">artículo 2</span>, apartados 2, 3 y 4, de dicho Reglamento (UE) o cumplan los requisitos para ser considerados fondos</mark>.</p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 <mark class=\"m-destacable\">NUEVO</mark> · <mark class=\"m-destacable\">30/09/2026</mark></span> <b><mark class=\"m-destacable\">6.</mark></b> <mark class=\"m-destacable\">Se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-destacable\">por</mark> <mark class=\"m-resp\" data-q=\"2-164\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">proveedor de servicios de criptoactivos</mark> <mark class=\"m-personalizado\">aquella</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1341,2-ia-1401,2-ia-1435,2-ia-1523,2-ia-2156\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">persona jurídica u otra empresa cuya actividad o negocio consista en la prestación profesional de uno o varios servicios de criptoactivos a clientes y que está autorizada</mark> <mark class=\"m-destacable\">a prestar servicios de criptoactivos, tal</mark> como se definen en el <span class=\"ref-art\">artículo 3.1</span>, punto 15, del Reglamento (UE) 2023/1114 (…), cuando lleve a cabo uno o más servicios de criptoactivos tal como se definen en <mark class=\"m-destacable\">el</mark> <span class=\"ref-art\">artículo 3.1</span>, punto 16, de dicho Reglamento (UE), con la excepción de la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1408\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">prestación de asesoramiento sobre criptoactivos</mark> a <mark class=\"m-destacable\">que se refiere el <span class=\"ref-art\">artículo 3</span>, apartado</mark> 1, punto 16, letra h), de <mark class=\"m-destacable\">dicho Reglamento</mark> (UE). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1303,2-ia-1863\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 <mark class=\"m-personalizado\">NUEVO</mark> · <mark class=\"m-personalizado\">30/09/2026</mark></span> <b><mark class=\"m-personalizado\">7.</mark></b> <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1342\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">dirección autoalojada</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">aquella dirección definida en el</mark> <span class=\"ref-art\">artículo 3</span>, punto 20, del Reglamento (UE) 2023/1113 del <mark class=\"m-autoridad\">Parlamento</mark> Europeo y del <mark class=\"m-autoridad\">Consejo</mark> de 31 de mayo de 2023, relativo</span></span> a <mark class=\"m-personalizado\">la información que acompaña a las transferencias de fondos y de determinados criptoactivos y por el que</mark> se modifica la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1455\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Directiva (UE) 2015/849</mark>.</p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"2-45\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 2 — Sujetos obligados <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF,*\"><b>1.</b> La presente Ley <mark class=\"m-accion\">será</mark> de aplicación a los siguientes <mark class=\"m-accion\">sujetos obligados</mark>: a) Las <mark class=\"m-autoridad\">entidades de crédito</mark>. b) Las <mark class=\"m-autoridad\">entidades aseguradoras</mark> autorizadas para <mark class=\"m-destacable\">operar</mark> en el ramo de vida <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">u otros seguros rela cionados con inversiones y los corredores de seguros cuando actúen en relación con seguros de vida u otros servicios relacionados con inversiones, con las excepciones que se establezcan reglamentariamente</span></span>. c) Las <mark class=\"m-autoridad\">empresas de servicios de inversión</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">d) Las sociedades gestoras de instituciones de inversión colectiva y las sociedades de inversión cuya gestión no esté encomendada a una sociedad gestora. e) Las entidades gestoras de fondos de pensiones. f) Las sociedades gestoras de entidades de capital-riesgo y las sociedades de capital-riesgo cuya gestión no esté encomendada a una sociedad gestora. g) Las sociedades de garantía recíproca.</span></span> h) Las <mark class=\"m-autoridad\">entidades de dinero electrónico</mark>, las <mark class=\"m-autoridad\">entidades de pago</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y las personas físicas y jurídicas a las que se refieren los artículos 14 y 15 del Real Decreto Ley 19/2018, de 23 de noviembre, de servicios de pago y otras medidas urgentes en materia financiera</span></span>. i) <mark class=\"m-autoridad\">Las personas</mark> que ejerzan profesionalmente actividades de <mark class=\"m-autoridad\">cambio de moneda</mark>. j) Los <mark class=\"m-autoridad\">servicios</mark> postales respecto de las <mark class=\"m-personalizado\">actividades de giro o transferencia</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">k) \u0007Las personas dedicadas profesionalmente a la intermediación en la concesión de préstamos o créditos, así como aquellas que, sin haber obtenido la autorización como establecimientos financieros de crédito, desarrollen profesionalmente alguna actividad prevista en el artículo 6.1 de la Ley 5/2015, de 27 de abril, de fomento de la financiación empresarial, o desarrollen actividades de concesión de préstamos previstas en la Ley 5/2019, de 15 de marzo, reguladora de los contratos de crédito inmobiliario, así como las personas dedicadas profesionalmente a la intermediación en la concesión de préstamos o créditos.</span></span> l) Los promotores inmobiliarios <mark class=\"m-autoridad\">y quienes ejerzan profesionalmente actividades de agencia</mark>, <mark class=\"m-autoridad\">comisión o intermediación en la compraventa de</mark> bienes inmuebles o <mark class=\"m-destacable\">en arrendamientos</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de bienes inmuebles que impliquen una transacción</span></span> por una <mark class=\"m-personalizado\">renta total anual</mark> <mark class=\"m-destacable\">igual o superior a 120.000 euros</mark> o una <mark class=\"m-personalizado\">renta mensual</mark> <mark class=\"m-destacable\">igual o superior a 10.000 euros</mark>. m) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1102,2-ia-2203\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Los auditores de cuentas, contables externos, asesores fiscales</mark> y cualquier otra persona que se comprometa a prestar <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de manera directa o a través de otras personas relacionadas, ayuda material, asistencia o</span></span> asesoramiento en cuestiones <mark class=\"m-autoridad\">fiscales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">como actividad empresarial o profesional principal</span></span>. n) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1402,2-ia-1531,2-ia-1901,2-ia-2534\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Los notarios y los registradores de la propiedad, mercantiles y de bienes muebles</mark>. ñ) Los <mark class=\"m-autoridad\">abogados,</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">procuradores u otros profesionales independientes cuando participen en la concepción, realización o asesoramiento de operaciones por cuenta de clientes (…).</span></span> (…) p) Los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1412\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">casinos de juego</mark>. q) Las <mark class=\"m-autoridad\">personas que comercien profesionalmente con</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1405\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">joyas, piedras o metales preciosos</mark>. r) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1539,2-ia-1905\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Las personas que comercien profesionalmente con objetos de arte o antigüedades</mark> <mark class=\"m-accion\">o actúen</mark> <mark class=\"m-autoridad\">como intermediarios</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en el comercio de objetos de arte o antigüedades</span></span>, y <mark class=\"m-autoridad\">las personas</mark> <mark class=\"m-accion\">que almacenen o comercien</mark> con objetos de arte o antigüedades <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o actúen como intermediarios en el comercio de objetos de arte o antigüedades</span></span> cuando <mark class=\"m-destacable\">lo lleven a cabo</mark> en puertos francos. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">s) \u0007Las personas que ejerzan profesionalmente las actividades a que se refiere el artículo 1 de la Ley 43/2007, de 13 de diciembre, de protección de los consumidores en la contratación de bienes con oferta de restitución del precio. t) L\u0007 as personas que ejerzan actividades de depósito, custodia o transporte profesional de fondos o medios de pago.</span></span> u) Las <mark class=\"m-autoridad\">personas responsables</mark> de la <mark class=\"m-destacable\">gestión</mark>, <mark class=\"m-destacable\">explotación y comercialización</mark> de <mark class=\"m-personalizado\">loterías</mark> u otros <mark class=\"m-personalizado\">juegos de azar</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">presenciales o por medios electrónicos, informáticos, telemáticos e interactivos. En el caso de loterías, apuestas mutuas deportivo-benéficas, concursos, bingos y máquinas recreativas tipo “B” únicamente respecto de las <mark class=\"m-resp r-ia\" data-q=\"2-ia-1407\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">operaciones de pago de premios</mark></span></span>. v) Las <mark class=\"m-autoridad\">personas físicas que realicen movimientos de medios de pago</mark> (<span class=\"ref-art\">art. 34</span>). w) Las <mark class=\"m-autoridad\">personas que comercien</mark> <mark class=\"m-destacable\">profesionalmente</mark> <mark class=\"m-autoridad\">con bienes</mark> (<span class=\"ref-art\">art. 38</span>). x) Las <mark class=\"m-autoridad\">fundaciones y asociaciones</mark> (<span class=\"ref-art\">art. 39</span>). y) Los <mark class=\"m-autoridad\">gestores de sistemas de pago</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y de compensación y liquidación de valores y productos financieros derivados, así como los gestores de tarjetas de crédito o débito emitidas por otras entidades, en los términos establecidos en el artículo 40.</span></span> (<span class=\"ref-art\">art. 40</span>). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1103,2-ia-1105,2-ia-1403,2-ia-1431,2-ia-1547,2-ia-1617\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 6 preguntas</mark></p><p class=\"p-nuevo\" data-ex=\"EXOF,*\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> z) <mark class=\"m-resp\" data-q=\"2-164,2-ia-1408\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Los proveedores de servicios de criptoactivos</mark>.</p></div></div><div class=\"bloque-titulo\">CAPÍTULO II. DE LA DILIGENCIA DEBIDA</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 3 y 4 — Identificación formal e identificación del titular real</div><div class=\"ex-fb\"><p><b>Art. 3.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. Los sujetos obligados <mark class=\"m-accion\">identificarán</mark> a cuantas personas físicas o jurídicas pretendan establecer relaciones de negocio o intervenir en cualesquiera operaciones. En ningún caso los sujetos obligados <mark class=\"m-accion\">mantendrán</mark> relaciones de negocio o <mark class=\"m-accion\">realizarán</mark> operaciones con personas (…) que no hayan sido debidamente identificadas.</span></span> Queda prohibida, en particular, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1414\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la apertura, contratación o mantenimiento de cuentas, libretas de ahorro, cajas de seguridad, activos o instrumentos numerados, cifrados, anónimos o con nombres ficticios</mark>. 2. Con carácter previo al establecimiento de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">la relación de negocios (…), los sujetos obligados <mark class=\"m-accion\">comprobarán</mark></span></span> la identidad de los intervinientes <mark class=\"m-resp r-ia\" data-q=\"2-ia-1415\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">mediante documentos fehacientes</mark> (…). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1425,2-ia-2138\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>Art. 4.</b> 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">2. A\u0007 los efectos de la presente ley,</span></span> se <mark class=\"m-accion\">entenderá</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por titular real: a) la persona o personas físicas por cuya cuenta se pretenda establecer una</span></span> relación de negocios <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o intervenir en cualesquiera operaciones</span></span>; b) la <mark class=\"m-personalizado\">persona o</mark> personas <mark class=\"m-personalizado\">físicas</mark> que en último término posean o controlen, <mark class=\"m-destacable\">directa o indirectamente</mark>, un porcentaje <mark class=\"m-resp r-ia\" data-q=\"2-ia-1419\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">superior al 25 por ciento</mark> del capital o de los derechos de voto de una persona jurídica <span class=\"hueco-txt\">, o que por otros medios ejerzan el control, directo o indirecto, de una persona jurídica. b bis) Cuando no exista una persona física que posea o controle, directa o indirectamente, un porcentaje superior al 25 por ciento del capital o de los derechos de voto de la persona jurídica, o que por otros medios ejerza el control, directo o indirecto, de la persona jurídica, se considerará que ejerce dicho control el administrador o administradores. Cuando el administrador designado fuera una persona jurídica, se entenderá que el control es ejercido por la persona física nombrada por el administrador persona jurídica. Los sujetos obligados verificarán su identidad y consignarán las medidas tomadas y las dificultades encontradas durante el proceso de verificación</span>. c) En el caso de los <mark class=\"m-destacable\">fideicomisos,</mark> como <mark class=\"m-personalizado\">el trust anglosajón</mark>, <mark class=\"m-accion\">tendrán</mark> la consideración de <mark class=\"m-destacable\">titulares</mark> reales <mark class=\"m-resp\" data-q=\"2-64\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">todas las personas siguientes: 1.º el fideicomitente o fideicomitentes; 2.º el fiduciario o fiduciarios; 3.º el protector o protectores, si los hubiera; 4.º los beneficiarios</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o, cuando aún estén por designar, la categoría de personas en beneficio de la cual se ha creado o actúa la estructura jurídica</span></span>; <mark class=\"m-autoridad\">y</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1423,2-ia-1424\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">5.º cualquier otra persona física que ejerza en último término el control del fideicomiso</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a través de la propiedad directa o indirecta o a través de otros medios</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1128\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 4 bis — Información de titularidad real de personas jurídicas <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b>1.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Sin perjuicio de las obligaciones que les fueran exigibles por su normativa reguladora, las sociedades mercantiles, fundaciones, asociaciones y cuantas personas jurídicas estén sujetas a la obligación de declarar su titularidad real, constituidas conforme a la legislación española o con domicilio social o sucursal en España, están obligadas a obtener, conservar y actualizar la información del titular o los titulares reales de esa persona jurídica, de conformidad con los criterios establecidos en el artículo 4. La información de los</span></span> titulares reales se <mark class=\"m-accion\">conservará</mark> por un plazo de <mark class=\"m-resp r-ia\" data-q=\"2-ia-1427,2-ia-1430\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">10 años a contar desde <mark class=\"m-personalizado\">el cese de su condición de titular</mark> real</mark> en <mark class=\"m-personalizado\">los términos establecidos reglamentariamente.</mark></p><p data-ex=\"EX\"><b>3.</b> La <mark class=\"m-personalizado\">información actualizada</mark> sobre la <mark class=\"m-destacable\">titularidad real</mark> <mark class=\"m-accion\">será</mark> <span class=\"m-caja\"><mark class=\"m-destacable\">mantenida</mark></span> por: <b>a)</b> El <mark class=\"m-autoridad\">administrador único</mark> o los <mark class=\"m-autoridad\">administradores mancomunados o solidarios.</mark> <b>b)</b> El <mark class=\"m-autoridad\">Consejo de Administración,</mark> <mark class=\"m-personalizado\">así</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">como, en</mark></span> <mark class=\"m-personalizado\">particular,</mark> el <mark class=\"m-autoridad\">secretario del Consejo de Administración,</mark> <mark class=\"m-personalizado\">sea</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">o no</mark></span> <mark class=\"m-personalizado\">consejero.</mark> <b>c)</b> El <mark class=\"m-autoridad\">patronato y el secretario.</mark> <b>d)</b> <mark class=\"m-autoridad\">El órgano de representación de la asociación</mark> y el <mark class=\"m-autoridad\">secretario.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1421,2-ia-1428\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 7, 9 y 11 — Aplicación de la diligencia debida, medidas simplificadas y reforzadas <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>Art. 7.</b> 3. Los sujetos obligados no <mark class=\"m-accion\">establecerán</mark> relaciones de negocio ni <mark class=\"m-accion\">ejecutarán</mark> operaciones cuando no puedan aplicar las medidas de diligencia debida <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">previstas en esta Ley</span></span>. <mark class=\"m-personalizado\">Cuando</mark> se aprecie <mark class=\"m-personalizado\">la</mark> imposibilidad en <mark class=\"m-personalizado\">el curso</mark> de la relación de negocios, los sujetos obligados <mark class=\"m-resp r-ia\" data-q=\"2-ia-1439,2-ia-2056\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">pondrán fin a la misma, procediendo a realizar el examen especial</mark> a que se refiere el <span class=\"ref-art\">artículo 17</span>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">L\u0007 a negativa a establecer relaciones de negocio o a ejecutar operaciones o la terminación de la relación de negocios por imposibilidad de aplicar las medidas de diligencia debida previstas en esta Ley no conllevará, salvo que medie enriquecimiento injusto, ningún tipo de responsabilidad para los sujetos obligados. 4. \u0007Los sujetos obligados aplicarán las medidas de diligencia debida establecidas en este Capítulo a los fideicomisos como el trust anglosajón, la fiducia, el treuhand de la legislación alemana u otros instrumentos jurídicos análogos o masas patrimoniales que, careciendo de personalidad jurídica, puedan actuar en el tráfico económico.</span></span> 5. Los <mark class=\"m-destacable\">casinos de juego</mark> <mark class=\"m-accion\">identificarán</mark> y <mark class=\"m-accion\">comprobarán</mark> mediante documentos fehacientes la identidad de <mark class=\"m-resp\" data-q=\"2-100\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cuantas personas pretendan acceder al establecimiento</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. La identidad de tales personas será registrada, sin perjuicio del cumplimiento de lo dispuesto en el artículo 25. A\u0007 simismo, los casinos de juego identificarán a cuantas personas pretendan realizar las siguientes operaciones: a) \u0007La entrega a los clientes de cheques como consecuencia de operaciones de cambio de fichas. b) \u0007Las transferencias de fondos realizadas por los casinos a petición de los clientes. c) L\u0007 a expedición por los casinos de certificaciones acreditativas de ganancias obtenidas por los jugadores</span></span>. Cuando <mark class=\"m-personalizado\">efectúen transacciones</mark> por un <mark class=\"m-destacable\">valor</mark> <mark class=\"m-resp\" data-q=\"2-101,2-ia-1441,2-ia-1443\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">igual o superior a 2.000 euros</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en una operación o en varias operaciones entre las que parezca existir algún tipo de relación, ya sea en el momento del cobro de ganancias, de compra o venta de fichas de juego</span></span>, los casinos <mark class=\"m-accion\">deberán aplicar</mark> el resto de las <mark class=\"m-personalizado\">medidas de diligencia debida</mark> <span class=\"hueco-txt\">respecto del cliente en los términos de esta Sección. 6. \u0007Los operadores de juego a través de medios electrónicos, informáticos, telemáticos e interactivos iden- tificarán y comprobarán la identidad de cuantas personas pretendan participar en estos juegos o apuestas, en los términos previstos reglamentariamente. C\u0007 uando efectúen transacciones por un valor igual o superior a 2.000 euros en una operación o en varias operaciones entre las que parezca existir algún tipo de relación, ya sea en el momento del cobro de ganancias y/o de la realización de apuestas, estos operadores de juego deberán aplicar el resto de las medidas de diligencia debida respecto del cliente en los términos de esta Sección. L\u0007 os operadores de juego a través de medios presenciales aplicarán las medidas de diligencia debida cuando efectúen transacciones por un valor igual o superior a 2.000 euros en una operación o en varias operaciones entre las que parezca existir algún tipo de relación. 7. \u0007Reglamentariamente podrá autorizarse la no aplicación de todas o algunas de las medidas de diligencia debida o de conservación de documentos en relación con aquellas operaciones ocasionales que no excedan de un umbral cuantitativo, bien singular, bien acumulado por periodos temporales</span>. 8. Las entidades financieras que actúen como adquirentes solo <mark class=\"m-accion\">aceptarán</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">pagos efectuados con tarjetas prepago anónimas emitidas en países fuera de España</span></span> cuando esas tarjetas <mark class=\"m-resp r-ia\" data-q=\"2-ia-1437,2-ia-1445\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cumplan con los umbrales y requisitos establecidos en el <span class=\"ref-art\">artículo 12</span> de la Directiva (UE) 2015/849</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1514\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 9.</b> Los sujetos obligados <mark class=\"m-accion\">podrán</mark> aplicar (…) <mark class=\"m-personalizado\">medidas simplificadas de diligencia debida respecto de</mark> aquellos <mark class=\"m-resp r-ia\" data-q=\"2-ia-1411,2-ia-1416,2-ia-1451,2-ia-1452,2-ia-1453,2-ia-1933,2-ia-2301\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">clientes, productos u operaciones que comporten un riesgo reducido de blanqueo de capitales o de financiación del terrorismo</mark>.</p><p><b>Art. 11.</b> 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Sección, y en cualesquiera otros que, por presentar un alto riesgo de blanqueo de capitales o de financiación del terrorismo, se determinen reglamentariamente. \u0007Los sujetos obligados, aplicarán, en función de un análisis del riesgo, medidas reforzadas de diligencia debida en aquellas situaciones que por su propia naturaleza puedan presentar un riesgo más elevado de blanqueo de capitales o de financiación del terrorismo.</span></span> En todo caso, <mark class=\"m-accion\">tendrán</mark> esta consideración (riesgo más elevado → medidas reforzadas) <mark class=\"m-resp\" data-q=\"2-102,2-ia-1456,2-ia-1457\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">la actividad de banca privada y las operaciones de envío de dinero y de cambio de moneda extranjera que superen los umbrales establecidos reglamentariamente</mark>.</p></div></div><div class=\"ex-linea\">Artículo 12 — Relaciones de <mark class=\"m-autoridad\">negocio</mark> y <mark class=\"m-personalizado\">operaciones</mark> <mark class=\"m-personalizado\">no</mark> presenciales: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1458,2-ia-1459,2-ia-1461\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 3 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 13 — Corresponsalía bancaria transfronteriza · R11 <span class=\"ex-sello ex-sello-r\">R11</span></div><div class=\"ex-fb\"><p data-r=\"R11\"><span class=\"ex-sello ex-sello-r\">R11</span> <b>1.</b> <mark class=\"m-destacable\">Se entiende por <mark class=\"m-resp\" data-q=\"2-127\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">relación de corresponsalía</mark></mark> la <mark class=\"m-personalizado\">prestación de servicios</mark> bancarios <mark class=\"m-personalizado\">de un banco</mark> en calidad de <mark class=\"m-destacable\">corresponsal</mark> a <mark class=\"m-personalizado\">otro banco</mark> como cliente <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, incluidas, entre otras, la prestación de cuentas corrientes u otras cuentas de pasivo y servicios conexos, como gestión de efectivo, transferencias internacionales de fondos, compensación de cheques, y servicios de cambio de divisas</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1463,2-ia-1620,2-ia-1747\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 3 preguntas</mark></p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> El concepto de relaciones de corresponsalía incluye cualquier relación <mark class=\"m-resp r-ia\" data-q=\"2-ia-1667,2-ia-1928\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">entre entidades de crédito, entre entidades financieras y entre entidades de crédito y entidades financieras</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con inclusión de las entidades de pago, que presten servicios similares a los de un corresponsal a un cliente, incluidas, entre otras, las relaciones establecidas para operaciones con</span></span> valores o transferencias de fondos <mark class=\"m-resp r-ia\" data-q=\"2-ia-1464\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">o relaciones establecidas para operaciones con criptoactivos o transferencias de criptoactivos</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">En todos estos supuestos <mark class=\"m-accion\">será</mark> de aplicación lo dispuesto en este artículo.</span></span></p><p><b>2.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Con respecto a las relaciones de corresponsalía transfronteriza con entidades clientes de terceros países, las entidades financieras <mark class=\"m-accion\">deberán</mark> aplicar las siguientes medidas: a) reunir sobre la entidad cliente información suficiente para comprender la naturaleza de sus actividades y determinar (…) su reputación y la calidad de su supervisión; b) evaluar los controles contra el blanqueo de capitales (…) de que disponga la entidad cliente;</span></span> c) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1465\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">obtener autorización de la dirección antes de establecer nuevas relaciones de corresponsalía bancaria</mark> (…); <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">d) documentar las responsabilidades respectivas de cada entidad; e) realizar un seguimiento reforzado y permanente de las operaciones (…);</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1511\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> 2 bis. Sin perjuicio de lo establecido en el apartado anterior, en las relaciones de corresponsalía transfronteriza <mark class=\"m-resp r-ia\" data-q=\"2-ia-1466\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">que supongan la ejecución de servicios de criptoactivos con una entidad cliente no establecida en la Unión Europea que preste servicios equivalentes</mark>, los proveedores de servicios de criptoactivos <mark class=\"m-resp r-ia\" data-q=\"2-ia-1467\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">comprobarán que la entidad cliente está autorizada o registrada</mark>. En todo caso, los proveedores de servicios de criptoactivos <mark class=\"m-resp r-ia\" data-q=\"2-ia-1468,2-ia-1917\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">actualizarán la información sobre diligencia debida para la relación de corresponsalía de forma periódica o cuando surjan nuevos riesgos en relación con la entidad cliente</mark>. Los proveedores de servicios de criptoactivos <mark class=\"m-accion\">tendrán</mark> en cuenta la información recabada <mark class=\"m-resp r-ia\" data-q=\"2-ia-1534\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a fin de determinar, en función del riesgo, las medidas adecuadas que deban adoptarse para mitigar los riesgos asociados a la entidad cliente</mark>.</p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> <b>3.</b> Las <mark class=\"m-resp r-ia\" data-q=\"2-ia-1664\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">entidades financieras</mark> no <mark class=\"m-accion\">establecerán</mark> o <mark class=\"m-accion\">mantendrán</mark> relaciones de corresponsalía con bancos pantalla. (…) A estos efectos se <mark class=\"m-accion\">entenderá</mark> por banco pantalla <mark class=\"m-resp r-ia\" data-q=\"2-ia-1323,2-ia-1469,2-ia-1657,2-ia-1664,2-ia-1915\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la entidad de crédito, o entidad que desarrolle una actividad similar, constituida en un país en el que no tenga una presencia física que permita ejercer una verdadera gestión y dirección y que no sea filial de un grupo financiero regulado</mark>.</p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> <b>4.</b> Las <mark class=\"m-resp\" data-q=\"2-164\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">entidades financieras y los proveedores de servicios de criptoactivos</mark> no <mark class=\"m-accion\">establecerán</mark> o <mark class=\"m-accion\">mantendrán</mark> relaciones de corresponsalía que, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1470\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">directamente o través de una subcuenta, permitan ejecutar operaciones a los clientes de la entidad representada</mark>.</p><p class=\"p-nuevo\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> <b>5.</b> Cuando las entidades financieras <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y los proveedores de servicios de criptoactivos decidan poner fin a relaciones de corresponsalía por razones relacionadas con la lucha contra el blanqueo de capitales</span></span> y la financiación del terrorismo, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1471\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">documentarán y registrarán su decisión</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 14 — Personas con responsabilidad pública (PRP)</div><div class=\"ex-fb\"><p><b>4.</b> Ninguna de las categorías previstas en los apartados anteriores <mark class=\"m-accion\">incluirá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1509\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">empleados públicos de niveles intermedios o inferiores</mark>.</p><p><b>6.</b> (…) Se <mark class=\"m-accion\">considerará</mark> allegado <mark class=\"m-resp r-ia\" data-q=\"2-ia-1513\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">toda persona física de la que sea notorio que</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ostente la titularidad o el control de un instrumento o persona jurídicos conjuntamente con una persona</span></span> con responsabilidad pública, o que <mark class=\"m-resp r-ia\" data-q=\"2-ia-1510,2-ia-1513\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">mantenga otro tipo de relaciones empresariales estrechas con la misma</mark> (…). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1502,2-ia-1512\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>9.</b> (…) <mark class=\"m-personalizado\">cuando</mark> las personas contempladas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) <mark class=\"m-personalizado\">hayan dejado de desempeñar sus funciones</mark>, <mark class=\"m-autoridad\">los sujetos obligados</mark> <mark class=\"m-accion\">continuarán</mark> <mark class=\"m-personalizado\">aplicando las medidas previstas</mark></span></span> en este artículo <mark class=\"m-personalizado\">por un periodo</mark> de <mark class=\"m-resp r-ia\" data-q=\"2-ia-1515\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">dos años</mark> (…).</p></div></div><div class=\"bloque-titulo\">CAPÍTULO III. <mark class=\"m-personalizado\">OBLIGACIONES</mark> DE <mark class=\"m-destacable\">INFORMACIÓN</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 17 y 18 — Examen especial y comunicación por indicio · R12 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R12</span></div><div class=\"ex-fb\"><p><b>Art. 17.</b> <mark class=\"m-destacable\">Los</mark> <mark class=\"m-autoridad\">sujetos</mark> <mark class=\"m-personalizado\">obligados</mark> <mark class=\"m-accion\">examinarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">con especial atención</u></mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1609,2-ia-1807\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualquier hecho u operación, con independencia de su cuantía, que, por su naturaleza, pueda estar relacionado con el blanqueo de capitales o la financiación del terrorismo</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">reseñando por escrito los resultados</mark> del examen. <u class=\"m-clave\">En particular</u>, (…) <mark class=\"m-personalizado\"><u class=\"m-clave\">toda</u> operación o pauta</mark> de comportamiento compleja, <mark class=\"m-personalizado\">inusual o sin un propósito económico o lícito aparente</mark>, <mark class=\"m-personalizado\">o</mark> que <mark class=\"m-destacable\">presente indicios de</mark> <mark class=\"m-personalizado\">simulación o fraude.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1110,2-ia-1135,2-ia-1519,2-ia-1520,2-ia-1533\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 5 preguntas</mark></p><p data-ex=\"*\" data-r=\"R12\"><span class=\"ex-sello ex-sello-r\">R12</span> <b>Art. 18.</b> 1. <mark class=\"m-autoridad\">Los sujetos obligados</mark> <mark class=\"m-accion\">comunicarán</mark>, <mark class=\"m-accion\">por</mark> <mark class=\"m-personalizado\">iniciativa propia,</mark> <mark class=\"m-autoridad\">al</mark> Servicio Ejecutivo de la <mark class=\"m-autoridad\">Comisión</mark> cualquier <mark class=\"m-personalizado\">hecho u operación</mark>, <mark class=\"m-personalizado\">incluso la</mark> mera <mark class=\"m-personalizado\">tentativa</mark>, respecto al que, <mark class=\"m-personalizado\">tras el examen especial</mark> (…), <mark class=\"m-personalizado\">exista <u class=\"m-clave\">indicio o certeza</u></mark> de que está <mark class=\"m-personalizado\">relacionado con el blanqueo</mark> de capitales o la financiación del terrorismo. (…) 4. <mark class=\"m-autoridad\">Los directivos o empleados</mark> de los sujetos obligados <mark class=\"m-accion\">podrán</mark> <mark class=\"m-destacable\">comunicar directamente</mark> al Servicio <mark class=\"m-autoridad\">Ejecutivo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la Comisión las operaciones de que conocieran y respecto de las cuales estimen que concurren indicios o certeza de estar relacionadas con el blanqueo de capitales o con la financiación del terrorismo,</span></span> en los casos en <mark class=\"m-personalizado\">que, habiendo sido puestas de manifiesto internamente</mark>, <mark class=\"m-autoridad\">el sujeto obligado</mark> <mark class=\"m-personalizado\">no hubiese informado</mark> al <mark class=\"m-autoridad\">directivo o empleado</mark> comunicante <mark class=\"m-personalizado\">del curso dado</mark> a su comunicación. <mark class=\"m-resp ex-q\" data-q=\"2-ia-1528,2-ia-1563,2-36,2-55,2-105,2-128,2-ia-1329,2-ia-1454,2-ia-1508,2-ia-1522,2-ia-1526,2-ia-1527,2-ia-1532,2-ia-1546,2-ia-1551,2-ia-1610,2-ia-1614,2-ia-1628,2-ia-1640,2-ia-1647,2-ia-1651,2-ia-1656,2-ia-1662,2-ia-1666,2-ia-1749,2-ia-1751,2-ia-1754,2-ia-1761,2-ia-1804,2-ia-1861,2-ia-1923,2-ia-1931\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 32 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 22, 23 y 24 — No sujeción de los abogados, exención de responsabilidad y prohibición de revelación <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>Art. 22.</b> Los <mark class=\"m-autoridad\">abogados</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1536\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no estarán sometidos a las obligaciones establecidas en los <span class=\"ref-art\">artículos 7.3, 18 y 21</span> con respecto a la información que reciban de uno de sus clientes</mark> u obtengan sobre <mark class=\"m-personalizado\">él al determinar la</mark> <mark class=\"m-destacable\">posición jurídica en favor</mark> <mark class=\"m-personalizado\">de su cliente o</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1113\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">desempeñar su misión de defender a dicho cliente en procesos judiciales</mark> o <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en relación con ellos (…).</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Sin perjuicio de lo establecido en la presente Ley, los <mark class=\"m-autoridad\">abogados</mark> <mark class=\"m-accion\">guardarán</mark> el deber de secreto profesional (…).</span></span></p><p><b>Art. 23.</b> <mark class=\"m-destacable\">La comunicación de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2046\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">buena fe</mark> <mark class=\"m-destacable\">de información a las</mark> <mark class=\"m-autoridad\">autoridades competentes</mark> (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1537\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no constituirá violación de las restricciones sobre divulgación de información</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">impuestas por vía contractual o por cualquier</span></span> disposición legal, reglamentaria o administrativa, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1537\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">y no implicará</mark> para los sujetos obligados, sus directivos o empleados <mark class=\"m-resp r-ia\" data-q=\"2-ia-1537\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">ningún tipo de responsabilidad</mark>.</p><p data-ex=\"*\"><b>Art. 24.</b> 1. Los sujetos obligados y sus <mark class=\"m-autoridad\">directivos o empleados</mark> no <mark class=\"m-accion\">revelarán</mark> <mark class=\"m-personalizado\">al cliente ni a terceros que</mark> se ha comunicado información al Servicio Ejecutivo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la Comisión, o que se está examinando o puede examinarse alguna operación por si pudiera estar relacionada con el blanqueo de capitales o con la financiación del terrorismo. E\u0007 sta prohibición no incluirá la revelación a las autoridades competentes, incluidos los órganos centralizados de prevención, o la revelación por motivos policiales en el marco de una investigación penal.</span></span>. 2. <mark class=\"m-personalizado\">La prohibición</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">establecida en el apartado precedente</span></span> no <mark class=\"m-accion\">impedirá</mark>: a) <mark class=\"m-resp\" data-q=\"2-165\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">La comunicación de información entre sujetos obligados que pertenezcan al mismo grupo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. A estos efectos, se estará a la definición de grupo establecida en el artículo 42 del Código de Comercio. Esta excepción es aplicable a la comunicación de información con sujetos obligados domiciliados en terceros países, siempre que se aplique en ellos políticas y procedimientos de grupo que cumplan con los requisitos establecidos en esta ley</span></span>; b) (…) c) (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 25 — Conservación de documentos · R13 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R13</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\" data-r=\"R13\"><span class=\"ex-sello ex-sello-r\">R13</span> <b>1.</b> <mark class=\"m-autoridad\">Los sujetos obligados</mark> <mark class=\"m-accion\">conservarán durante un</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">período de</u></mark> <mark class=\"m-resp\" data-q=\"2-68,2-ia-1653,2-175,2-ia-1826\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">diez años</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">la</u></mark> <mark class=\"m-personalizado\">documentación en que se</mark> <mark class=\"m-autoridad\">formalice</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">el</u> cumplimiento de las obligaciones establecidas</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">en la</u></mark> <mark class=\"m-personalizado\">presente ley, procediendo</mark> <mark class=\"m-accion\">tras</mark> el mismo a su eliminación. Transcurridos <mark class=\"m-resp r-ia\" data-q=\"2-ia-1046\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cinco años</mark> <mark class=\"m-personalizado\">desde la terminación de la relación</mark> de negocios o <mark class=\"m-personalizado\">la ejecución de la operación</mark> ocasional, la documentación conservada <mark class=\"m-personalizado\">únicamente</mark> <mark class=\"m-accion\">será</mark> accesible por los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1542,2-ia-1625\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">órganos de control interno</mark> del <mark class=\"m-autoridad\">sujeto obligado</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, con inclusión de las unidades técnicas de prevención, y, en su caso, aquellos encargados de su defensa legal. E\u0007 n particular, los sujetos obligados conservarán para su uso en toda investigación o análisis, en materia de posibles casos de blanqueo de capitales o de financiación del terrorismo, por parte del Servicio Ejecutivo de la Comisión o de cualquier otra autoridad legalmente competente</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1543,2-ia-1535,2-ia-1910\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 3 preguntas</mark></p></div></div><div class=\"bloque-titulo\">CAPÍTULO IV. CONTROL INTERNO</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 26 ter, 27 y 28 — Representante, órganos centralizados de prevención y examen externo <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R14</span> <span class=\"ex-sello ex-sello-r\">R15</span></div><div class=\"ex-fb\"><p data-ex=\"*\" data-r=\"R14\"><span class=\"ex-sello ex-sello-r\">R14</span> <b>Art. 26 ter.</b> 1. Los sujetos obligados <mark class=\"m-accion\">designarán</mark> como representante ante <mark class=\"m-destacable\">el Servicio Ejecutivo</mark> a <mark class=\"m-autoridad\">una persona residente en España</mark> que ejerza <mark class=\"m-personalizado\">cargo</mark> de administración o dirección de la <mark class=\"m-destacable\"><u class=\"m-clave\">sociedad</u></mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">E\u0007 n los grupos que integren varios sujetos obligados, el representante <mark class=\"m-resp r-ia\" data-q=\"2-ia-1555\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">será único y deberá ejercer cargo de administración o dirección de la sociedad dominante del grupo</mark>.</span></span> <mark class=\"m-personalizado\">En el caso de empresarios</mark> o profesionales <mark class=\"m-destacable\"><u class=\"m-clave\">individuales</u></mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">representante</mark> ante el Servicio Ejecutivo de la <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1556\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el titular de la actividad</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-98,2-129,2-ia-1343,2-ia-1504,2-ia-1505,2-ia-1554,2-ia-1558,2-ia-1641,2-ia-1725,2-ia-1735,2-ia-1757\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 11 preguntas</mark></p><p data-r=\"R15\"><span class=\"ex-sello ex-sello-r\">R15</span> <b>Art. 27.</b> 1. Mediante <mark class=\"m-destacable\">orden</mark> del Ministro de <mark class=\"m-personalizado\">Economía y</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">Empresa</u></mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">acordarse</mark> <mark class=\"m-autoridad\">la constitución de órganos</mark> <mark class=\"m-destacable\">centralizados</mark> <mark class=\"m-personalizado\">de prevención de las</mark> profesiones colegiadas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">sujetas a la presente Ley. \u0007</span></span>. Los <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-destacable\">centralizados de prevención</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-destacable\">por función</mark> <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1562\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">intensificación y canalización de la colaboración de las profesiones colegiadas con las autoridades</mark> judiciales, policiales y administrativas <span class=\"hueco-txt\">responsables de la prevención y represión del blanqueo de capitales y de la financiación del terrorismo, sin perjuicio de la responsabilidad directa de los profesionales incorporados como sujetos obligados. El representante del órgano centralizado de prevención tendrá la condición de representante de los profesionales incorporados a efectos de lo dispuesto en el artículo 26 ter. MEDIANTE ORDEN DEL MINISTRO DE ECONOMÍA Y EMPRESA</span>. <mark class=\"m-resp ex-q\" data-q=\"2-26,2-130,2-ia-1548,2-ia-1561,2-ia-1661,2-ia-1862,2-ia-1902\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 7 preguntas</mark></p><p data-ex=\"*\"><b>Art. 28.</b> 1. <mark class=\"m-personalizado\">Las medidas</mark> y <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">de control interno</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a que se refieren los artículos 26, 26 bis y 26 ter</span></span> <mark class=\"m-accion\">serán</mark> <mark class=\"m-destacable\">objeto</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1114\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">examen anual por un experto externo</mark>. <span class=\"hueco-txt\">\u0007Los resultados del examen serán consignados en un informe escrito que describirá detalladamente las medidas de control interno existentes, valorará su eficacia operativa y propondrá, en su caso, eventuales rectificaciones o mejoras. No obstante, en los dos años sucesivos a la emisión del informe podrá éste ser sustituido por un informe de seguimiento emitido por el experto externo, referido exclusivamente <mark class=\"m-resp r-ia\" data-q=\"2-ia-1603\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a la adecuación de las medidas adoptadas por el sujeto obligado para solventar las deficiencias identificadas</mark>. M\u0007 ediante orden del Ministro de Economía y Empresa podrán aprobarse los modelos a que habrán de ajustarse los informes emitidos. \u0007</span> <mark class=\"m-destacable\">El informe</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">elevará</mark> en el plazo máximo de tres meses desde la fecha de emisión <mark class=\"m-autoridad\">al Consejo de Administración</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o, en su caso, al órgano de administración o al principal órgano directivo del sujeto obligado, que adoptará las medidas necesarias para solventar las deficiencias identificadas</span></span>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Los sujetos obligados deberán encomendar la práctica del examen externo a personas que reúnan condiciones académicas y de experiencia profesional que las hagan idóneas para el desempeño de la función. \u0007Quienes pretendan actuar como expertos externos deberán comunicarlo al Servicio Ejecutivo de la Comisión antes de iniciar su actividad e informar a éste semestralmente de la relación de sujetos obligados cuyas medidas de control interno hayan examinado.</span></span> Los sujetos obligados no <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">encomendar</mark> la práctica del <mark class=\"m-plazo\">examen externo a aquellas personas físicas que</mark> <mark class=\"m-resp\" data-q=\"2-166,2-167,2-ia-1606\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">les hayan prestado o presten cualquier otra clase de servicios retribuidos durante los tres años anteriores o posteriores a la emisión del informe</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 31 — Sucursales y filiales en terceros países <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b>2.</b> Cuando el <mark class=\"m-personalizado\">derecho</mark> del <mark class=\"m-autoridad\">tercer país</mark> <mark class=\"m-personalizado\">no</mark> permita <mark class=\"m-destacable\">la <u class=\"m-clave\">aplicación</u></mark> de <mark class=\"m-personalizado\"><u class=\"m-clave\">medidas</u> equivalentes</mark> a las establecidas por el derecho de la <mark class=\"m-destacable\">Unión Europea,</mark> <mark class=\"m-autoridad\">los sujetos obligados</mark> <mark class=\"m-accion\">adoptarán</mark> <mark class=\"m-personalizado\">respecto de sus sucursales y filiales</mark> con participación mayoritaria <mark class=\"m-personalizado\">medidas</mark> adicionales para hacer frente eficazmente al riesgo <mark class=\"m-personalizado\">de</mark> blanqueo de capitales o de financiación del terrorismo. Las entidades <mark class=\"m-autoridad\">financieras</mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-personalizado\">aplicar</mark> medidas de conformidad con lo dispuesto en el Reglamento <mark class=\"m-autoridad\">Delegado</mark> (UE) 2019/758, de la <mark class=\"m-autoridad\">Comisión,</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de 31 de enero de 2019, por el que se completa la Directiva (UE) 2015/849 en lo que respecta a las normas técnicas de</span></span> regulación sobre las <mark class=\"m-personalizado\">medidas mínimas y el tipo de medidas adicionales</mark> que han de adoptar las entidades de crédito y financieras <mark class=\"m-personalizado\">para atenuar el riesgo de blanqueo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de capitales y de financiación del terrorismo en determinados terceros países.</span></span> Asimismo, los sujetos <mark class=\"m-personalizado\">obligados</mark> <mark class=\"m-accion\">informarán</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">al</u></mark> <mark class=\"m-autoridad\">Servicio Ejecutivo</mark> de la <mark class=\"m-autoridad\">Comisión</mark> de esta circunstancia en el plazo máximo de siete días después de identificar al <mark class=\"m-autoridad\">tercer país</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1001,2-ia-1448,2-ia-1612,2-ia-1613\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 4 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 32 ter — Sistemas comunes de información <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>1.</b> Los <mark class=\"m-autoridad\">sujetos obligados pertenecientes</mark> a <mark class=\"m-destacable\">una misma categoría</mark> de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">las establecidas en el artículo 2 de esta ley <mark class=\"m-accion\">podrán crear</mark> <mark class=\"m-destacable\">sistemas comunes de información, almacenamiento</mark> y, en su caso, <mark class=\"m-destacable\">acceso a la información y documentación recopilada</mark> para el cumplimiento de las obligaciones de diligencia debida establecidas en el capítulo II, con excepción</span></span> de la relacionada con el <mark class=\"m-resp r-ia\" data-q=\"2-ia-1622\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">seguimiento continuo de la relación de negocios</mark>, regulada en el artículo 6. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1624\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"*\">Los sujetos obligados corresponsables <mark class=\"m-accion\">deberán</mark> comunicar a la <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias la</span></span> intención de constituir <mark class=\"m-destacable\">estos</mark> <mark class=\"m-personalizado\">sistemas</mark> <mark class=\"m-autoridad\">al</mark> <mark class=\"m-destacable\">menos sesenta</mark> <mark class=\"m-autoridad\">días antes</mark> <mark class=\"m-personalizado\">de su puesta en funcionamiento. Esta comunicación</mark> no exime a las entidades financieras del <mark class=\"m-personalizado\">cumplimiento de las obligaciones de notificación</mark> a que estén sujetas. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1623\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"bloque-titulo\">CAPÍTULOS V y VI. MEDIOS DE PAGO Y OTRAS DISPOSICIONES</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 34 y 35 — Obligación de declarar e intervención de los medios de pago <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b><mark class=\"m-plazo\">Art. 34.</mark></b> 1. <mark class=\"m-accion\">Deberán</mark> presentar declaración previa (…) las personas físicas que <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, actuando por cuenta propia o de tercero,</span></span> realicen los siguientes movimientos: a) salida o entrada en territorio nacional de medios de pago por importe igual o superior a 10.000 euros <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o su contravalor en moneda extranjera</span></span>; b) movimientos por territorio nacional de medios de pago por importe <mark class=\"m-resp\" data-q=\"2-103,2-ia-1630,2-ia-1631,2-ia-1644\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">igual o superior a 100.000 euros</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o su contravalor en moneda extranjera</span></span>. 2. (…) envíos sin portador <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, tales como envíos postales, envíos por mensajería, equipaje no acompañado o carga en contenedores,</span></span> por importe <mark class=\"m-destacable\"><u class=\"m-clave\">igual o superior</u> a 10.000 euros</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o su contravalor en moneda extranjera, deberá presentarse</span></span> <mark class=\"m-destacable\">declaración</mark> <mark class=\"m-personalizado\">dentro del</mark> plazo de 30 días anteriores al movimiento no <mark class=\"m-personalizado\">acompañado</mark> (…). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1633,2-ia-1634\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p data-ex=\"EXOF,*\"><b>Art. 35.</b> 2. <mark class=\"m-accion\">Procederá</mark> la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1003,2-ia-1639,2-ia-1645\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">intervención provisional de la totalidad de los medios de pago</mark> objeto del movimiento <mark class=\"m-personalizado\">por parte de</mark> los funcionarios aduaneros <mark class=\"m-personalizado\">o policiales</mark> actuantes, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1643\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">salvo el mínimo de supervivencia</mark> que pueda <mark class=\"m-personalizado\">determinarse mediante</mark> <mark class=\"m-destacable\">orden</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la persona titular del Ministerio de Asuntos Económicos y Transformación Digital</span></span>, <mark class=\"m-personalizado\">en los <u class=\"m-clave\">casos</u></mark> siguientes: a) <mark class=\"m-personalizado\">no presentación</mark> de la declaración previa <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a que se refieren los apartados 1 y 2 del artículo 34</span></span> <mark class=\"m-personalizado\">cuando esta sea preceptiva</mark> (…); <mark class=\"m-destacable\"><u class=\"m-clave\">c)</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Presentación de la declaración previa a que se refieren los apartados 1 y 2 del artículo 34 con información incorrecta o incompleta. A estos efectos, y sin perjuicio de su aplicación en otros supuestos, en todo caso se considerará información incorrecta o incompleta la falta de veracidad total o parcial de los datos relativos al portador, propietario, remitente, destinatario, procedencia o uso previsto de los medios de pago, así como</span></span> la <mark class=\"m-personalizado\">variación por exceso o defecto del importe</mark> declarado respecto del <mark class=\"m-personalizado\">real</mark> <mark class=\"m-destacable\">en más de un 10 por ciento o de 3.000 euros</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1642\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 38 y 39 — Comercio de bienes y fundaciones y asociaciones <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>Art. 38.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Sin perjuicio de las limitaciones de pagos en efectivo establecidas en el artículo 7.Uno de la Ley 7/2012, de 29 de octubre, de modificación de la normativa tributaria y presupuestaria y de adecuación de la normativa financiera para la intensificación de las actuaciones en la prevención y lucha contra el fraude,</span></span> <mark class=\"m-personalizado\">las personas</mark> <mark class=\"m-autoridad\">físicas o jurídicas</mark> <mark class=\"m-personalizado\">que <u class=\"m-clave\">comercien profesionalmente con</u> bienes</mark> <mark class=\"m-accion\">quedarán</mark> <mark class=\"m-destacable\">sujetas a las obligaciones</mark> establecidas en los <mark class=\"m-personalizado\"><span class=\"ref-art\">artículos 3, 17, 18</span>,</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">19,</mark></span> <mark class=\"m-personalizado\">21, 24 y 25 respecto de las transacciones en que los cobros o pagos</mark> se efectúen por <mark class=\"m-resp r-ia\" data-q=\"2-ia-1129\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">personas físicas no residentes</mark> con los <mark class=\"m-personalizado\">medios de pago a</mark> que se refiere el <span class=\"ref-art\">artículo 34.2</span> de esta <mark class=\"m-personalizado\">ley y por importe</mark> <mark class=\"m-resp\" data-q=\"2-104,2-ia-1345,2-ia-1652\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">superior a 10.000 euros</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, ya se realicen en una o en varias operaciones entre las que parezca existir algún tipo de relación. En función de un análisis del riesgo podrán extenderse reglamentariamente respecto de las referidas transacciones todas o algunas de las restantes obligaciones establecidas en la presente ley</span></span>.</p><p data-ex=\"*\"><b>Art. 39.</b> <mark class=\"m-destacable\">El Protectorado y el Patronato</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en ejercicio de las funciones que le atribuye la Ley 50/2002, de 26 de diciembre, de Fundaciones,</span></span> y <mark class=\"m-destacable\">el personal con responsabilidades</mark> en la gestión de las fundaciones <mark class=\"m-resp r-ia\" data-q=\"2-ia-1654\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">velarán para que éstas no sean utilizadas para el blanqueo de capitales</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">para canalizar fondos o recursos a</mark> las personas o entidades vinculadas a <mark class=\"m-personalizado\">grupos u organizaciones <u class=\"m-clave\">terroristas</u></mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">A estos efectos, todas las fundaciones conservarán durante el plazo establecido en el artículo 25 registros con la identificación de todas las personas que aporten o reciban a título gratuito fondos o recursos de la fundación, en los términos de los artículos 3 y 4 de esta Ley. Estos registros estarán a disposición del Protectorado, de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo, de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias o de sus órganos de apoyo, así como de los órganos administrativos o judiciales con competencias en el ámbito de la prevención o persecución del blanqueo de capitales o del terrorismo.</span></span></span> Lo dispuesto <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en los párrafos anteriores</span></span> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">asimismo de aplicación a</mark> <mark class=\"m-destacable\">las asociaciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, correspondiendo en tales casos al órgano de gobierno o asamblea general, a los miembros del órgano de representación que gestione los intereses de la asociación y al organismo encargado de verificar su constitución, en el ejercicio de las funciones que tiene atribuidas por el artículo 34 de la Ley Orgánica 1/2002, de 22 de marzo, reguladora del Derecho de Asociación, cumplir con lo establecido el presente artículo</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-168\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 42 — Sanciones y contramedidas financieras internacionales <span class=\"ex-sello ex-sello-r\">R16</span></div><div class=\"ex-fb\"><p data-r=\"R16\"><span class=\"ex-sello ex-sello-r\">R16</span> <b><mark class=\"m-destacable\">2.</mark></b> Sin perjuicio del <mark class=\"m-personalizado\">efecto directo de los reglamentos comunitarios,</mark> el <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"2-131\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Consejo de Ministros, a propuesta del Ministro de Economía y Competitividad</mark>,</mark> <mark class=\"m-accion\">podrá</mark> acordar la aplicación de <mark class=\"m-destacable\">contramedidas financieras</mark> respecto de <mark class=\"m-autoridad\">países terceros</mark> <mark class=\"m-personalizado\">que supongan riesgos</mark> <mark class=\"m-destacable\">más elevados</mark> de <mark class=\"m-personalizado\">blanqueo de capitales, financiación del terrorismo o financiación de la proliferación de armas de destrucción masiva.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1715,2-ia-1731,2-ia-1848,2-ia-1934\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 4 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 43 — Fichero de Titularidades Financieras <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>1.</b> (…) las entidades de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">crédito, las entidades de dinero electrónico y las entidades de pago (…) <mark class=\"m-accion\">deberán</mark> declarar al Servicio Ejecutivo de la <mark class=\"m-autoridad\">Comisión</mark> (…) la apertura o cancelación de cuentas corrientes, cuentas de ahorro, depósitos y de cualquier otro tipo de cuentas de pago, así como los contratos de alquiler de cajas de seguridad (…).</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1701,2-ia-1702\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p data-ex=\"EXOF\"><b>2.</b> Los datos declarados <mark class=\"m-accion\">serán</mark> incluidos en un fichero de titularidad pública, denominado <mark class=\"m-resp\" data-q=\"2-2,2-73\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Fichero de Titularidades Financieras</mark>, del cual <mark class=\"m-accion\">será</mark> responsable la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1704\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Secretaría de Estado de Economía y Apoyo a la Empresa</mark>. El <mark class=\"m-resp\" data-q=\"2-36\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Servicio Ejecutivo de la Comisión, como encargado del tratamiento, determinará</mark> (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1705\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">las características técnicas del fichero, pudiendo aprobar las instrucciones pertinentes</mark>.</p><p data-ex=\"EX,*\"><b>3.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Con ocasión de la investigación de delitos relacionados con el blanqueo de capitales o la</span></span> financiación del terrorismo, <mark class=\"m-accion\">podrán</mark> acceder al Fichero <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de titularidades Financieras</span></span> los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1707,2-ia-1708,2-ia-1916\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">órganos jurisdiccionales</mark>, el <mark class=\"m-resp r-ia\" data-q=\"2-ia-1710,2-ia-1936,2-ia-1938\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Ministerio Fiscal</mark> y la <mark class=\"m-autoridad\">Fiscalía</mark> Europea <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en el ejercicio de sus competencias</span></span>, así como: las <mark class=\"m-resp r-ia\" data-q=\"2-ia-1706\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Fuerzas y Cuerpos de Seguridad del Estado</mark> y las Policías Autonómicas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con competencias estatutariamente asumidas</span></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1706\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">para la investigación de los delitos graves</mark>; <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Los organismos de recuperación de activos, incluida la Oficina de Recuperación y Gestión de Activos, podrán acceder al Fichero cuando les haya sido encomendada la localización de activos por los órganos judiciales o fiscalías, así como en la realización de sus funciones de intercambio de información con otras oficinas análogas de la Unión Europea o instituciones de terceros Estados cuyo fin sea el embargo o decomiso en el marco de un procedimiento penal y se trate de delitos relacionados con el blanqueo de capitales o la financiación del terrorismo. La Secretaría de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo podrá acceder al Fichero en el marco de las competencias que tiene atribuidas en materia de bloqueo de los saldos, cuentas y posiciones, incluidos los bienes depositados en cajas de seguridad abiertas por personas o entidades vinculadas a organizaciones terroristas, en virtud de los artículos 1 y 2 de la Ley 12/2003, de 21 de mayo, de prevención y bloqueo de la financiación del terrorismo, y del Reglamento de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo, aprobado por el Real Decreto 413/2015, de 29 de mayo.</span></span> el <mark class=\"m-resp\" data-q=\"2-16,2-ia-1717,2-ia-1922\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Centro Nacional de Inteligencia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">podrá acceder a los datos declarados en el Fichero de Titularidades Financieras para el cumplimiento de las funciones que tiene asignadas en su normativa reguladora</span></span>; la <mark class=\"m-autoridad\">Agencia Estatal de Administración Tributaria</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">podrá acceder al Fichero de Titularidades Financieras para el ejercicio de sus competencias en materia de prevención y lucha contra el fraude, en los términos previstos en la Ley 58/2003, de 17 de diciembre, General Tributaria, y en el artículo 7.3 bis del Reglamento (UE, Euratom) n.º 883/2013 del Parlamento Europeo y del Consejo, de 11 de septiembre de 2013, relativo a las investigaciones efectuadas por la Oficina Europea de Lucha contra el Fraude. Igual acceso dispondrán las Haciendas Forales para la mencionada finalidad</span></span>. <mark class=\"m-personalizado\">Toda petición de acceso</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a los datos del Fichero de Titularidades Financieras habrá de realizarse a través de los respectivos puntos únicos de acceso que deberán asignarse a todas las autoridades anteriormente señaladas y</span></span> <mark class=\"m-accion\">deberá</mark> ser <mark class=\"m-destacable\">adecuadamente motivada</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por el órgano requirente, que será responsable de la regularidad del requerimiento. En ningún caso podrá requerirse el acceso al Fichero para finalidades distintas de las previstas en este artículo</span></span>. <mark class=\"m-destacable\">Los accesos</mark> <mark class=\"m-accion\">quedarán</mark> <mark class=\"m-personalizado\">registrados y los datos de los registros</mark> se <mark class=\"m-accion\">conservarán</mark> por un plazo de 5 años.</p></div></div><div class=\"bloque-titulo\">CAPÍTULO VII. DE <mark class=\"m-personalizado\">LA ORGANIZACIÓN</mark> INSTITUCIONAL</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 44 — Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R17</span></div><div class=\"ex-fb\"><p data-ex=\"*\" data-r=\"R17\"><span class=\"ex-sello ex-sello-r\">R17</span> <b>1.</b> El impulso y coordinación de la ejecución de la presente Ley <mark class=\"m-accion\">corresponderá</mark> a la <mark class=\"m-autoridad\">Comisión</mark> de Prevención del Blanqueo de Capitales e Infracciones Monetarias, <mark class=\"m-resp\" data-q=\"2-51,2-ia-1056,2-ia-1711\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">dependiente de la Secretaría de Estado de Economía</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-132,2-ia-1337,2-ia-1650,2-ia-1721,2-ia-1741,2-ia-1745,2-ia-1849,2-ia-1927,2-ia-1935,2-ia-1940\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 10 preguntas</mark></p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-accion\">Serán</mark> funciones de la <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias las siguientes</span></span>: (…) d) nombrar y cesar al Director del Servicio Ejecutivo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la Comisión. El nombramiento y cese se realizarán a propuesta de la persona titular de la Presidencia de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span><span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, previa consulta con el Banco de España. e) aprobar, previa consulta con el Banco de España, el presupuesto</span></span> del Servicio Ejecutivo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la Comisión. f) O\u0007 rientar de forma permanente la actuación del Servicio Ejecutivo de la Comisión y aprobar su estructura organizativa y directrices de funcionamiento</span></span>. g) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1115,2-ia-1120,2-ia-1550,2-ia-1713,2-ia-1716\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Aprobar, a propuesta del Servicio Ejecutivo de la Comisión</mark> y, en caso de convenio, de los <mark class=\"m-autoridad\">órganos</mark> de supervisión de las entidades financieras, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1743\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el Plan Anual de Inspección de los sujetos obligados</mark>, que <mark class=\"m-accion\">tendrá</mark> carácter reservado. (…)</p><p data-ex=\"*\"><b>3.</b> La <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span> <mark class=\"m-accion\">estará</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1718\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">presidida por el Secretario de Estado de Economía</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">tendrá</mark> la composición que reglamentariamente se establezca <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Contará, en todo caso, con la adecuada representación del Ministerio Fiscal, de los Ministerios e instituciones con competencias en la materia, de los órganos supervisores de las entidades financieras, así como de las Comunidades Autónomas con competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana. \u0007La Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span>. <mark class=\"m-accion\">Podrá</mark> <mark class=\"m-personalizado\">actuar</mark> en <mark class=\"m-destacable\">Pleno</mark> <mark class=\"m-personalizado\">o a través de un</mark> <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-destacable\">Permanente</mark> que, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con la composición que se determine reglamentariamente y</span></span> presidido por <mark class=\"m-autoridad\">el Director General del Tesoro y</mark> Política Financiera, <mark class=\"m-accion\">ejercerá</mark> <mark class=\"m-personalizado\">las funciones</mark> previstas en las letras f), <mark class=\"m-personalizado\">g) y h)</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">) del apartado precedente, o cualesquiera otras que el Pleno le delegue expresamente</span></span>. <mark class=\"m-personalizado\">La asistencia al Pleno</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span> <mark class=\"m-personalizado\">y a su</mark> <mark class=\"m-autoridad\">Comité</mark> Permanente <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"2-ia-1719\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">personal y no delegable</mark></mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 45 y 46 — Órganos de apoyo (Secretaría y Servicio Ejecutivo-SEPBLAC) e informes de inteligencia financiera <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF,EX,*\"><b>Art. 45.</b> 1. <span class=\"m-caja\"><mark class=\"m-autoridad\">La</mark></span> <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span> <mark class=\"m-accion\">llevará</mark> a cabo su <mark class=\"m-personalizado\">cometido con el</mark> apoyo <mark class=\"m-autoridad\">de la Secretaría de la Comisión</mark> <mark class=\"m-destacable\">y</mark> del Servicio Ejecutivo <mark class=\"m-autoridad\">de la Comisión</mark>. <mark class=\"m-destacable\">2.</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">L\u0007 a Secretaría de la Comisión será desempeñada por la unidad orgánica, con rango al menos de subdi- rección general, de las existentes en la Secretaría de Estado de Economía, que reglamentariamente se determine. Quien dirija dicha unidad orgánica ostentará, con carácter nato, el cargo de Secretario de la Comisión y de sus Comités. \u0007</span></span> <mark class=\"m-accion\">Corresponderá</mark> a <mark class=\"m-autoridad\">la Secretaría de la Comisión</mark>, <mark class=\"m-personalizado\">entre otras funciones</mark>, <mark class=\"m-destacable\">instruir los procedimientos</mark> sancionadores (…). 4. <mark class=\"m-autoridad\">El Servicio Ejecutivo</mark> de la <mark class=\"m-autoridad\">Comisión,</mark> <mark class=\"m-personalizado\">sin perjuicio de las competencias</mark> atribuidas a las Fuerzas y Cuerpos de la Seguridad <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y a otros Servicios de la Administración</span></span>, <mark class=\"m-accion\">ejercerá</mark> <mark class=\"m-personalizado\">las siguientes</mark> <mark class=\"m-destacable\">funciones</mark>: a) <mark class=\"m-destacable\">prestar el necesario <u class=\"m-clave\">auxilio a</u></mark> <mark class=\"m-personalizado\">los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">judiciales</mark>, <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Ministerio Fiscal</mark>, <mark class=\"m-personalizado\">a la Policía Judicial</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y a los órganos administrativos competentes</span></span>; (…) c) <mark class=\"m-personalizado\">recibir las comunicaciones</mark> previstas en los <mark class=\"m-personalizado\"><span class=\"ref-art\">artículos 18 y 20</span>;</mark> d) <mark class=\"m-personalizado\">analizar la información recibida</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y darle el cauce que en cada caso proceda. e) \u0007Ejecutar las órdenes y seguir las orientaciones dictadas por la Comisión de Prevención del Blan- queo de Capitales e Infracciones Monetarias o por su Comité Permanente, así como elevarle los informes que solicite</span></span>; f) <mark class=\"m-personalizado\">supervisar e inspeccionar el cumplimiento</mark> de las obligaciones de los <mark class=\"m-personalizado\">sujetos obligados</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">establecidas en esta Ley, de conformidad con lo previsto en el artículo 47. g) E\u0007 fectuar recomendaciones a los sujetos obligados orientadas a la mejora de las medidas de control interno. h) \u0007Proponer al Comité Permanente la formulación de requerimientos a los sujetos obligados. i) I\u0007nformar, con las excepciones que se determinen reglamentariamente, en los procedimientos de creación de entidades financieras sobre la adecuación de las medidas de control interno previstas en el programa de actividades. j) I\u0007nformar, con las excepciones que se determinen reglamentariamente, en los procedimientos de evaluación cautelar de las adquisiciones y de los incrementos de participaciones en el sector financiero. k) \u0007Las demás previstas en esta Ley o que le atribuyan las disposiciones legales vigentes</span></span>; <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">c) R\u0007 ecibir las comunicaciones previstas en los artículos 18 y 20. d) A\u0007 nalizar la información recibida y darle el cauce que en cada caso proceda. e) \u0007Ejecutar las órdenes y seguir las orientaciones dictadas por la Comisión de Prevención del Blan- queo de Capitales e Infracciones Monetarias o por su Comité Permanente, así como elevarle los informes que solicite. f) \u0007Supervisar e inspeccionar el cumplimiento de las obligaciones de los sujetos obligados establecidas en esta Ley, de conformidad con lo previsto en el artículo 47. g) E\u0007 fectuar recomendaciones a los sujetos obligados orientadas a la mejora de las medidas de control interno. h) \u0007Proponer al Comité Permanente la formulación de requerimientos a los sujetos obligados. i) I\u0007nformar, con las excepciones que se determinen reglamentariamente, en los procedimientos de creación de entidades financieras sobre la adecuación de las medidas de control interno previstas en el programa de actividades. j) I\u0007nformar, con las excepciones que se determinen reglamentariamente, en los procedimientos de evaluación cautelar de las adquisiciones y de los incrementos de participaciones en el sector financiero.</span></span> k) <mark class=\"m-personalizado\">las demás</mark> previstas en esta Ley <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o que le atribuyan las disposiciones legales vigentes</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1726\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p class=\"p-nuevo\" data-ex=\"EXOF,EX,*\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> l) <mark class=\"m-resp\" data-q=\"2-169,2-ia-1729\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Informar sobre la adecuación de las medidas de control interno en los procedimientos de autorización de proveedores de servicios de criptoactivos</mark>.</p><p data-ex=\"*\"><b>Art. 46.</b> 1. <mark class=\"m-autoridad\">El Servicio Ejecutivo de la Comisión</mark> <mark class=\"m-accion\">analizará</mark> <mark class=\"m-personalizado\">la información recibida</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de los sujetos obligados o de otras fuentes,</span></span> remitiendo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en tiempo oportuno, si apreciara la existencia de indicios o certeza de blanqueo de capitales, delitos subyacentes conexos o de financiación del terrorismo, o a petición de las autoridades competentes,</span></span> <mark class=\"m-personalizado\">el correspondiente</mark> <mark class=\"m-destacable\">informe</mark> de <mark class=\"m-destacable\">inteligencia financiera</mark> <mark class=\"m-autoridad\">al Ministerio Fiscal o a los órganos</mark> judiciales, <mark class=\"m-autoridad\">policiales o administrativos</mark> competentes. En ejercicio de sus funciones de <mark class=\"m-resp r-ia\" data-q=\"2-ia-1736,2-ia-1762\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">inteligencia financiera</mark>, <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">independiente y autónomo</u> en el plano operativo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, con autoridad y capacidad para desempeñar sus funciones libremente, pudiendo decidir de forma autónoma analizar, pedir y transmitir información específica. L\u0007 a información y documentación de que disponga el Servicio Ejecutivo de la Comisión y los informes de inteligencia financiera tendrán carácter confidencial, debiendo guardar reserva sobre los mismos toda autoridad o funcionario que acceda a su contenido. En particular, no será en ningún caso objeto de revelación la identidad de los analistas que hayan intervenido en la elaboración de los informes de inteligencia financiera ni la de los empleados, directivos o agentes que hubieran comunicado la existencia de indicios a los órganos de control interno del sujeto obligado. \u0007</span></span>. Los informes <mark class=\"m-personalizado\">de</mark> inteligencia financiera <mark class=\"m-resp r-ia\" data-q=\"2-ia-1733,2-ia-1742,2-ia-1864\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no tendrán valor probatorio y no podrán ser incorporados directamente a las diligencias judiciales o administrativas</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1732\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 48 bis — Cooperación internacional (suspensión de transacciones) <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b><mark class=\"m-personalizado\">6.</mark></b> <mark class=\"m-personalizado\">A requerimiento</mark> de la Unidad de Inteligencia <mark class=\"m-autoridad\">Financiera de otro Estado miembro de la Unión Europea, el Servicio Ejecutivo</mark> de la <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">facultado para suspender una transacción en curso,</mark> cuando concurran indicios de <mark class=\"m-personalizado\">blanqueo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de capitales o financiación del terrorismo a fin de que por parte de la Unidad</span></span> de Inteligencia Financiera <mark class=\"m-autoridad\">requirente</mark> <mark class=\"m-personalizado\">se proceda a analizar la transacción, confirmar la sospecha</mark> y comunicar los resultados del análisis a las <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-personalizado\">competentes. En los casos de suspensión</mark> por indicios de financiación de <mark class=\"m-personalizado\">terrorismo,</mark> <mark class=\"m-accion\">informará</mark> a la <mark class=\"m-autoridad\">Secretaría</mark> de la <mark class=\"m-autoridad\">Comisión</mark> de Vigilancia de Actividades de Financiación del Terrorismo cuando exista la <mark class=\"m-personalizado\">previa autorización</mark> de la Unidad de Inteligencia Financiera requirente. <mark class=\"m-autoridad\">La suspensión se</mark> <mark class=\"m-accion\">acordará</mark> <mark class=\"m-personalizado\">bajo la responsabilidad de la Unidad de Inteligencia Financiera</mark> <mark class=\"m-autoridad\">requirente y</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-autoridad\">efectiva por un periodo máximo de un mes. Transcurrido dicho plazo,</mark> <mark class=\"m-accion\">cesará</mark> <mark class=\"m-autoridad\">la</mark> suspensión <mark class=\"m-personalizado\">salvo</mark> que fuera <mark class=\"m-personalizado\">ratificada o prorrogada</mark> <mark class=\"m-autoridad\">judicialmente</mark> a solicitud del <mark class=\"m-autoridad\">Ministerio Fiscal.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1753\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 49 — Deber de secreto</div><div class=\"ex-fb\"><p><b>1.</b> <mark class=\"m-personalizado\">Todas las personas que desempeñen o hayan</mark> desempeñado una actividad <mark class=\"m-personalizado\">para</mark> la <mark class=\"m-autoridad\">Comisión</mark> de <mark class=\"m-personalizado\">Prevención del Blanqueo de</mark> Capitales e Infracciones Monetarias <mark class=\"m-personalizado\">o para cualquiera de sus</mark> <mark class=\"m-autoridad\">órganos</mark> y hayan tenido conocimiento de sus <mark class=\"m-personalizado\">actuaciones</mark> o de datos de <mark class=\"m-personalizado\">carácter reservado</mark> <mark class=\"m-resp\" data-q=\"2-30\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">están obligadas a mantener el debido secreto</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">El incumplimiento de esta obligación determinará las responsabilidades previstas por las leyes.</span></span> Estas <mark class=\"m-personalizado\">personas no</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">publicar</mark>, <mark class=\"m-personalizado\">comunicar o exhibir</mark> datos <mark class=\"m-personalizado\">o</mark> documentos reservados, ni siquiera <mark class=\"m-personalizado\">después de haber cesado</mark> en el servicio, salvo <mark class=\"m-personalizado\">permiso expreso</mark> otorgado por la <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1755\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"bloque-titulo\">CAPÍTULO VIII. DEL RÉGIMEN SANCIONADOR</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 49 — Deber de secreto (testimonio de los órganos judiciales) <span class=\"ex-sello ex-sello-r\">R18</span></div><div class=\"ex-fb\"><p data-r=\"R18\"><span class=\"ex-sello ex-sello-r\">R18</span> <b>3.</b> Los <mark class=\"m-autoridad\">órganos</mark> judiciales, de <mark class=\"m-destacable\">oficio</mark> o a <mark class=\"m-destacable\">instancia del</mark> <mark class=\"m-autoridad\">Ministerio Fiscal,</mark> <mark class=\"m-accion\">remitirán</mark> <mark class=\"m-destacable\">testimonio</mark> a la <mark class=\"m-autoridad\">Secretaría</mark> de <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Comisión</mark> cuando <mark class=\"m-personalizado\">en</mark> <mark class=\"m-autoridad\">el curso</mark> <mark class=\"m-personalizado\">del</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">proceso aprecien indicios de incumplimiento de la presente ley que no sean constitutivos de delito.</span></span> <mark class=\"m-resp ex-q\" data-q=\"2-133,2-ia-1327,2-ia-1746\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 3 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 50 y 51 — Clases de infracciones e infracciones muy graves <span class=\"ex-sello ex-sello-r\">R19</span></div><div class=\"ex-fb\"><p data-r=\"R19\"><span class=\"ex-sello ex-sello-r\">R19</span> <b>Art. 50.</b> Las infracciones <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">administrativas previstas en esta Ley</span></span> se <mark class=\"m-accion\">clasificarán</mark> en <mark class=\"m-resp\" data-q=\"2-52,2-134,2-ia-1759\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">muy graves, graves y leves</mark>.</p><p><b>Art. 51.</b> 1. <mark class=\"m-accion\">Constituirán</mark> infracciones muy graves las siguientes: a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1530,2-ia-1553,2-ia-1562,2-ia-1760\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el incumplimiento del deber de comunicación previsto en el <span class=\"ref-art\">artículo 18</span>, cuando algún directivo o empleado del sujeto obligado hubiera puesto de manifiesto internamente la existencia de indicios o la certeza</mark> de que un hecho u operación estaba relacionado con el <mark class=\"m-personalizado\">blanqueo</mark> de capitales <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o la financiación del terrorismo</span></span>; b) <mark class=\"m-personalizado\">el incumplimiento de la obligación de</mark> <mark class=\"m-destacable\">colaboración</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">establecida en el artículo 21</span></span> cuando medie requerimiento escrito de la <mark class=\"m-autoridad\">Comisión</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de Prevención del Blanqueo de Capitales e Infracciones Monetarias</span></span>; c) el incumplimiento de la prohibición de revelación <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">establecida en el artículo 24 o del deber de reserva previsto en los artículos 46.2 y 49.2.e).</span></span>; d) la <mark class=\"m-resp\" data-q=\"2-170,2-ia-1436,2-ia-1440,2-ia-1801,2-ia-1809,2-ia-1814,2-ia-1856\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">resistencia u obstrucción a la labor inspectora, siempre que medie requerimiento del personal actuante expreso y por escrito</mark> al respecto; e) <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007 l incumplimiento de la obligación de adoptar las medidas correctoras comunicadas por requerimiento del Comité Permanente a las que se alude en los artículos 26.5, 31.2, 44.2 y 47.5</span></span> cuando concurra <mark class=\"m-resp r-ia\" data-q=\"2-ia-1802\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">una voluntad deliberadamente rebelde al cumplimiento</mark>; f) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1111,2-ia-1727,2-ia-1803\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la comisión de una infracción grave cuando durante los cinco años anteriores hubiera sido impuesta al sujeto obligado sanción firme</mark> en vía administrativa por el mismo tipo de infracción; (…) <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1812\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 52 y 55 — Infracciones graves y exigibilidad de la responsabilidad · R19 <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b>1.</b> <mark class=\"m-accion\">Constituirán</mark> infracciones graves las siguientes: <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a) \u0007El incumplimiento de obligaciones de identificación formal, en los términos del artículo 3. b) E\u0007 l incumplimiento de las obligaciones de identificación e información del titular real, en los términos de los artículos 4, 4 bis y 4 ter. c) \u0007El incumplimiento de la obligación de obtener información sobre el propósito e índole de la relación de negocios, en los términos del artículo 5. d) E\u0007 l incumplimiento de la obligación de aplicar medidas de seguimiento continuo a la relación de negocios, en los términos del artículo 6. e) \u0007El incumplimiento de la obligación de aplicar medidas de diligencia debida a los clientes existentes, en los términos del artículo 7.2 y de la Disposición transitoria séptima. f) E\u0007 l incumplimiento de la obligación de aplicar medidas reforzadas de diligencia debida, en los términos de los artículos 11 a 16. g) \u0007El incumplimiento de la obligación de examen especial, en los términos del artículo 17.</span></span> h) <mark class=\"m-resp\" data-q=\"2-171,2-ia-1121,2-ia-1808,2-ia-1816,2-ia-1817,2-ia-1819\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">El incumplimiento de la obligación de comunicación por indicio, en los términos del <span class=\"ref-art\">artículo 18</span>, cuando no deba calificarse como infracción muy grave</mark>. (…) s) <mark class=\"m-resp\" data-q=\"2-172,2-ia-1426,2-ia-1450,2-ia-1608,2-ia-1611,2-ia-1629,2-ia-1734,2-ia-2311\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">El incumplimiento de la obligación de adoptar por parte del sujeto obligado las medidas adecuadas para mantener la confidencialidad sobre la identidad de los empleados, directivos o agentes que hayan realizado una comunicación a los órganos de control interno</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en los términos del artículo 30.1. t) \u0007El incumplimiento de la obligación de aplicar respecto de las sucursales y filiales con participación mayoritaria situadas en terceros países las medidas previstas en el artículo 31. u) E\u0007 l incumplimiento de la obligación de aplicar sanciones o contramedidas financieras internacionales, en los términos del artículo 42. v) E\u0007 l incumplimiento de la obligación establecida en el artículo 43 de declarar la apertura, modificación o cancelación de cuentas corrientes, cuentas de ahorro, depósitos, cuentas de pago y contratos</span></span>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de alquiler de cajas de seguridad, así como de <mark class=\"m-resp r-ia\" data-q=\"2-ia-1811\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">declarar y mantener actualizados los datos de los intervinientes</mark>. w) E\u0007 l incumplimiento de la obligación de adoptar las medidas correctoras comunicadas por requerimiento del Comité Permanente a las que se alude en los artículos 26.5, 31.2, 44.2 y 47.5 cuando no concurra una voluntad deliberadamente rebelde al cumplimiento. x) \u0007El establecimiento o mantenimiento de relaciones de negocio o la ejecución de operaciones prohibidas.</span></span> y) <mark class=\"m-personalizado\">La resistencia u obstrucción a la labor inspectora</mark> cuando no haya <mark class=\"m-personalizado\">mediado requerimiento</mark> del personal actuante <mark class=\"m-personalizado\">expreso y</mark> por escrito al respecto.</p><p class=\"p-nuevo\" data-ex=\"*\"><span class=\"tag-nuevo\">🆕 NUEVO · 30/09/2026</span> <b>5.</b> <mark class=\"m-accion\">Constituirán</mark> infracciones <mark class=\"m-destacable\">graves</mark> de la presente ley los <mark class=\"m-personalizado\">incumplimientos</mark> recogidos en el <span class=\"ref-art\">artículo 29</span> del Reglamento (UE) 2023/1113 del <mark class=\"m-autoridad\">Parlamento</mark> Europeo y del <mark class=\"m-autoridad\">Consejo,</mark> de 31 <mark class=\"m-personalizado\">de mayo</mark> de 2023. Asimismo, <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">considerado</mark> infracción <mark class=\"m-personalizado\">grave</mark> de la presente ley el incumplimiento de las obligaciones establecidas en los <span class=\"ref-art\">artículos 4 a 24 y 26</span> respecto de los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1818\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">proveedores de servicios de pago y de los proveedores de servicios de criptoactivos</mark> del Reglamento (UE) 2023/1113 <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del Parlamento Europeo y del Consejo, de</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-173\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p><p><b>Art. 55.</b> (…) <mark class=\"m-personalizado\">En el caso de <u class=\"m-clave\">sociedades disueltas</u></mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1821\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los antiguos socios responderán solidariamente de las sanciones administrativas pecuniarias impuestas hasta el límite de lo que hubieran recibido como cuota de liquidación</mark> (…).</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>⭐ EX · Arts. 56 a 58 — Sanciones de la Ley 10/2010: muy graves, graves y leves (cuadro propio)</div><div class=\"ex-tab\" style=\"--n:4\"><div class=\"ex-th\"></div><div class=\"ex-th\">MUY GRAVES (56)</div><div class=\"ex-th\">GRAVES (57)</div><div class=\"ex-th\">LEVES (58)</div><div class=\"ex-tl\"><b>Multa al sujeto obligado</b></div><div class=\"ex-td\"><u class=\"m-clave\">importe</u> <u class=\"m-clave\">mínimo</u> de 150.000 <mark class=\"m-personalizado\">euros</mark>; <mark class=\"m-personalizado\">máximo</mark>: la mayor de <mark class=\"m-plazo\"><u class=\"m-clave\">el 10 por</u> ciento del <u class=\"m-clave\">volumen de negocios</u> anual total</mark>, <mark class=\"m-plazo\">el duplo</mark> del contenido económico <mark class=\"m-personalizado\">de la operación</mark>, el quíntuplo del <u class=\"m-clave\">importe</u> de <u class=\"m-clave\">los beneficios</u> derivados <mark class=\"m-personalizado\">de la infracción</mark> o <mark class=\"m-plazo\">10.000.000 euros</mark></div><div class=\"ex-td\"><u class=\"m-clave\">importe</u> <u class=\"m-clave\">mínimo</u> de <mark class=\"m-plazo\">60.000 euros</mark>; <mark class=\"m-personalizado\">máximo</mark>: la mayor de <u class=\"m-clave\">el 10 por</u> ciento del <u class=\"m-clave\">volumen de negocios</u>, <u class=\"m-clave\">el tanto</u> del contenido económico más un <u class=\"m-clave\">50 por ciento</u>, <mark class=\"m-personalizado\">el triple</mark> del <u class=\"m-clave\">importe</u> de <u class=\"m-clave\">los beneficios</u> o <mark class=\"m-plazo\">5.000.000 euros</mark></div><div class=\"ex-td\"><mark class=\"m-resp\" data-q=\"2-12,2-49,2-135\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Multa por importe de hasta 60.000 euros</mark></div><div class=\"ex-tl\"><b>Además</b></div><div class=\"ex-td\"><mark class=\"m-personalizado\">amonestación pública</mark> · <mark class=\"m-personalizado\">suspensión</mark> temporal o <u class=\"m-clave\">revocación</u> de la <mark class=\"m-destacable\">autorización</mark> (entidades autorizadas)</div><div class=\"ex-td\"><mark class=\"m-resp\" data-q=\"2-39\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">amonestación pública o privada · suspensión temporal de la autorización</mark></div><div class=\"ex-td\"><mark class=\"m-resp\" data-q=\"2-135\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Amonestación privada</mark></div><div class=\"ex-tl\"><b>Cargos de administración o dirección</b></div><div class=\"ex-td\"><mark class=\"m-personalizado\">multa</mark> entre <mark class=\"m-plazo\">60.000 y 10.000.000 euros</mark> · <mark class=\"m-personalizado\">separación del cargo</mark> con <u class=\"m-clave\">inhabilitación</u> por un <mark class=\"m-destacable\">plazo</mark> <mark class=\"m-personalizado\">máximo</mark> de <mark class=\"m-plazo\">diez años</mark> · <mark class=\"m-personalizado\">amonestación pública</mark></div><div class=\"ex-td\"><mark class=\"m-personalizado\">multa</mark> de <u class=\"m-clave\">mínimo</u> <mark class=\"m-plazo\">3.000 euros</mark> y <mark class=\"m-personalizado\">máximo</mark> de hasta <mark class=\"m-plazo\">5.000.000 euros</mark> · <mark class=\"m-personalizado\">amonestación pública</mark> o privada · separación con <u class=\"m-clave\">inhabilitación</u> por un <mark class=\"m-destacable\">plazo</mark> <mark class=\"m-personalizado\">máximo</mark> de <mark class=\"m-plazo\">cinco años</mark> (<mark class=\"m-personalizado\">también</mark> el <mark class=\"m-personalizado\">experto externo</mark>)</div><div class=\"ex-td num\">—</div><div class=\"ex-tl\"><b>Declaración del art. 34</b></div><div class=\"ex-td num\">—</div><div class=\"ex-td\"><mark class=\"m-personalizado\">multa</mark> de <u class=\"m-clave\">mínimo</u> <mark class=\"m-plazo\">600 euros</mark> y <mark class=\"m-plazo\">hasta el</mark> <u class=\"m-clave\">50 por ciento</u> del <mark class=\"m-destacable\">valor</mark> de los medios de pago empleados</div><div class=\"ex-td num\">—</div></div></div><div class=\"ex-linea\">Artículos 56, 57 y 58 — <mark class=\"m-destacable\">Sanciones</mark> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R20</span>: <mark class=\"m-resp ex-q\" data-q=\"2-174,2-ia-1506,2-ia-1822,2-ia-1823,2-ia-1824,2-ia-1825,2-ia-1829,2-ia-1830,2-ia-1831,2-ia-1832,2-ia-1834,2-ia-1835\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 12 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 59 — Graduación de las sanciones <span class=\"ex-sello\">EXOF</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>1.</b> Las sanciones se <mark class=\"m-accion\">graduarán</mark> atendiendo a las siguientes circunstancias: <b>a)</b> La <mark class=\"m-destacable\"><u class=\"m-clave\">cuantía</u></mark> <mark class=\"m-personalizado\">de las operaciones</mark> afectadas por el incumplimiento. <b>b)</b> <mark class=\"m-personalizado\">Los</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">beneficios</u></mark> <mark class=\"m-personalizado\">obtenidos</mark> como consecuencia de las omisiones o actos constitutivos de la infracción. <b>c)</b> La circunstancia de haber <mark class=\"m-personalizado\">procedido o no a la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">subsanación</u></mark> de la infracción por propia iniciativa. <b>d)</b> <mark class=\"m-personalizado\">Las</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">sanciones firmes</u> en</mark> <span class=\"m-caja\">vía administrativa</span> <mark class=\"m-personalizado\">por infracciones de <u class=\"m-clave\">distinto tipo impuestas al</u></mark> sujeto obligado <mark class=\"m-plazo\">en los últimos cinco años con arreglo a esta ley.</mark> <b>e)</b> <mark class=\"m-destacable\"><u class=\"m-clave\">El grado</u></mark> de <mark class=\"m-personalizado\">responsabilidad o intencionalidad</mark> en los hechos que concurra en el sujeto obligado. <b>f)</b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">gravedad y duración</u></mark> <mark class=\"m-personalizado\">de la infracción.</mark> <b>g)</b> <mark class=\"m-personalizado\">Las</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">pérdidas para</u> terceros</mark> causadas por el incumplimiento. <b><mark class=\"m-personalizado\">h)</mark></b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">capacidad económica</u></mark> del inculpado, <span class=\"m-caja\">cuando</span> la <mark class=\"m-personalizado\">sanción sea de multa.</mark> <b>i)</b> <mark class=\"m-personalizado\">El nivel</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">de</u> cooperación</mark> del inculpado con las <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-personalizado\">competentes. En todo</mark> caso, <mark class=\"m-destacable\"><u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">graduará</mark> la sanción de modo que la <mark class=\"m-autoridad\">comisión</mark> de las infracciones <mark class=\"m-resp r-ia\" data-q=\"2-ia-1837\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no <mark class=\"m-personalizado\">resulte más beneficiosa para el</mark> <mark class=\"m-autoridad\">infractor</mark> que el cumplimiento de las normas infringidas</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-109\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 60 y 61 — Prescripción y procedimiento sancionador · R21 R22 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R21</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\" data-r=\"R21\"><span class=\"ex-sello ex-sello-r\">R21</span> <b>Art. 60.</b> 1. Las <mark class=\"m-destacable\">infracciones muy graves y graves</mark> <mark class=\"m-accion\">prescribirán</mark> <mark class=\"m-plazo\">a los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1833,2-ia-1836,2-ia-1840,2-ia-1855,2-ia-1930\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cinco años</mark></mark>, <mark class=\"m-plazo\">y las leves a los</mark> <mark class=\"m-personalizado\">dos</mark> <mark class=\"m-plazo\">años</mark>, contados <span class=\"m-circulo\"><mark class=\"m-personalizado\">desde</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">la fecha</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">en</mark></span> que la infracción hubiera sido cometida. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">En las infracciones derivadas de una actividad continuada, la fecha inicial del cómputo será la de la finalización de la actividad o la del último acto con el que la infracción se consume.</span></span> En el <mark class=\"m-destacable\">caso</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">incumplimiento de</mark> <mark class=\"m-destacable\">las</mark> <mark class=\"m-personalizado\">obligaciones de diligencia</mark> debida el plazo <mark class=\"m-personalizado\">de <u class=\"m-clave\">prescripción</u></mark> <u class=\"m-clave\">se</u> <mark class=\"m-accion\">contará</mark> <mark class=\"m-resp\" data-q=\"2-110,2-ia-1842,2-ia-1844\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">desde la fecha de terminación de la relación de negocios</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">, y en el de conservación de documentos desde la expiración del plazo al que se refiere el artículo 25. L\u0007 a prescripción se interrumpirá por cualquier acción de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias o de sus órganos de apoyo, realizada con conocimiento formal de los sujetos obligados, conducente a la inspección, supervisión o control de todas o parte de las obligaciones recogidas en esta Ley. También se interrumpirá por la iniciación, con conocimiento de los interesados, del procedimiento sancionador o de un proceso penal por los mismos hechos, o por otros cuya separación de los sancionables con arreglo a esta Ley sea racionalmente imposible</span></span></span>. <mark class=\"m-personalizado\">2.</mark> <mark class=\"m-destacable\">Las sanciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que se impongan conforme a esta Ley</span></span> <mark class=\"m-accion\">prescribirán</mark> <mark class=\"m-plazo\">a los tres años</mark> en caso de infracciones <mark class=\"m-personalizado\">muy graves,</mark> <mark class=\"m-autoridad\">a</mark> los <mark class=\"m-resp r-ia\" data-q=\"2-ia-1515\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">dos años</mark> en caso de infracciones graves, y al año en caso de infracciones <mark class=\"m-personalizado\">leves</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, contados desde la fecha de notificación de la resolución sancionadora</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-108,2-111,2-136,2-ia-1607,2-ia-1913,2-ia-1943\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 6 preguntas</mark></p><p><b>Art. 61.</b> <mark class=\"m-destacable\">1.</mark> La <mark class=\"m-destacable\">incoación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y, en su caso, el sobreseimiento de los procedimientos sancionadores a que hubiere lugar por la comisión de las infracciones previstas en esta Ley</span></span> <mark class=\"m-accion\">corresponderá</mark> al <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-personalizado\">Permanente</mark>, a <mark class=\"m-personalizado\">propuesta de</mark> <mark class=\"m-autoridad\">la Secretaría de la Comisión</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007La competencia para incoar o acordar el sobreseimiento de los procedimientos sancionadores por incumplimiento de la obligación de declaración establecida en el artículo 34 corresponderá a la Secretaría de la Comisión.</span></span> 2. <mark class=\"m-destacable\">La</mark> instrucción de los procedimientos sancionadores <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a que hubiera lugar por la comisión de infracciones previstas en esta ley</span></span> <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1722,2-ia-1845,2-ia-1846\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Secretaría de la Comisión</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">E\u0007 l órgano competente para la incoación del procedimiento sancionador podrá acordar, al tiempo de iniciarse el procedimiento o durante su tramitación, la constitución de garantía suficiente para hacer frente a las responsabilidades a que hubiera lugar. En el caso de los procedimientos por incumplimiento de la obligación de declaración establecida en el artículo 34, de conformidad con el artículo 35.2 se entenderá constituida en garantía, pudiendo acordarse por el secretario de la Comisión durante la instrucción del procedimiento sancionador la ampliación o reducción de la referida garantía. E\u0007 n el caso de que hubiera sido interpuesta por el interesado reclamación contra la intervención provisional de medios de pago en los términos previstos en el artículo 35.5, la persona titular de la Secretaría de la Comisión resolverá dicha reclamación, en su caso, en el acuerdo de iniciación del procedimiento sancionador, pudiendo el interesado formular las alegaciones que considere oportunas, que serán resueltas en la resolución por la que se acuerde la terminación del procedimiento administrativo sancionador. E\u0007 l procedimiento sancionador aplicable al incumplimiento de las obligaciones previstas en esta ley será el previsto, con carácter general, para el ejercicio de la potestad sancionadora por las Administraciones Públicas.</span></span> 3. <mark class=\"m-accion\">Será</mark> <mark class=\"m-personalizado\">competente para</mark> <mark class=\"m-destacable\">imponer</mark> <mark class=\"m-personalizado\">las sanciones</mark> por infracciones <mark class=\"m-personalizado\">muy graves</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1848\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el Consejo de Ministros</mark>, <mark class=\"m-personalizado\">a propuesta</mark> <mark class=\"m-autoridad\">del Ministro de Economía</mark> y Hacienda. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Será competente para imponer las sanciones por</span></span> infracciones <mark class=\"m-personalizado\"><u class=\"m-clave\">graves</u></mark> <mark class=\"m-autoridad\">el Ministro de Economía y Hacienda</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, a propuesta de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias. Será competente para imponer las sanciones por infracciones leves el <mark class=\"m-resp r-ia\" data-q=\"2-ia-1850\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Director General del Tesoro y Política Financiera, a propuesta del instructor</mark>. \u0007Cuando el inculpado sea una entidad financiera o precise de autorización administrativa para operar, será preceptivo para la imposición de sanciones por infracciones graves o muy graves solicitar de la institución u órgano administrativo responsable de su supervisión informe sobre la posible incidencia de la sanción o sanciones propuestas sobre la estabilidad de la entidad objeto del procedimiento. \u0007La competencia para resolver los procedimientos sancionadores por incumplimiento de la obligación de declaración establecida en el artículo 34 corresponderá, a propuesta del instructor y previo informe del Servicio Ejecutivo de la Comisión, al Director General del Tesoro y Política Financiera, cuyas resoluciones pondrán fin a la vía administrativa</span></span>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">3. \u0007Será competente para imponer las sanciones por infracciones muy graves el Consejo de Ministros, a propuesta del Ministro de Economía y Hacienda. Será competente para imponer las sanciones por infracciones graves el Ministro de Economía y Hacienda, a propuesta de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias. Será competente para imponer las sanciones por</span></span> infracciones <mark class=\"m-personalizado\">leves</mark> <mark class=\"m-autoridad\">el Director General del Tesoro y Política Financiera</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, a propuesta del instructor. \u0007Cuando el inculpado sea una entidad financiera o precise de autorización administrativa para operar, será preceptivo para la imposición de sanciones por infracciones graves o muy graves solicitar de la institución u órgano administrativo responsable de su supervisión informe sobre la posible incidencia de la sanción o sanciones propuestas sobre la estabilidad de la entidad objeto del procedimiento. \u0007La competencia para resolver los procedimientos sancionadores por incumplimiento de la obligación de declaración establecida en el artículo 34 corresponderá, a propuesta del instructor y previo informe del Servicio Ejecutivo de la Comisión, al Director General del Tesoro y Política Financiera, cuyas resoluciones pondrán fin a la vía administrativa</span></span>. 4. En los procedimientos <u class=\"m-clave\">sancionadores</u> instruidos <u class=\"m-clave\">por</u> <mark class=\"m-autoridad\">la Secretaría de la Comisión</mark> <mark class=\"m-personalizado\">el <u class=\"m-clave\">plazo máximo</u></mark> para resolver el <mark class=\"m-personalizado\">procedimiento y notificar la resolución</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-autoridad\">de</mark> <mark class=\"m-resp\" data-q=\"2-21,2-ia-1903\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">un año</mark> a contar desde <mark class=\"m-personalizado\">la fecha de notificación del</mark> acuerdo de incoación <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">, sin perjuicio de la posibilidad de suspensión por el instructor del cómputo del plazo en los supuestos señalados en el artículo 42.5 de la Ley 30/1992, de 26 de noviembre, del Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común</span></span></span>, <mark class=\"m-personalizado\">y de</mark> <mark class=\"m-autoridad\">la</mark> ampliación <mark class=\"m-personalizado\">en seis meses</mark> adicionales <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">de dicho plazo máximo que podrá acordarse motivadamente por el Secretario de la Comisión, a propuesta del instructor, al amparo de lo previsto en el artículo 49 de la misma Ley. E\u0007 l transcurso de los plazos establecidos en el apartado precedente determinará la caducidad del procedimiento administrativo sancionador, debiendo procederse a dictar nuevo acuerdo de incoación en tanto no haya prescrito la infracción de conformidad con lo dispuesto en el artículo 60</span></span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1854\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 61 — Ejecución de las resoluciones sancionadoras <span class=\"ex-sello ex-sello-r\">R22</span></div><div class=\"ex-fb\"><p data-r=\"R22\"><span class=\"ex-sello ex-sello-r\">R22</span> <b>5.</b> <mark class=\"m-destacable\">La ejecución</mark> <mark class=\"m-personalizado\">de las resoluciones sancionadoras firmes</mark> en vía administrativa <mark class=\"m-accion\">corresponderá</mark> <mark class=\"m-personalizado\">a</mark> <span class=\"m-caja\">la</span> <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"2-137\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretaría de la Comisión</mark>.</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 62 y 63 — Vinculación con el orden penal y comunicación de infracciones</div><div class=\"ex-fb\"><p><b>Art. 62.</b> <mark class=\"m-destacable\">4. Si el</mark> <mark class=\"m-autoridad\">Ministerio Fiscal</mark> no encontrara méritos para proceder penalmente (…), <mark class=\"m-resp r-ia\" data-q=\"2-ia-1648,2-ia-1867\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">lo comunicará a la Secretaría de la Comisión para que pueda continuar el procedimiento administrativo sancionador</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1859\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-personalizado\">Art.</mark> 63.</b> 2. (…) <mark class=\"m-personalizado\">Mediante</mark> <mark class=\"m-destacable\">orden</mark> <mark class=\"m-personalizado\">del</mark> <mark class=\"m-resp\" data-q=\"2-26\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Ministro de Economía y Empresa</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">aprobará</mark> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-destacable\">modelo</mark> <mark class=\"m-personalizado\">de comunicación y</mark> se <mark class=\"m-accion\">establecerán</mark> las <mark class=\"m-personalizado\">características y requisitos del canal de recepción</mark> de comunicaciones (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Disposición adicional — Registro de Titularidades Reales <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\">Mediante real decreto se <mark class=\"m-accion\">creará</mark> <mark class=\"m-resp\" data-q=\"2-37,2-ia-1914\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">en el Ministerio de Justicia</mark> el <mark class=\"m-destacable\">Registro de Titularidades Reales</mark>, <mark class=\"m-destacable\">registro central y único en todo el territorio nacional</mark> (…). <mark class=\"m-destacable\">El Registro de Titularidades Reales</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">gestionado por el</mark> <mark class=\"m-resp\" data-q=\"2-37\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Ministerio de Justicia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, que además de los datos recabados de manera directa, centralizará la información de titularidad real disponible en los Registros de Fundaciones, Asociaciones, Mercantil y otros registros que puedan recoger la información de las entidades inscritas, así como la obtenida por el Consejo General del Notariado</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1909\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Disposiciones adicionales cuarta, quinta y sexta — Acceso al Registro de Titularidades Reales y plazos <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><mark class=\"m-destacable\">DA 4.ª</mark> 1. <mark class=\"m-accion\">Corresponderá</mark> al <mark class=\"m-autoridad\">Ministerio de Justicia</mark> <mark class=\"m-destacable\">garantizar y controlar el acceso</mark> a la información contenida en <mark class=\"m-destacable\">el Registro de Titularidades Reales</mark> en las condiciones establecidas en la ley y las que reglamentariamente <mark class=\"m-destacable\">se</mark> determinen.</p><p data-ex=\"*\">La <mark class=\"m-personalizado\">persona titular</mark> de <mark class=\"m-autoridad\">la <mark class=\"m-resp r-ia\" data-q=\"2-ia-1921\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Dirección General de Seguridad Jurídica y Fe Pública</mark></mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-autoridad\">la encargada del Registro. Las</mark> Resoluciones de la persona encargada <mark class=\"m-personalizado\">del Registro</mark> de Titularidades <mark class=\"m-personalizado\">Reales</mark> por las que se deniegue el <mark class=\"m-personalizado\">acceso</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">ser recurridas</mark> en alzada ante el <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-accion\">superior</mark> <mark class=\"m-personalizado\">jerárquico del</mark> que dependa, cuyas resoluciones <mark class=\"m-accion\">pondrán</mark> fin <mark class=\"m-personalizado\">a la vía administrativa.</mark> <mark class=\"m-resp ex-q\" data-q=\"2-176\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><mark class=\"m-personalizado\">DA</mark> 5.ª En el plazo máximo de doce meses desde la entrada en vigor de esta ley, <mark class=\"m-personalizado\">el Servicio</mark> <mark class=\"m-destacable\">Ejecutivo</mark> de la <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-accion\">establecerá</mark> la <mark class=\"m-destacable\">forma y plazo para</mark> realizar <mark class=\"m-destacable\">la declaración inicial de las</mark> <mark class=\"m-plazo\">cuentas de pago</mark> y cajas de seguridad a que se refiere el artículo 43 de <mark class=\"m-destacable\">la Ley 10/2010, de</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">28 de abril, de prevención del blanqueo de capitales y de la financiación del terrorismo, que se encuentren activas a la fecha que se indique.</span></span></p><p data-ex=\"*\">DA 6.ª En el plazo de seis meses, el <mark class=\"m-autoridad\">Gobierno,</mark> a propuesta del Ministro de Justicia, <mark class=\"m-accion\">aprobará</mark> el reglamento por el que se <mark class=\"m-accion\">creará</mark> en el <mark class=\"m-autoridad\">Ministerio</mark> de Justicia el <mark class=\"m-resp r-ia\" data-q=\"2-ia-1924\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Registro de Titularidades Reales</mark>, registro central y único en todo el territorio nacional</p></div></div><div class=\"bloque-titulo\">2.4 — <mark class=\"m-personalizado\">CONVENCIÓN</mark> <mark class=\"m-autoridad\">DE LAS NACIONES UNIDAS</mark> CONTRA LA DELINCUENCIA ORGANIZADA TRANSNACIONAL (<mark class=\"m-personalizado\">CONVENCIÓN</mark> DE PALERMO), HECHA EN NUEVA YORK EL 15 DE NOVIEMBRE DE 2000</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 1 y 2 — Finalidad y definiciones <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>Art. 1.</b> El propósito de la presente Convención es <mark class=\"m-resp r-ia\" data-q=\"2-ia-2001\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">promover la cooperación para prevenir y combatir más eficazmente la delincuencia organizada transnacional</mark>.</p><p data-ex=\"*\"><b>Art. 2.</b> a) Por «grupo delictivo organizado» se <mark class=\"m-accion\">entenderá</mark> un <mark class=\"m-personalizado\"><u class=\"m-clave\">grupo estructurado</u> de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2002\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">tres o más personas que exista durante cierto tiempo y que actúe concertadamente</mark> <mark class=\"m-personalizado\">con el propósito de cometer <u class=\"m-clave\">uno o más</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">delitos graves</mark></span> o delitos <mark class=\"m-personalizado\">tipificados con arreglo</mark> a la presente <mark class=\"m-personalizado\"><u class=\"m-clave\">Convención</u></mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2002,2-ia-2302\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">con miras a obtener, directa o indirectamente, un beneficio económico u otro beneficio de orden material</mark>; b) por <mark class=\"m-personalizado\">«delito grave» se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">la conducta que constituya un delito punible con una privación de libertad</mark> máxima <mark class=\"m-personalizado\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1101,2-ia-2003\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">al menos cuatro años o con una pena más grave</mark>; c) por «grupo <mark class=\"m-personalizado\">estructurado» se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">un grupo no formado fortuitamente para la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">inmediata de un delito</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y en el que no necesariamente se haya asignado a sus miembros funciones formalmente definidas ni haya continuidad en la condición de miembro o exista una estructura desarrollada</span></span>; d) por «bienes» se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1739,2-ia-2319\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los activos de cualquier tipo, corporales o incorporales, muebles o inmuebles, tangibles o intangibles</mark>, y los documentos <mark class=\"m-personalizado\">o</mark> instrumentos legales <mark class=\"m-personalizado\">que acrediten la</mark> propiedad u otros derechos sobre dichos activos; e) por «producto del delito» se <mark class=\"m-accion\">entenderá</mark> los bienes de cualquier índole derivados u <mark class=\"m-personalizado\">obtenidos</mark> directa o indirectamente de la <mark class=\"m-autoridad\">comisión</mark> de un delito; f) <mark class=\"m-destacable\"><u class=\"m-clave\">por «embargo preventivo» o «incautación» se</u></mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp\" data-q=\"2-65,2-ia-2005,2-ia-2047\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">la prohibición temporal de transferir, convertir, enajenar o mover bienes, o la custodia o el control temporales de bienes por mandamiento expedido por un tribunal u otra autoridad competente</mark>; g) <mark class=\"m-destacable\"><u class=\"m-clave\">por «decomiso» se</u></mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1838,2-ia-2006\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la privación con carácter definitivo de bienes por decisión de un tribunal</mark> o de <mark class=\"m-personalizado\">otra</mark> <mark class=\"m-autoridad\">autoridad</mark> competente; h) <mark class=\"m-autoridad\">por «delito determinante» se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-autoridad\">todo delito del</mark> <mark class=\"m-personalizado\">que se</mark> <mark class=\"m-destacable\">derive un producto</mark> <mark class=\"m-personalizado\">que pueda pasar a constituir materia de un delito definido en el <span class=\"ref-art\">artículo 6</span></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la presente Convención</span></span>; i) por <mark class=\"m-resp\" data-q=\"2-106,2-ia-1524,2-ia-2008,2-ia-2154,2-ia-2162,2-ia-2205,2-ia-2409\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">«entrega vigilada»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-destacable\">la <u class=\"m-clave\">técnica</u></mark> consistente en dejar que <mark class=\"m-resp r-ia\" data-q=\"2-ia-2008\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">remesas ilícitas o sospechosas salgan del territorio de uno o más Estados, lo atraviesen o entren en él, con el conocimiento y bajo la supervisión de sus autoridades competentes</mark>, con el <mark class=\"m-personalizado\">fin de investigar</mark> delitos <mark class=\"m-personalizado\">e identificar</mark> a las personas involucradas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en la comisión de éstos; j) \u0007Por «organización regional de integración económica» se entenderá una organización constituida por Estados soberanos de una región determinada, a la que sus Estados miembros han transferido competencia en las cuestiones regidas por la presente Convención y que ha sido debidamente facultada, de conformidad con sus procedimientos internos, para firmar, ratificar, aceptar o aprobar la Convención o adherirse a ella; las referencias a los «Estados Parte» con arreglo a la presente Convención se aplicarán a esas organizaciones dentro de los límites de su competencia</span></span>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 3 y 4 — Ámbito de aplicación y protección de la soberanía · R23 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R23</span></div><div class=\"ex-fb\"><p data-ex=\"EX,*\"><b>Art. 3.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 3. ÁMBITO DE APLICACIÓN. 1. \u0007A menos que contenga una disposición en contrario,</span></span> la presente Convención <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">aplicará</mark> <mark class=\"m-personalizado\">a la prevención</mark>, <mark class=\"m-personalizado\">la investigación y el enjuiciamiento de:</mark> a) los <mark class=\"m-personalizado\">delitos tipificados</mark> con arreglo a los <mark class=\"m-personalizado\"><span class=\"ref-art\">artículos 5, 6, 8 y 23</span></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">4 de la presente Convención</span></span>; <mark class=\"m-destacable\">y</mark> b) los <mark class=\"m-personalizado\">delitos graves</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que se definen en el artículo 2 de la presente Convención</span></span>; cuando esos delitos sean de carácter <mark class=\"m-personalizado\">transnacional <u class=\"m-clave\">y</u></mark> entrañen la participación de un <mark class=\"m-personalizado\">grupo delictivo organizado</mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">A\u0007 los efectos del párrafo 1 del presente artículo,</span></span> <mark class=\"m-personalizado\">el delito</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">carácter transnacional</mark> si: a) <mark class=\"m-personalizado\">se comete en más de un</mark> <mark class=\"m-autoridad\">Estado;</mark> b) <mark class=\"m-resp\" data-q=\"2-177,2-ia-2010,2-ia-2011\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">se comete dentro de un solo Estado pero una parte sustancial de su preparación, planificación, dirección o control se realiza en otro Estado</mark>; c) <mark class=\"m-personalizado\">se comete</mark> dentro de <mark class=\"m-personalizado\">un solo</mark> <mark class=\"m-autoridad\">Estado</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">pero</mark></span> <mark class=\"m-personalizado\">entraña la participación de un grupo delictivo organizado</mark> que realiza <mark class=\"m-personalizado\"><u class=\"m-clave\">actividades</u></mark> delictivas <mark class=\"m-personalizado\">en <u class=\"m-clave\">más</u> de un</mark> <mark class=\"m-autoridad\">Estado;</mark> o d) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1937,2-ia-2012\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se comete en un solo Estado pero tiene efectos sustanciales en otro Estado</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1541\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-r=\"R23\"><span class=\"ex-sello ex-sello-r\">R23</span> <b>Art. 4.</b> 1. <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">cumplirán</mark> <mark class=\"m-personalizado\">sus obligaciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con arreglo a la presente Convención</span></span> <mark class=\"m-personalizado\">en consonancia con los</mark> <mark class=\"m-destacable\">principios</mark> de igualdad <mark class=\"m-destacable\">soberana e integridad territorial</mark> de los <mark class=\"m-autoridad\">Estados</mark>, así como de <mark class=\"m-resp r-ia\" data-q=\"2-ia-2013\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no intervención en los asuntos internos de otros Estados</mark> (<mark class=\"m-resp\" data-q=\"2-ia-2014,2-138\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">protección de la soberanía</mark>). 2. (…) <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">facultará</mark> a un <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-personalizado\">para ejercer</mark>, <mark class=\"m-personalizado\">en el territorio de otro</mark> <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-personalizado\">jurisdicción o funciones</mark> que el derecho interno de ese <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">reserve exclusivamente a sus</mark> <mark class=\"m-autoridad\">autoridades</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 5 — Penalización de la participación en un grupo delictivo organizado</div><div class=\"ex-fb\"><p><b>1.</b> <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">adoptará las medidas</mark> (…) <mark class=\"m-personalizado\">para tipificar como delito</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1207\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando se cometan intencionalmente</mark>: a) <mark class=\"m-personalizado\">i)</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1433,2-ia-2017\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el acuerdo con una o más personas de cometer un delito grave con un propósito que guarde relación directa o indirecta con la obtención de un beneficio económico u otro beneficio de orden material</mark> (…); ii) <mark class=\"m-personalizado\">la conducta</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de toda persona que, <mark class=\"m-destacable\"><u class=\"m-clave\">a sabiendas</u></mark> de la <mark class=\"m-personalizado\">finalidad y actividad</mark> delictiva general de un <mark class=\"m-personalizado\"><u class=\"m-clave\">grupo</u> delictivo organizado</mark> (…), <mark class=\"m-personalizado\">participe activamente en</mark> (…) <mark class=\"m-personalizado\">actividades</mark> ilícitas <mark class=\"m-personalizado\">del grupo</mark> (…);</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">b) <mark class=\"m-personalizado\">la organización</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">dirección</u></mark>, <mark class=\"m-personalizado\">ayuda, incitación</mark>, <mark class=\"m-personalizado\">facilitación <u class=\"m-clave\">o asesoramiento</u></mark> en aras de la <mark class=\"m-autoridad\">comisión</mark> de un <mark class=\"m-personalizado\"><u class=\"m-clave\">delito</u> grave</mark> que entrañe la <mark class=\"m-personalizado\">participación de un</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">grupo</mark></span> <mark class=\"m-personalizado\">delictivo</mark> organizado.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2015\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>2.</b> El <mark class=\"m-personalizado\">conocimiento</mark>, <mark class=\"m-personalizado\">la intención</mark>, <mark class=\"m-personalizado\">la finalidad</mark>, <mark class=\"m-personalizado\">el propósito o el acuerdo</mark> (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2018\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">podrán inferirse de circunstancias fácticas objetivas</mark>.</p><p><b>3.</b> (…) los <mark class=\"m-autoridad\">Estados</mark> Parte cuyo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">derecho interno requiera la <mark class=\"m-autoridad\">comisión</mark> de un acto que tenga por objeto</span></span> llevar adelante el acuerdo (…), <mark class=\"m-resp r-ia\" data-q=\"2-ia-2019\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">lo notificarán al Secretario General de las Naciones Unidas en el momento de la firma o del depósito de su instrumento de ratificación</mark> (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 6 y 7 — Blanqueo del producto del delito y medidas para combatirlo <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 6.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. C\u0007 ada Estado Parte adoptará, de conformidad con los principios fundamentales de su derecho interno, las medidas legislativas y de otra índole que sean necesarias para</span></span> <mark class=\"m-personalizado\">tipificar como delito</mark>, <mark class=\"m-personalizado\">cuando se cometan <u class=\"m-clave\">intencionalmente</u></mark>: a) i) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1434,2-ia-2007,2-ia-2021,2-ia-2022\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la conversión o la transferencia de bienes, a sabiendas de que esos bienes son producto del delito, con el propósito de ocultar o disimular el origen ilícito</mark> de los bienes <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">ayudar</u> a</mark> cualquier persona involucrada en la <mark class=\"m-autoridad\">comisión</mark> del delito determinante <mark class=\"m-personalizado\"><u class=\"m-clave\">a</u> eludir las consecuencias jurídicas</mark> de sus actos; ii) <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">ocultación o</u> disimulación</mark> <mark class=\"m-personalizado\">de la verdadera naturaleza</mark>, <mark class=\"m-personalizado\">origen, ubicación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, disposición, movimiento o propiedad</span></span> de bienes <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o del legítimo derecho a éstos, a sabiendas de que dichos bienes son producto del delito</span></span>; (…)</p><p><b>2.</b> c) (…) <mark class=\"m-personalizado\">los delitos</mark> cometidos <span class=\"m-circulo\"><mark class=\"m-personalizado\">fuera</mark></span> de la jurisdicción de un <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">constituirán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">delito</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">determinante</mark></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2024,2-ia-2335\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">siempre y cuando el acto correspondiente sea delito con arreglo al derecho interno del Estado en que se haya cometido y constituyese asimismo delito con arreglo al derecho interno del Estado Parte</mark> que <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">aplique (…) el presente artículo si el delito se hubiese cometido allí;</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">d) <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-accion\">proporcionará</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Secretario General de las Naciones Unidas</mark> <mark class=\"m-personalizado\">una copia de <u class=\"m-clave\">sus leyes</u></mark> (…);</span></span> e) <mark class=\"m-personalizado\">si así lo requieren</mark> los principios fundamentales del <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">derecho interno</mark> (…), <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">disponerse</mark> que los</span></span> delitos tipificados en el <mark class=\"m-personalizado\">párrafo 1</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2025,2-ia-2329\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no se aplicarán a las personas que hayan cometido el delito determinante</mark>.</p><p><b>Art. 7.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. <mark class=\"m-autoridad\">Cada Estado Parte</mark>: a) <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">un amplio régimen interno de reglamentación y supervisión de los bancos y las instituciones financieras no bancarias</mark> (…);</span></span> b) <mark class=\"m-accion\">garantizará</mark> (…) <mark class=\"m-personalizado\">que las</mark> <mark class=\"m-autoridad\">autoridades</mark> (…) <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">sean capaces de cooperar e intercambiar</mark> información (…) y, a tal fin,</span></span> <mark class=\"m-accion\">considerará</mark> la posibilidad de <mark class=\"m-personalizado\">establecer</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2027\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">una dependencia de inteligencia financiera que sirva de centro nacional de recopilación, análisis y difusión de información sobre posibles actividades de blanqueo de dinero</mark>. (…) 3. (…) <mark class=\"m-personalizado\">se insta a</mark> <mark class=\"m-autoridad\">los Estados Parte</mark> <mark class=\"m-personalizado\">a que</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2029\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">utilicen como guía las iniciativas pertinentes de las organizaciones regionales, interregionales y multilaterales</mark> <mark class=\"m-personalizado\">de lucha contra el blanqueo</mark> de dinero. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2323\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 7 — Medidas para combatir el blanqueo de dinero (cooperación) <span class=\"ex-sello ex-sello-r\">R24</span></div><div class=\"ex-fb\"><p data-r=\"R24\"><span class=\"ex-sello ex-sello-r\">R24</span> <b>4.</b> Los <mark class=\"m-autoridad\">Estados</mark> Parte se <mark class=\"m-accion\">esforzarán</mark> por establecer y promover la cooperación a escala <mark class=\"m-resp\" data-q=\"2-139\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">mundial, regional, subregional y bilateral</mark> entre las <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2030\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">judiciales, de cumplimiento de la ley y de reglamentación financiera</mark> a fin de combatir el blanqueo de dinero.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 8, 10 y 11 — Corrupción, personas jurídicas y proceso, fallo y sanciones · R24 <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. <mark class=\"m-destacable\">8.</mark></b> 1. <mark class=\"m-autoridad\">Cada Estado</mark> <mark class=\"m-personalizado\">Parte</mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">las</mark> medidas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">legislativas y de otra índole que sean necesarias</span></span> <mark class=\"m-personalizado\">para tipificar como delito</mark>, cuando <mark class=\"m-personalizado\">se cometan intencionalmente</mark>: <mark class=\"m-plazo\">a)</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2032,2-ia-2143\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la promesa, el ofrecimiento o la concesión a un funcionario público</mark>, <mark class=\"m-personalizado\">directa o indirectamente</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2031\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">de un beneficio indebido</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que redunde en su propio provecho o en el de otra persona o entidad</span></span>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1827\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">con el fin de que dicho funcionario actúe o se abstenga de actuar en el cumplimiento de sus funciones oficiales</mark>; b) <mark class=\"m-destacable\"><u class=\"m-clave\">la solicitud</u></mark> <mark class=\"m-personalizado\">o <u class=\"m-clave\">aceptación</u> por</mark> <mark class=\"m-autoridad\">un funcionario público</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, directa o indirectamente,</span></span> de un beneficio indebido <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que redunde en su propio provecho o en el de otra persona o entidad, con el fin de que dicho funcionario actúe o se abstenga de actuar en el cumplimiento de sus funciones oficiales</span></span>. 2. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2032\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">considerará la posibilidad de adoptar</mark> <mark class=\"m-personalizado\">las medidas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">legislativas y de otra índole que sean necesarias</span></span> para <mark class=\"m-personalizado\">tipificar</mark> como delito los actos a que <u class=\"m-clave\">se refiere el</u> <mark class=\"m-personalizado\">párrafo 1</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente artículo</span></span> cuando <u class=\"m-clave\">esté</u> involucrado en ellos <mark class=\"m-autoridad\">un funcionario público</mark> extranjero o un funcionario internacional <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Del mismo modo, cada Estado Parte considerará la posibilidad de tipificar como delito otras formas de corrupción</span></span>.</p><p><b>Art. 10.</b> 2. Con sujeción a los <mark class=\"m-personalizado\">principios jurídicos del</mark> <mark class=\"m-autoridad\">Estado Parte</mark>, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\">responsabilidad</mark> de las <mark class=\"m-autoridad\">personas jurídicas</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1228\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">índole penal, civil o administrativa</mark>. 3. Dicha responsabilidad <mark class=\"m-accion\">existirá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1210,2-ia-1326\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sin perjuicio de la responsabilidad penal que incumba a las personas naturales que hayan perpetrado los delitos</mark>. <mark class=\"m-destacable\">4.</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) <mark class=\"m-destacable\">sanciones</mark> <mark class=\"m-personalizado\">penales o no penales</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">eficaces</u></mark>, proporcionadas <mark class=\"m-destacable\">y</mark> disuasivas, incluidas <mark class=\"m-destacable\">sanciones</mark> monetarias (…).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2036\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 11.</b> 3. (…) <mark class=\"m-personalizado\">al imponer condiciones</mark> en relación con la <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">decisión de <mark class=\"m-personalizado\"><u class=\"m-clave\">conceder la libertad</u></mark> en espera de juicio o la apelación</span></span> se tenga presente la <mark class=\"m-personalizado\">necesidad de</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1002,2-ia-2038\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">garantizar la comparecencia del acusado en todo procedimiento penal ulterior</mark>. (…) 5. Cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">establecerá</mark>, cuando proceda (…), <mark class=\"m-personalizado\">un</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2040\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">plazo de prescripción prolongado</mark> dentro del cual <mark class=\"m-personalizado\">pueda iniciarse el proceso</mark> (…) <mark class=\"m-destacable\">y</mark> un plazo <mark class=\"m-personalizado\">mayor cuando</mark> el presunto delincuente <mark class=\"m-personalizado\">haya eludido la administración de <u class=\"m-clave\">justicia</u></mark> .</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 12, 13 y 14 — Decomiso, cooperación para el decomiso y disposición de los bienes</div><div class=\"ex-fb\"><p><b>Art. 12.</b> 4. <mark class=\"m-personalizado\">Cuando</mark> el producto del <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">delito se haya <mark class=\"m-destacable\">mezclado</mark> <mark class=\"m-personalizado\">con bienes adquiridos de <u class=\"m-clave\">fuentes lícitas</u></mark>,</span></span> esos <mark class=\"m-personalizado\">bienes</mark> <mark class=\"m-accion\">podrán</mark> (…) <mark class=\"m-personalizado\">ser objeto de decomiso</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2042\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">hasta el valor estimado del producto entremezclado</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) 6. (…) cada <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-accion\">facultará</mark> a <mark class=\"m-personalizado\">sus</mark> <mark class=\"m-autoridad\">tribunales</mark> <mark class=\"m-personalizado\">u otras</mark> <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-personalizado\">competentes para ordenar la presentación o la incautación de documentos bancarios</mark>, <mark class=\"m-personalizado\">financieros o comerciales</mark>.</span></span> Los <mark class=\"m-autoridad\">Estados</mark> Parte no <mark class=\"m-accion\">podrán</mark> negarse a aplicar las disposiciones del presente párrafo <mark class=\"m-resp r-ia\" data-q=\"2-ia-2044\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">amparándose en el secreto bancario</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2043\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 13.</b> 5. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">proporcionará</mark> <mark class=\"m-resp\" data-q=\"2-3,2-74\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">al Secretario General de las Naciones Unidas una copia de sus leyes y reglamentos</mark> destinados a dar aplicación al presente artículo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y de cualquier enmienda ulterior que se haga a tales leyes y reglamentos o una descripción de ésta</span></span>. 6. Si <mark class=\"m-autoridad\">un Estado Parte opta</mark> por <mark class=\"m-personalizado\"><u class=\"m-clave\">supeditar la adopción</u> de las medidas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mencionadas en los párrafos 1 y 2 del presente artículo</span></span> <mark class=\"m-personalizado\">a la <u class=\"m-clave\">existencia de un tratado</u></mark> pertinente, ese <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-resp r-ia\" data-q=\"2-ia-2046,2-ia-2049\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">considerará la presente Convención como la base de derecho necesaria y suficiente</mark> para cumplir ese requisito. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2103\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 14.</b> 2. (…) <mark class=\"m-autoridad\">los Estados Parte</mark> (…) <mark class=\"m-accion\">darán</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2051,2-ia-2052\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">consideración prioritaria a la devolución del producto del delito o de los bienes decomisados al Estado Parte requirente a fin de que éste pueda indemnizar a las víctimas del delito o devolver ese producto del delito o esos bienes a sus propietarios legítimos</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 15 — Jurisdicción <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>1.</b> <mark class=\"m-autoridad\">Cada Estado</mark> Parte <mark class=\"m-accion\">adoptará</mark> las <mark class=\"m-personalizado\">medidas</mark> que sean necesarias para <mark class=\"m-personalizado\">establecer su jurisdicción</mark> respecto <mark class=\"m-autoridad\">de los</mark> <mark class=\"m-personalizado\">delitos tipificados</mark> con arreglo a los <span class=\"ref-art\">artículos 5, 6, 8 y 23</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la presente Convención</span></span> cuando: a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2053\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el delito se cometa en su territorio</mark>; <mark class=\"m-destacable\">o</mark> b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2053\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el delito se cometa a bordo de un buque que enarbole su pabellón</mark> <mark class=\"m-personalizado\">o de una aeronave registrada conforme a sus leyes</mark> en el <mark class=\"m-autoridad\">momento</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">del delito</mark>.</p><p data-ex=\"EX\"><b>2.</b> Con sujeción a lo dispuesto en el <span class=\"ref-art\">artículo 4</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la presente Convención</span></span>, un <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-personalizado\">también</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">establecer su jurisdicción</mark> para conocer de tales <mark class=\"m-personalizado\">delitos cuando:</mark> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1217\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el delito se cometa contra uno de sus nacionales</mark>; b) <mark class=\"m-resp\" data-q=\"2-67,2-ia-1006,2-ia-1218,2-ia-2054\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el delito sea cometido por uno de sus nacionales o por una persona apátrida que tenga residencia habitual en su territorio</mark>; <mark class=\"m-personalizado\">o</mark> c) el <mark class=\"m-destacable\">delito</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">: i) \u0007Sea uno de los delitos tipificados con arreglo al párrafo 1 del artículo 5 de la presente Convención y</span></span> <mark class=\"m-personalizado\">se cometa fuera de su territorio con miras a la</mark> <mark class=\"m-autoridad\">comisión</mark> de un delito grave <mark class=\"m-personalizado\">dentro de su territorio</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">; ii) S\u0007 ea uno de los delitos tipificados con arreglo al inciso ii) del apartado b) del párrafo 1 del artículo 6 de la presente Convención y se cometa fuera de su territorio con miras a la comisión, dentro de su territorio, de un delito tipificado con arreglo a los incisos i) o ii) del apartado a) o al inciso i) del apartado b) del párrafo 1 del artículo 6 de la presente Convención</span></span>.</p><p data-ex=\"EX\"><b>3.</b> A los efectos del párrafo 10 del <span class=\"ref-art\">artículo 16</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la presente Convención</span></span>, cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">adoptará</mark> las medidas que sean necesarias para establecer su jurisdicción <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">respecto de los delitos comprendidos en la presente Convención</span></span> cuando el presunto delincuente se encuentre en su territorio y el <mark class=\"m-autoridad\">Estado</mark> Parte no lo extradite <mark class=\"m-resp r-ia\" data-q=\"2-ia-2055\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">por el solo hecho de ser uno de sus nacionales</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 16 y 17 — Extradición y traslado de condenados <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>Art. 16.</b> 10. El <mark class=\"m-autoridad\">Estado Parte en</mark> <mark class=\"m-personalizado\">cuyo territorio se encuentre un presunto delincuente</mark>, si no <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">lo <mark class=\"m-destacable\">extradita</mark> (…) <mark class=\"m-personalizado\">por</mark> el solo hecho de <mark class=\"m-personalizado\">ser uno de sus nacionales</mark>, <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">obligado</mark>, previa solicitud del <mark class=\"m-autoridad\">Estado</mark> Parte</span></span> que pide la extradición, a <mark class=\"m-resp r-ia\" data-q=\"2-ia-1518,2-ia-2064,2-ia-2101\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">someter el caso sin demora injustificada a sus autoridades competentes a efectos de enjuiciamiento</mark> (…).</p><p data-ex=\"EXOF\"><b>12.</b> Si <mark class=\"m-personalizado\">la extradición</mark> solicitada con el <mark class=\"m-personalizado\">propósito</mark> de que se <mark class=\"m-destacable\">cumpla una condena</mark> es denegada por el hecho de que la persona buscada <mark class=\"m-personalizado\">es nacional</mark> del <mark class=\"m-autoridad\">Estado</mark> Parte requerido, éste, <mark class=\"m-personalizado\">si</mark> su derecho interno lo <mark class=\"m-destacable\">permite</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y de conformidad con los requisitos de dicho derecho</span></span>, <mark class=\"m-accion\">considerará</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, previa solicitud del Estado Parte requirente,</span></span> <mark class=\"m-personalizado\">la posibilidad de</mark> <mark class=\"m-resp\" data-q=\"2-112,2-ia-2057,2-ia-2102\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">hacer cumplir la condena impuesta o el resto pendiente de dicha condena con arreglo al derecho interno del Estado Parte requirente</mark>.</p><p data-ex=\"*\"><b>14.</b> <mark class=\"m-destacable\">Nada</mark> de lo dispuesto <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en la presente Convención</span></span> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">interpretarse como la imposición de una obligación de extraditar</mark> si el <mark class=\"m-autoridad\">Estado Parte requerido</mark> tiene <mark class=\"m-personalizado\">motivos justificados</mark> para presumir que <mark class=\"m-personalizado\">la solicitud se ha presentado con el fin de perseguir</mark> o castigar a una persona por razón de <mark class=\"m-personalizado\">su sexo, raza, religión</mark>, <mark class=\"m-personalizado\">nacionalidad</mark>, <mark class=\"m-personalizado\">origen étnico u opiniones políticas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o que su cumplimiento ocasionaría perjuicios a la posición de esa persona por cualquiera de estas razones</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-179,2-ia-2104\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p><b>15.</b> <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2058,2-ia-2059,2-ia-2060,2-ia-2105\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no podrán denegar una solicitud de extradición únicamente porque se considere que el delito también entraña cuestiones tributarias</mark>.</p><p><b>16.</b> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2062\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Antes de denegar la extradición</mark>, el <mark class=\"m-autoridad\">Estado</mark> Parte requerido, cuando proceda, <mark class=\"m-resp\" data-q=\"2-78,2-ia-2061,2-ia-2106\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">consultará al Estado Parte requirente para darle amplia oportunidad de presentar sus opiniones</mark> <mark class=\"m-personalizado\">y de proporcionar información pertinente a su alegato</mark>.</p><p><b>17.</b> Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-resp\" data-q=\"2-7\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">procurarán celebrar acuerdos o arreglos bilaterales y multilaterales para llevar a cabo la extradición o aumentar su eficacia</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 17 — Traslado de personas condenadas a cumplir una pena <span class=\"ex-sello ex-sello-r\">R25</span></div><div class=\"ex-fb\"><p data-r=\"R25\"><span class=\"ex-sello ex-sello-r\">R25</span> Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-accion\">podrán</mark> considerar la posibilidad de celebrar acuerdos <mark class=\"m-accion\">o</mark> arreglos bilaterales <mark class=\"m-destacable\">o</mark> multilaterales sobre el traslado a su territorio de toda persona <mark class=\"m-accion\">que</mark> haya sido condenada <mark class=\"m-accion\">a</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">pena de prisión o a otra pena de privación de libertad por algún delito comprendido en</span></span> la presente Convención <mark class=\"m-personalizado\">a fin</mark> de que <mark class=\"m-resp r-ia\" data-q=\"2-ia-2107\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">complete allí su condena</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-140,2-ia-2050,2-ia-2141,2-ia-2206\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 4 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 18 — Asistencia judicial recíproca <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R26</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF,EX,*\"><b>5.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">L\u0007 a transmisión de información con arreglo al párrafo 4 del presente artículo se hará sin perjuicio de las indagaciones y procesos penales que tengan lugar en el Estado de las autoridades competentes que facilitan la información. Las autoridades competentes que reciben la información deberán acceder a toda solicitud de que se respete su carácter confidencial, incluso temporalmente, o de que se impongan restricciones a su utilización.</span></span> Sin embargo, <mark class=\"m-personalizado\">ello</mark> no <mark class=\"m-accion\">obstará</mark> para que el <mark class=\"m-autoridad\">Estado</mark> Parte receptor revele, en sus actuaciones, <mark class=\"m-destacable\">información que sea exculpatoria de</mark> una persona acusada. <mark class=\"m-personalizado\">En tal caso,</mark> <mark class=\"m-resp\" data-q=\"2-180,2-ia-2112\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el Estado Parte receptor notificará al Estado Parte transmisor antes de revelar dicha información</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y, si así se le solicita, consultará al Estado Parte transmisor. Si, en un caso excepcional, no es posible notificar con antelación, el Estado Parte receptor informará sin demora al Estado Parte transmisor de dicha revelación</span></span>.</p><p data-ex=\"EXOF,EX,*\"><b>8.</b> <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-resp\" data-q=\"2-70,2-ia-2114,2-ia-2124\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">no invocarán el secreto bancario para denegar la asistencia judicial recíproca</mark> con arreglo al presente artículo.</p><p data-ex=\"EXOF,EX,*\"><b>13.</b> Cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">designará</mark> <mark class=\"m-destacable\">a</mark> <mark class=\"m-personalizado\">una</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2531\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">autoridad central</mark> <mark class=\"m-personalizado\">encargada de recibir solicitudes de asistencia judicial recíproca</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y facultada para darles cumplimiento o para transmitirlas a las autoridades competentes para su ejecución. Cuando alguna región o algún territorio especial de un Estado Parte disponga de un régimen distinto de asistencia judicial recíproca, el Estado Parte podrá designar a otra autoridad central que desempeñará la misma función para dicha región o dicho territorio. Las autoridades centrales velarán por el rápido y adecuado cumplimiento o transmisión de las solicitudes recibidas. Cuando la autoridad central transmita la solicitud a una autoridad competente para su ejecución, alentará la rápida y adecuada ejecución de la solicitud por parte de dicha autoridad. Cada Estado Parte notificará al Secretario General de las Naciones Unidas, en el momento de depositar su instrumento de ratificación, aceptación o aprobación de la presente Convención o de adhesión a ella, el nombre de la autoridad central que haya sido designada a tal fin. Las solicitudes de asistencia judicial recíproca y cualquier otra comunicación pertinente serán transmitidas a las autoridades centrales designadas por los Estados Parte. La presente disposición no afectará al derecho de cualquiera de los Estados Parte a exigir que estas solicitudes y comunicaciones le sean enviadas por vía diplomática y, en circunstancias urgentes, cuando los Estados Parte convengan en ello, por conducto de la Organización Internacional de Policía Criminal, de ser posible</span></span>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">13. Cada Estado Parte designará a una autoridad central encargada de recibir solicitudes de asistencia ju- dicial recíproca y facultada para darles cumplimiento o para transmitirlas a las autoridades competentes para su ejecución. Cuando alguna región o algún territorio especial de un Estado Parte disponga de un régimen distinto de asistencia judicial recíproca, el Estado Parte podrá designar a otra autoridad central que desempeñará la misma función para dicha región o dicho territorio. Las autoridades centrales velarán por el rápido y adecuado cumplimiento o transmisión de las solicitudes recibidas. Cuando la autoridad central transmita la solicitud a una autoridad competente para su ejecución, alentará la rápida y adecuada ejecución de la solicitud por parte de dicha autoridad.</span></span> <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-accion\">notificará</mark> <mark class=\"m-autoridad\">al Secretario General de las Naciones Unidas</mark> <mark class=\"m-personalizado\">el nombre</mark> de la <mark class=\"m-autoridad\">autoridad</mark> central <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que haya sido designada a tal fin. Las solicitudes de asistencia judicial recíproca y cualquier otra comunicación pertinente serán transmitidas a las autoridades centrales designadas por los Estados Parte. La presente disposición no afectará al derecho de cualquiera de los Estados Parte a exigir que estas solicitudes y comunicaciones le sean enviadas por vía diplomática y, en circunstancias urgentes, cuando los Estados Parte convengan en ello, por conducto de la Organización Internacional de Policía Criminal, de ser posible</span></span>.</p><p data-ex=\"EXOF,EX,*\"><b>15.</b> <mark class=\"m-personalizado\">Toda</mark> <mark class=\"m-destacable\">solicitud</mark> <mark class=\"m-personalizado\">de asistencia judicial recíproca</mark> <mark class=\"m-accion\">contendrá</mark> lo siguiente: a) la <mark class=\"m-personalizado\"><u class=\"m-clave\">identidad</u> de la</mark> <mark class=\"m-autoridad\">autoridad</mark> que hace la solicitud; b) <mark class=\"m-personalizado\">el objeto y <u class=\"m-clave\">la índole</u> de las investigaciones</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, los procesos o las actuaciones judiciales a que se refiere la solicitud y el nombre y las funciones de la autoridad encargada de efectuar dichas investigaciones, procesos o actuaciones</span></span>; c) <mark class=\"m-personalizado\">un resumen de los hechos</mark> pertinentes <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, salvo cuando se trate de solicitudes de presentación de documentos judiciales</span></span>; d) <mark class=\"m-resp\" data-q=\"2-14,2-84,2-114,2-115,2-ia-2048,2-ia-2110,2-ia-2113,2-ia-2118,2-ia-2123,2-ia-2125,2-ia-2128\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">una descripción de la asistencia solicitada y pormenores sobre cualquier procedimiento particular que el Estado Parte requirente desee que se aplique</mark>; e) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2126\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">de ser posible, la identidad, ubicación y nacionalidad de toda persona interesada</mark>; y f) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2109,2-ia-2140\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la finalidad para la que se solicita la prueba, información o actuación</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2045,2-ia-2115,2-ia-2116,2-ia-2121,2-ia-2129,2-ia-2142\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 6 preguntas</mark></p><p data-ex=\"EXOF,EX,*\" data-r=\"R26\"><span class=\"ex-sello ex-sello-r\">R26</span> <b>22.</b> Los <mark class=\"m-autoridad\">Estados Parte</mark> no <mark class=\"m-accion\">podrán</mark> denegar <mark class=\"m-personalizado\">una</mark> solicitud de <mark class=\"m-destacable\">asistencia</mark> judicial recíproca únicamente porque <mark class=\"m-personalizado\">se considere</mark> que el delito también entraña asuntos <mark class=\"m-autoridad\">fiscales.</mark> 23. Toda denegación <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de asistencia judicial recíproca</span></span> <mark class=\"m-accion\">deberá</mark> fundamentarse debidamente. <mark class=\"m-resp ex-q\" data-q=\"2-141,2-ia-2130\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p data-ex=\"EXOF,EX,*\"><b>25.</b> <mark class=\"m-personalizado\">La asistencia</mark> judicial recíproca <mark class=\"m-resp\" data-q=\"2-181,2-ia-2127,2-ia-2132\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">podrá ser diferida por el Estado Parte requerido si perturbase investigaciones, procesos o actuaciones judiciales en curso</mark>.</p><p data-ex=\"EXOF,EX,*\"><b>27.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Sin perjuicio de la aplicación del párrafo 12 del presente artículo,</span></span> el <mark class=\"m-destacable\">testigo</mark>, <mark class=\"m-destacable\">perito</mark> <mark class=\"m-personalizado\">u otra persona</mark> que <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, a instancias del Estado Parte requirente,</span></span> consienta en prestar testimonio <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en un juicio o en colaborar en una investigación, proceso o actuación judicial</span></span> <mark class=\"m-personalizado\">en el territorio del</mark> <mark class=\"m-autoridad\">Estado Parte requirente</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2119\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no podrá ser enjuiciado, detenido, condenado ni sometido a ninguna otra restricción de su libertad personal en ese territorio por actos, omisiones o declaraciones de culpabilidad anteriores a la fecha en que abandonó el territorio del Estado Parte requerido</mark> (salvoconducto). Ese <mark class=\"m-destacable\">salvoconducto</mark> <mark class=\"m-resp\" data-q=\"2-182\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cesará cuando el testigo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, perito u otra persona</span></span> haya tenido, durante quince días consecutivos</mark> o durante el período acordado <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por los Estados Parte</span></span> <mark class=\"m-personalizado\">después</mark> de la fecha en que se le haya <u class=\"m-clave\">informado</u> <mark class=\"m-personalizado\">oficialmente</mark> de que las <mark class=\"m-autoridad\">autoridades</mark> judiciales <mark class=\"m-personalizado\">ya</mark> no <mark class=\"m-personalizado\">requerían su presencia</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u> oportunidad de salir del país</mark> y no obstante permanezca voluntariamente en ese territorio <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">regrese</u> libremente a él</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">después de haberlo abandonado</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2108,2-ia-2133\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p data-ex=\"EXOF,EX,*\"><b>28.</b> <mark class=\"m-destacable\">Los gastos ordinarios</mark> que ocasione el cumplimiento de una solicitud <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">sufragados por</mark> <mark class=\"m-resp\" data-q=\"2-113,2-ia-2117,2-ia-2134\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el Estado Parte requerido, a menos que los Estados Parte interesados hayan acordado otra cosa</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Cuando se requieran a este fin gastos cuantiosos o de carácter extraordinario, los Estados Parte se consultarán para determinar las condiciones en que se dará cumplimiento a la solicitud, así como la manera en que se sufragarán los gastos.</span></span></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 19 y 20 — Investigaciones conjuntas y técnicas especiales de investigación <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EX,*\"><b><mark class=\"m-personalizado\">Art. 19.</mark></b> Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-accion\">considerarán</mark> la posibilidad de <mark class=\"m-personalizado\">celebrar acuerdos o</mark> arreglos <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">bilaterales o multilaterales</span></span> en virtud de los cuales <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en relación con cuestiones que son objeto de investigaciones, procesos o actuaciones judiciales en uno o más Estados,</span></span> las <mark class=\"m-autoridad\">autoridades competentes</mark> <mark class=\"m-personalizado\">puedan establecer</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-destacable\">mixtos de investigación</mark>. <mark class=\"m-personalizado\">A falta de acuerdos</mark> o arreglos de esa índole, las investigaciones conjuntas <mark class=\"m-resp\" data-q=\"2-183,2-ia-2136\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">podrán llevarse a cabo mediante acuerdos concertados caso por caso</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Los Estados Parte participantes velarán por que la soberanía del Estado Parte en cuyo territorio haya de efectuarse la investigación sea plenamente respetada.</span></span></p><p data-ex=\"*\"><b>Art. 20.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 20. TÉCNICAS ESPECIALES DE INVESTIGACIÓN. 1. S\u0007 iempre que lo permitan los principios fundamentales de su ordenamiento jurídico interno, cada Esta- do Parte adoptará, dentro de sus posibilidades y en las condiciones prescritas por su derecho interno,</span></span> <mark class=\"m-personalizado\">las medidas</mark> que sean necesarias <mark class=\"m-personalizado\">para permitir</mark> el adecuado recurso a la <mark class=\"m-resp r-vec\" data-q=\"2-184,2-ia-2137\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">entrega vigilada</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">y,</u></mark> cuando lo <mark class=\"m-personalizado\">considere apropiado</mark>, la utilización de <mark class=\"m-personalizado\">otras técnicas especiales</mark> de investigación, como la <mark class=\"m-resp\" data-q=\"2-184,2-ia-2137\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">vigilancia electrónica</mark> <mark class=\"m-personalizado\">o de otra índole y las</mark> <mark class=\"m-resp\" data-q=\"2-184\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">operaciones encubiertas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, por sus autoridades competentes en su territorio con objeto de combatir eficazmente la delincuencia organizada</span></span>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 24, 25 y 26 — Protección de testigos, víctimas y cooperación de los implicados <span class=\"ex-sello ex-sello-r\">R27</span></div><div class=\"ex-fb\"><p><b>Art. 24.</b> 1. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">medidas</mark> apropiadas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) <mark class=\"m-personalizado\">para proteger</mark> de manera eficaz contra eventuales</span></span> actos de <mark class=\"m-personalizado\">represalia o intimidación a los testigos</mark> (…), <mark class=\"m-personalizado\">así como,</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2144\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando proceda, a sus familiares y demás personas cercanas</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) 4. Las disposiciones del presente artículo <mark class=\"m-personalizado\">también</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">aplicables a las víctimas</mark> en el caso de <mark class=\"m-personalizado\">que actúen como testigos</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2146\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-r=\"R27\"><span class=\"ex-sello ex-sello-r\">R27</span> <b>Art. 25.</b> <mark class=\"m-destacable\">2.</mark> <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">establecerá</mark> procedimientos adecuados que permitan <mark class=\"m-accion\">a</mark> las víctimas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de los delitos comprendidos en la presente Convención</span></span> obtener <mark class=\"m-resp\" data-q=\"2-142,2-ia-2147\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">indemnización y restitución</mark>.</p><p><b>Art. 26.</b> 2. <mark class=\"m-accion\">Cada Estado Parte considerará la posibilidad</mark> de <mark class=\"m-personalizado\">prever</mark> (…) <mark class=\"m-destacable\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2150,2-ia-2151\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">mitigación de la pena de las personas acusadas que presten una cooperación sustancial</mark> en <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">la investigación o el enjuiciamiento (…).</span></span>  <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">3. (…) la concesión de <mark class=\"m-destacable\">inmunidad judicial</mark> a las personas que presten <mark class=\"m-personalizado\">una cooperación <u class=\"m-clave\">sustancial</u></mark> (…).</span></span></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 29 y 32 — Capacitación y asistencia técnica y Conferencia de las Partes <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><mark class=\"m-destacable\">Art. 29. 1.</mark> <mark class=\"m-autoridad\">Cada Estado Parte,</mark> <mark class=\"m-personalizado\">en la medida necesaria,</mark> <mark class=\"m-accion\">formulará, desarrollará</mark> <mark class=\"m-personalizado\">o</mark> <mark class=\"m-accion\">perfeccionará</mark> programas <mark class=\"m-personalizado\">de capacitación</mark> específicamente <mark class=\"m-personalizado\">concebidos</mark> para el personal <mark class=\"m-personalizado\">de sus</mark> servicios encargados <mark class=\"m-personalizado\">de hacer</mark> cumplir la ley, <mark class=\"m-personalizado\">incluidos</mark> <mark class=\"m-autoridad\">fiscales, jueces</mark> <mark class=\"m-destacable\">de instrucción y personal de aduanas,</mark> <mark class=\"m-autoridad\">así</mark> como <mark class=\"m-personalizado\">para el</mark> personal de otra índole encargado <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u> la</mark> prevención, la detección y <mark class=\"m-personalizado\">el control de los delitos comprendidos en la presente Convención.</mark> Esos programas <mark class=\"m-accion\">podrán</mark> <mark class=\"m-destacable\">incluir adscripciones e intercambios</mark> <mark class=\"m-personalizado\">de personal.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2158,2-ia-2210\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p data-ex=\"EX\"><mark class=\"m-personalizado\">Art. 32. 2. El</mark> <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">General de las Naciones Unidas</mark> <mark class=\"m-accion\">convocará</mark> <mark class=\"m-personalizado\">la Conferencia de</mark> las Partes a más tardar un <mark class=\"m-personalizado\">año después de la entrada</mark> en vigor de la presente <mark class=\"m-personalizado\">Convención.</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 31, 35 y 37 — Prevención, solución de controversias y relación con los Protocolos · R28 R29 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EX,*\"><b><mark class=\"m-personalizado\">Art. 31.</mark></b> 6. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Secretario</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">General</mark></span> <mark class=\"m-autoridad\">de las Naciones Unidas</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1557,2-ia-2208\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el nombre y la dirección de la autoridad o las autoridades que pueden ayudar a otros Estados Parte a formular medidas para prevenir la delincuencia organizada transnacional</mark>.</p><p data-ex=\"EX\"><b>Art. 35.</b> 1. <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">procurarán</mark> solucionar toda controversia <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">relacionada con la interpretación o aplicación del presente Protocolo</span></span> mediante la negociación. 2. Toda controversia <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">entre dos o más Estados Parte acerca de la interpretación o la aplicación del presente Protocolo</span></span> que <mark class=\"m-destacable\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-personalizado\">pueda</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">resolverse</u></mark> mediante la <mark class=\"m-personalizado\">negociación dentro de un plazo razonable</mark> <mark class=\"m-accion\">deberá,</mark> <mark class=\"m-personalizado\">a solicitud de</mark> <mark class=\"m-autoridad\">uno</mark> de esos <mark class=\"m-autoridad\">Estados</mark> Parte, someterse a <mark class=\"m-destacable\">arbitraje</mark>. <mark class=\"m-personalizado\">Si,</mark> seis meses después de la fecha de la solicitud de arbitraje, esos <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-personalizado\">no</mark> han podido ponerse de <mark class=\"m-personalizado\">acuerdo sobre la organización del arbitraje</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2023,2-ia-2035,2-ia-2214,2-ia-2215,2-ia-2420\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualquiera de esos Estados Parte podrá remitir la controversia a la Corte Internacional de Justicia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mediante solicitud conforme al Estatuto de la Corte</span></span>. 3. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">podrá</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en el momento de la firma, ratificación, aceptación o aprobación del presente Protocolo o adhesión a él,</span></span> <mark class=\"m-personalizado\">declarar que no</mark> se considera <mark class=\"m-personalizado\">vinculado por el párrafo 2</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente artículo. Los demás Estados Parte no quedarán vinculados por el párrafo 2 del presente artículo respecto de todo Estado Parte que haya hecho esa reserva</span></span>. 4. <mark class=\"m-autoridad\">El Estado Parte</mark> que haya hecho una <mark class=\"m-destacable\">reserva</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de conformidad con el párrafo 3 del presente artículo</span></span> <mark class=\"m-accion\">podrá</mark> en <mark class=\"m-personalizado\">cualquier momento retirar esa reserva notificándolo</mark> <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp\" data-q=\"2-3\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretario General de las Naciones Unidas</mark>.</p><p><b>Art. 37.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">1. La presente Convención</mark> <mark class=\"m-accion\">podrá</mark> complementarse con uno o más protocolos.</span></span> 2. <mark class=\"m-resp r-ia\" data-q=\"2-ia-2219\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Para pasar a ser parte en un protocolo, los Estados o las organizaciones regionales de integración económica también deberán ser parte en la presente Convención</mark>. (…)</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 31 y 33 — Prevención (evaluación de instrumentos) y Secretaría <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R28</span> <span class=\"ex-sello ex-sello-r\">R29</span></div><div class=\"ex-fb\"><p data-ex=\"*\" data-r=\"R28\"><span class=\"ex-sello ex-sello-r\">R28</span> Art. 31. 4. Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-accion\">procurarán</mark> evaluar periódicamente los instrumentos <mark class=\"m-personalizado\">jurídicos y</mark> las <mark class=\"m-plazo\">prácticas administrativas</mark> pertinentes vigentes a fin de detectar <mark class=\"m-resp r-ia\" data-q=\"2-ia-2207\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">si existe el peligro de que sean <mark class=\"m-destacable\">utilizados</mark> indebidamente por grupos <mark class=\"m-plazo\">delictivos</mark> organizados</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2149\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-r=\"R29\"><span class=\"ex-sello ex-sello-r\">R29</span> Art. 33. <b>1.</b> El <mark class=\"m-destacable\">Secretario General de las Naciones Unidas</mark> prestará los servicios de secretaría necesarios a la <mark class=\"m-resp\" data-q=\"2-144\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Conferencia de las Partes en la Convención</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>⭐ EX · Arts. 36 a 41 — Firma, vigor, enmienda, denuncia y depositario</div><div class=\"ex-tab\" style=\"--n:2\"><div class=\"ex-th\"></div><div class=\"ex-th\">DATO</div><div class=\"ex-tl\"><b>Firma (36)</b></div><div class=\"ex-td\">Abierta a todos <mark class=\"m-autoridad\">los Estados</mark> del <mark class=\"m-personalizado\">12 al 15 de diciembre de 2000 en Palermo</mark> (Italia) y <mark class=\"m-personalizado\">después</mark> en la <mark class=\"m-autoridad\">Sede de las Naciones Unidas en Nueva York</mark> <mark class=\"m-plazo\">hasta el</mark> 12 de <mark class=\"m-personalizado\">diciembre de</mark> 2002</div><div class=\"ex-tl\"><b>Vigor (38)</b></div><div class=\"ex-td\">Entra <mark class=\"m-personalizado\">en vigor el nonagésimo día</mark> <mark class=\"m-personalizado\">después</mark> de <mark class=\"m-personalizado\">la fecha</mark> en que se haya depositado <mark class=\"m-personalizado\">el cuadragésimo instrumento</mark> (cuarenta <mark class=\"m-personalizado\">instrumentos</mark>) de ratificación, <u class=\"m-clave\">aceptación</u>, aprobación o adhesión · para <mark class=\"m-autoridad\">cada Estado</mark> que <mark class=\"m-personalizado\">ratifique</mark> <mark class=\"m-personalizado\">después</mark>: el trigésimo <mark class=\"m-destacable\">día</mark> <mark class=\"m-personalizado\">después</mark> de <mark class=\"m-autoridad\">la fecha de</mark> depósito de su instrumento</div><div class=\"ex-tl\"><b>Enmiendas (39)</b></div><div class=\"ex-td\"><mark class=\"m-personalizado\">Cuando</mark> <mark class=\"m-personalizado\">hayan</mark> transcurrido cinco <mark class=\"m-plazo\">años</mark> <mark class=\"m-personalizado\">desde</mark> la entrada <mark class=\"m-personalizado\">en vigor</mark>, <mark class=\"m-personalizado\">por escrito al</mark> <mark class=\"m-autoridad\">Secretario General</mark> · primero <u class=\"m-clave\">consenso</u>; <mark class=\"m-personalizado\">si</mark> se agotan las posibilidades, <mark class=\"m-destacable\">mayoría de dos tercios</mark> de <mark class=\"m-autoridad\">los Estados Parte</mark> <mark class=\"m-destacable\">presentes y votantes</mark> · entra <mark class=\"m-personalizado\">en vigor respecto de</mark> <mark class=\"m-autoridad\">un Estado</mark> a los noventa días <mark class=\"m-personalizado\">después</mark> de que este deposite su instrumento de ratificación, <u class=\"m-clave\">aceptación</u> o aprobación de la <mark class=\"m-destacable\">enmienda</mark></div><div class=\"ex-tl\"><b>Denuncia (40)</b></div><div class=\"ex-td\">Surte <mark class=\"m-plazo\">efecto</mark> un <mark class=\"m-personalizado\">año después</mark> de <mark class=\"m-personalizado\">la fecha</mark> en que <mark class=\"m-autoridad\">el Secretario General</mark> haya <mark class=\"m-personalizado\">recibido</mark> la notificación · la <mark class=\"m-destacable\">denuncia</mark> de <mark class=\"m-personalizado\">la Convención</mark> entrañará la <mark class=\"m-destacable\">denuncia</mark> de sus protocolos</div><div class=\"ex-tl\"><b>Depositario e idiomas (41)</b></div><div class=\"ex-td\"><mark class=\"m-autoridad\">El Secretario General</mark> <mark class=\"m-autoridad\">de las Naciones Unidas</mark> · textos <mark class=\"m-personalizado\">en árabe, chino, español, francés, inglés y ruso</mark>, <mark class=\"m-personalizado\">igualmente auténticos</mark></div></div></div><div class=\"ex-linea\">Artículos 36, 38, 39, 40 y 41 — Firma, entrada <mark class=\"m-personalizado\">en vigor</mark>, <mark class=\"m-destacable\">enmienda</mark>, <mark class=\"m-destacable\">denuncia</mark> y <mark class=\"m-destacable\">depositario</mark> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R30</span>: <mark class=\"m-resp ex-q\" data-q=\"2-145,2-186,2-ia-1646,2-ia-2221,2-ia-2222,2-ia-2223,2-ia-2224,2-ia-2225,2-ia-2226,2-ia-2227,2-ia-2424,2-ia-2539\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 12 preguntas más de este artículo</mark></div><div class=\"bloque-titulo\">2.5 — <mark class=\"m-personalizado\">PROTOCOLO</mark> PARA <mark class=\"m-destacable\">PREVENIR</mark>, <mark class=\"m-destacable\">REPRIMIR</mark> Y SANCIONAR <mark class=\"m-personalizado\">LA TRATA DE <u class=\"m-clave\">PERSONAS</u></mark>, ESPECIALMENTE MUJERES Y NIÑOS, QUE <mark class=\"m-destacable\">COMPLEMENTA</mark> <mark class=\"m-personalizado\">LA CONVENCIÓN</mark> DE PALERMO (Nueva York, 15-11-2000 · <mark class=\"m-personalizado\">en vigor</mark> <mark class=\"m-plazo\">para España el</mark> 25-12-2003)</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 1 y 2 — Relación con la Convención y finalidad <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>Art. 1.</b> 1. El presente <mark class=\"m-personalizado\">Protocolo</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2426\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">complementa la Convención de las Naciones Unidas contra la Delincuencia Organizada Transnacional</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1022,2-ia-2159\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se interpretará juntamente con la Convención</mark>. 2. <mark class=\"m-personalizado\">Las disposiciones de la Convención se</mark> <mark class=\"m-accion\">aplicarán</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2229\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">mutatis mutandis</mark> al presente Protocolo, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2229\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a menos que en él se disponga otra cosa</mark>. 3. <mark class=\"m-personalizado\">Los</mark> delitos <mark class=\"m-personalizado\">tipificados</mark> con arreglo al <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 5</span> del presente Protocolo</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2230,2-ia-2429\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se considerarán delitos tipificados con arreglo a la Convención</mark>.</p><p data-ex=\"*\"><b>Art. 2.</b> Los <mark class=\"m-destacable\">fines</mark> del presente Protocolo son: a) <mark class=\"m-destacable\">prevenir y combatir</mark> <mark class=\"m-personalizado\">la trata de personas</mark>, <mark class=\"m-resp\" data-q=\"2-187\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">prestando especial atención a las mujeres y los niños</mark>; b) <mark class=\"m-resp\" data-q=\"2-187,2-ia-2228,2-ia-2306,2-ia-2315\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">proteger y ayudar a las víctimas de dicha trata, respetando plenamente sus derechos humanos</mark>; <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> c) <mark class=\"m-destacable\">promover la cooperación</mark> <mark class=\"m-personalizado\">entre los</mark> <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">Parte para lograr esos fines.</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 3 y 4 — Definiciones y ámbito de aplicación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 3.</b> a) Por <mark class=\"m-destacable\">«trata de personas»</mark> <mark class=\"m-accion\">se entenderá</mark> la <mark class=\"m-resp r-ia\" data-q=\"2-ia-2232\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">captación, el transporte, el traslado, la acogida o la recepción de personas</mark>, recurriendo a la <mark class=\"m-personalizado\">amenaza o</mark> al uso de <mark class=\"m-personalizado\">la fuerza u otras formas de coacción</mark>, <mark class=\"m-personalizado\">al rapto, al fraude, al engaño, al abuso de poder o de una situación de vulnerabilidad o a la concesión o recepción de pagos o beneficios</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">para obtener el consentimiento de una persona que tenga autoridad sobre otra</span></span>, <mark class=\"m-personalizado\">con fines de explotación</mark>. <mark class=\"m-personalizado\">Esa explotación</mark> <mark class=\"m-accion\">incluirá</mark>, <mark class=\"m-personalizado\">como mínimo</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2232,2-ia-2233\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la explotación de la prostitución ajena u otras formas de explotación sexual, los trabajos o servicios forzados, la esclavitud o las prácticas análogas a la esclavitud, la servidumbre o la extracción de órganos</mark>; b) <mark class=\"m-destacable\">el consentimiento</mark> <mark class=\"m-personalizado\">dado por la víctima</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la trata de personas a toda forma de explotación que se tenga la intención de realizar descrita en el apartado a) del presente artículo</span></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1637,2-ia-2234\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no se tendrá en cuenta cuando se haya recurrido a cualquiera de los medios enunciados</mark> en dicho apartado; c) <mark class=\"m-personalizado\">la captación</mark>, <mark class=\"m-personalizado\">el transporte</mark>, <mark class=\"m-personalizado\">el traslado</mark>, <mark class=\"m-personalizado\">la acogida o la recepción de un</mark> <mark class=\"m-destacable\">niño</mark> <mark class=\"m-personalizado\">con fines de explotación se</mark> <mark class=\"m-accion\">considerará</mark> <mark class=\"m-destacable\">«trata de</mark> <mark class=\"m-personalizado\">personas»</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2155\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">incluso cuando no se recurra a ninguno de los medios enunciados</mark> en el apartado a); d) por «niño» se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2235\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">toda persona menor de 18 años</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1866\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-plazo\">Art.</mark> 4.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">A menos que contenga una disposición en contrario,</span></span> el presente Protocolo se <mark class=\"m-accion\">aplicará</mark> <mark class=\"m-personalizado\">a la prevención</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">investigación y penalización</u> de los delitos</mark> tipificados con arreglo al <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 5</span></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Protocolo</span></span>, <mark class=\"m-resp\" data-q=\"2-178,2-ia-2009,2-ia-2212,2-ia-2236\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cuando esos delitos sean de carácter transnacional y entrañen la participación de un grupo delictivo organizado</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">así</u> como a la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">protección</mark></span> <mark class=\"m-personalizado\">de</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">las víctimas</mark></span> de esos delitos.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 5</mark> — Penalización: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2237,2-ia-1207\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 6 y 7 — Asistencia y protección a las víctimas y régimen en el Estado receptor · R31 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R31</span></div><div class=\"ex-fb\"><p data-r=\"R31\"><span class=\"ex-sello ex-sello-r\">R31</span> <b>Art. 6.</b> <mark class=\"m-destacable\">1.</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 6. ASISTENCIA Y PROTECCIÓN A LAS VÍCTIMAS DE LA TRATA DE PERSONAS. R31 1. Cuando proceda y en la medida que lo permita su derecho interno,</span></span> <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-accion\">protegerá</mark> la <mark class=\"m-personalizado\"><u class=\"m-clave\">privacidad y</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">la</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">identidad</u> de las víctimas</mark> de la trata de personas, <mark class=\"m-personalizado\"><u class=\"m-clave\">en</u></mark> particular <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, entre otras cosas,</span></span> <mark class=\"m-personalizado\">previendo</mark> <mark class=\"m-resp\" data-q=\"2-146,2-ia-2238\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">la confidencialidad de las actuaciones judiciales relativas a dicha trata</mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Cada Estado Parte velará por que su ordenamiento jurídico o administrativo interno prevea medidas con miras a proporcionar a las víctimas de la trata de personas, cuando proceda: a) I\u0007nformación sobre procedimientos judiciales y administrativos pertinentes;</span></span> b) <mark class=\"m-destacable\"><u class=\"m-clave\">asistencia</u></mark> encaminada <mark class=\"m-personalizado\">a permitir que sus opiniones y preocupaciones se presenten y examinen en las etapas apropiadas</mark> de las actuaciones penales contra los delincuentes <mark class=\"m-resp r-ia\" data-q=\"2-ia-2148,2-ia-2239\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sin que ello menoscabe los derechos de la defensa</mark>.</p><p data-ex=\"EXOF,*\"><b>3.</b> <mark class=\"m-accion\">Cada Estado Parte considerará la posibilidad de aplicar</mark> <mark class=\"m-personalizado\">medidas</mark> destinadas <mark class=\"m-autoridad\"><u class=\"m-clave\">a prever la recuperación</u></mark> <mark class=\"m-destacable\">física, psicológica y social de las víctimas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la trata de personas, incluso, cuando proceda, en coope- ración con organizaciones no gubernamentales, otras organizaciones pertinentes y demás sectores de la sociedad civil</span></span>, <mark class=\"m-destacable\">y</mark> <mark class=\"m-personalizado\">en particular mediante</mark> el <mark class=\"m-destacable\">suministro</mark> de: a) <mark class=\"m-resp\" data-q=\"2-31\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">alojamiento adecuado</mark>; b) <mark class=\"m-personalizado\">asesoramiento e información</mark>, <mark class=\"m-personalizado\">en particular con</mark> respecto a sus <mark class=\"m-personalizado\">derechos jurídicos</mark>, en un <mark class=\"m-personalizado\"><u class=\"m-clave\">idioma</u></mark> que las víctimas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la trata de personas</span></span> <mark class=\"m-personalizado\">puedan comprender</mark>; c) <mark class=\"m-resp\" data-q=\"2-31\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">asistencia médica, sicológica y material</mark>; <mark class=\"m-personalizado\">y</mark> d) <mark class=\"m-resp\" data-q=\"2-31,2-ia-2240\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">oportunidades de empleo, educación y capacitación</mark>.</p><p><b><span class=\"m-caja\">4.</span></b> <span class=\"m-caja\">Cada</span> <span class=\"m-caja\"><mark class=\"m-autoridad\">Estado</mark></span> <span class=\"m-caja\">Parte</span> <span class=\"m-caja\"><mark class=\"m-accion\">tendrá</mark></span> <span class=\"m-caja\">en cuenta,</span> <mark class=\"m-personalizado\">al aplicar</mark> las disposiciones del presente artículo, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2241\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la edad, el sexo y las necesidades especiales de las víctimas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">de la trata de personas</mark>, en <mark class=\"m-personalizado\">particular las necesidades especiales de los niños</mark> (…).</span></span>  5. (…) <mark class=\"m-personalizado\">prever la <u class=\"m-clave\">seguridad física</u> de las víctimas</mark> (…). 6. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">velará</mark> <mark class=\"m-personalizado\">por que su ordenamiento</mark> jurídico interno <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">prevea medidas</mark> que brinden a las víctimas de la</span></span> trata de personas <mark class=\"m-personalizado\">la posibilidad</mark> de <mark class=\"m-resp r-ia\" data-q=\"2-ia-2242\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">obtener indemnización por los daños sufridos</mark>.</p><p><b>Art. 7.</b> <mark class=\"m-destacable\">1.</mark> (…) <mark class=\"m-destacable\">cada</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-destacable\">Parte</mark> <mark class=\"m-accion\">considerará</mark> <mark class=\"m-destacable\">la posibilidad de adoptar medidas legislativas u otras medidas apropiadas que</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1444,2-ia-2243\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">permitan a las víctimas de la trata de personas permanecer en su territorio, temporal o permanentemente</mark>, cuando proceda. 2. (…) <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-accion\">dará</mark> <mark class=\"m-personalizado\">la debida consideración a</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1111\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">factores humanitarios y personales</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>⭐ EX · Arts. 6 a 8 — Víctimas: protección, permanencia y repatriación</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>PROTECCIÓN Y ASISTENCIA (6)</h5><ul><li>Privacidad e <u class=\"m-clave\">identidad</u>: confidencialidad de las <mark class=\"m-personalizado\">actuaciones</mark> <mark class=\"m-personalizado\">judiciales</mark></li><li>Sus opiniones se examinan en el proceso penal <u class=\"m-clave\">sin</u> menoscabo de los <mark class=\"m-personalizado\">derechos</mark> de la defensa</li><li>Recuperación física, psicológica y social (<mark class=\"m-accion\">considerará</mark>): <mark class=\"m-resp\" data-q=\"2-31\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">a) alojamiento adecuado · b) asesoramiento e información en un idioma que entiendan · c) asistencia médica, psicológica y material · d) empleo, educación y capacitación</mark></li><li>Tener <mark class=\"m-personalizado\">en cuenta</mark> la edad, el sexo y las necesidades especiales (sobre todo de los niños) · su <mark class=\"m-personalizado\">seguridad</mark> física</li><li>Posibilidad de obtener <u class=\"m-clave\">indemnización</u> por los daños sufridos (<mark class=\"m-accion\">velará</mark>)</li></ul></div><div class=\"vis-col\"><h5>ESTADO RECEPTOR (7)</h5><ul><li><mark class=\"m-accion\">Considerará</mark> permitirles permanecer en su territorio, temporal o permanentemente</li><li>Con debida consideración a factores humanitarios y personales</li></ul></div><div class=\"vis-col\"><h5>REPATRIACIÓN (8)</h5><ul><li>El <mark class=\"m-autoridad\">Estado</mark> de <mark class=\"m-personalizado\">nacionalidad</mark> o <mark class=\"m-personalizado\">residencia</mark> <mark class=\"m-destacable\">permanente</mark> la facilita y acepta <u class=\"m-clave\">sin</u> <mark class=\"m-autoridad\">demora</mark> <mark class=\"m-autoridad\">indebida o</mark> <mark class=\"m-personalizado\">injustificada</mark>, <mark class=\"m-personalizado\">teniendo</mark> <mark class=\"m-personalizado\">en cuenta</mark> su <mark class=\"m-personalizado\">seguridad</mark></li><li>Preferentemente voluntaria</li><li>A <mark class=\"m-destacable\">solicitud</mark> del receptor, el <mark class=\"m-autoridad\">Estado</mark> requerido verifica <mark class=\"m-personalizado\">si</mark> es <u class=\"m-clave\">nacional</u> o residente</li><li><u class=\"m-clave\">Sin</u> documentación: el <mark class=\"m-autoridad\">Estado</mark> de <mark class=\"m-personalizado\">nacionalidad</mark> expide, <mark class=\"m-personalizado\">previa</mark> <mark class=\"m-destacable\">solicitud</mark> del receptor, los documentos de viaje</li></ul></div></div></div><div class=\"ex-linea\">Artículo 8 — <mark class=\"m-personalizado\">Repatriación</mark> de <mark class=\"m-personalizado\">las víctimas</mark> <span class=\"ex-sello\">✱</span>: <mark class=\"m-resp ex-q\" data-q=\"2-188,2-ia-1601,2-ia-2244,2-ia-2245,2-ia-2246,2-ia-2247\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 6 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 9 y 10 — Prevención, intercambio de información y capacitación <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><b>Art. 9.</b> 4. <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">adoptarán</mark> medidas <mark class=\"m-personalizado\">o</mark> <mark class=\"m-accion\">reforzarán</mark> las ya existentes, recurriendo <mark class=\"m-personalizado\">en particular a la cooperación bilateral o multilateral</mark>, <mark class=\"m-personalizado\">a fin de</mark> <mark class=\"m-resp\" data-q=\"2-189,2-ia-2303,2-ia-2304\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">mitigar factores como la pobreza, el subdesarrollo y la falta de oportunidades equitativas que hacen a las personas, especialmente las mujeres y los niños, vulnerables a la trata</mark>. 5. Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-accion\">adoptarán</mark> medidas <mark class=\"m-personalizado\">legislativas o de otra índole,</mark> tales <mark class=\"m-personalizado\">como</mark> <mark class=\"m-resp\" data-q=\"2-190\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">medidas educativas, sociales y culturales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, o reforzarán las ya existentes, recurriendo en particular a la cooperación bilateral y multilateral</span></span>, <mark class=\"m-personalizado\">a fin de</mark> <mark class=\"m-resp\" data-q=\"2-190\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">desalentar la demanda</mark> que <mark class=\"m-personalizado\">propicia</mark> cualquier forma <mark class=\"m-personalizado\">de explotación conducente a la trata</mark> de personas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, especialmente mujeres y niños</span></span>.</p><p data-ex=\"*\"><b>Art. 10.</b> 2. <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">impartirán</mark> <mark class=\"m-personalizado\">a los funcionarios</mark> encargados de hacer cumplir <mark class=\"m-personalizado\">la ley</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, así como a los de inmigración y a otros funcionarios pertinentes,</span></span> <mark class=\"m-destacable\">capacitación</mark> <mark class=\"m-personalizado\">en la prevención de la trata</mark> de personas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">o reforzarán dicha capacitación, según proceda</span></span>. Esta <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">centrarse</mark> en <mark class=\"m-resp\" data-q=\"2-191,2-ia-2305\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">los métodos aplicados para prevenir dicha trata, enjuiciar a los traficantes y proteger los derechos de las víctimas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, incluida la protección de las víctimas frente a los traficantes. La capacitación también deberá tener en cuenta la necesidad de considerar los derechos humanos y las cuestiones relativas al niño y a la mujer, así como fomentar la cooperación con organizaciones no gubernamentales, otras organizaciones pertinentes y demás sectores de la sociedad civil</span></span>. 3. <mark class=\"m-resp\" data-q=\"2-192,2-ia-1723,2-ia-2307\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">El Estado Parte receptor de dicha información dará cumplimiento a toda solicitud del Estado Parte que la haya facilitado en el sentido de imponer restricciones a su utilización</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 11, 12 y 13 — Medidas fronterizas y documentos <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R32</span></div><div class=\"ex-fb\"><p data-ex=\"*\" data-r=\"R32\"><span class=\"ex-sello ex-sello-r\">R32</span> <b>Art. 11.</b> 1. <mark class=\"m-personalizado\">Sin perjuicio de los compromisos internacionales</mark> relativos a la <mark class=\"m-personalizado\">libre circulación de personas</mark>, <mark class=\"m-autoridad\">los Estados Parte</mark> <mark class=\"m-accion\">reforzarán</mark>, en la medida de lo posible, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1019\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los controles fronterizos que sean necesarios</mark> para <mark class=\"m-destacable\"><u class=\"m-clave\">prevenir</u></mark> <mark class=\"m-personalizado\">y detectar la trata de</mark> personas. 2. Cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">medidas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">legislativas u otras medidas apropiadas</span></span> para <mark class=\"m-personalizado\">prevenir</mark>, en la medida de lo posible, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2407\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la utilización de medios de transporte explotados por transportistas comerciales</mark> <mark class=\"m-personalizado\">para la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">de los delitos tipificados</mark> con arreglo al <span class=\"ref-art\">artículo 5</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Protocolo</span></span>. 3. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">C\u0007 uando proceda y sin perjuicio de las convenciones internacionales aplicables se preverá, entre esas medidas,</span></span> <mark class=\"m-personalizado\">la <u class=\"m-clave\">obligación</u> de <u class=\"m-clave\">los transportistas</u> comerciales</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, incluidas las empresas de transporte, así como los propietarios o explotadores de cualquier medio de transporte,</span></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2309\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">de cerciorarse de que todos los pasajeros tengan en su poder los documentos de viaje requeridos para entrar en el Estado receptor</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">4. C\u0007 ada Estado Parte adoptará las medidas necesarias, de conformidad con su derecho interno, para prever sanciones en caso de incumplimiento de la obligación enunciada en el párrafo 3 del presente artículo.</span></span> 5. Cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">considerará</mark> la posibilidad de <mark class=\"m-accion\">adoptar</mark> <mark class=\"m-personalizado\">medidas que</mark> permitan <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con su derecho interno,</span></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2310\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">denegar la entrada o revocar visados</mark> a personas implicadas en la <mark class=\"m-autoridad\">comisión</mark> de delitos tipificados con arreglo al presente Protocolo. <mark class=\"m-resp ex-q\" data-q=\"2-147,2-ia-2308\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 12.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Cada Estado Parte adoptará, con los medios de que disponga, las medidas que se requieran para:</span></span> a) <mark class=\"m-personalizado\">garantizar</mark> la necesaria <mark class=\"m-destacable\"><u class=\"m-clave\">calidad</u></mark> de los <mark class=\"m-destacable\">documentos de viaje o de identidad</mark> que <mark class=\"m-personalizado\">expida</mark> <mark class=\"m-resp\" data-q=\"2-193\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">a fin de que éstos no puedan con facilidad utilizarse indebidamente ni falsificarse</mark> <mark class=\"m-personalizado\">o alterarse</mark>, reproducirse o expedirse de forma ilícita <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">; y b) \u0007Garantizar la integridad y la seguridad de los documentos de viaje o de identidad que expida o que se expidan en su nombre e impedir la creación, expedición y utilización ilícitas de dichos documentos</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2312\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 13.</b> <mark class=\"m-personalizado\">Cuando</mark> lo solicite otro <mark class=\"m-autoridad\">Estado</mark> Parte, cada <mark class=\"m-autoridad\">Estado</mark> <span class=\"m-caja\">Parte</span> <mark class=\"m-accion\">verificará</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1227\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">de conformidad con su derecho interno</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2313\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">dentro de un plazo razonable</mark>, <mark class=\"m-destacable\">la legitimidad y validez</mark> <mark class=\"m-personalizado\">de los documentos de viaje o de identidad</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">expedidos o presuntamente expedidos en su nombre y</span></span> <mark class=\"m-personalizado\">sospechosos de</mark> ser utilizados para la trata <mark class=\"m-personalizado\">de personas</mark>.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 14 y 15 — Cláusula de salvaguardia y solución de controversias · R32 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R33</span></div><div class=\"ex-fb\"><p data-ex=\"*\" data-r=\"R33\"><span class=\"ex-sello ex-sello-r\">R33</span> <b>Art. 14.</b> 1. Nada de lo <mark class=\"m-personalizado\">dispuesto en el presente</mark> <mark class=\"m-destacable\">Protocolo</mark> <mark class=\"m-accion\">afectará</mark> a los <mark class=\"m-personalizado\">derechos</mark>, <mark class=\"m-personalizado\">obligaciones y responsabilidades de los</mark> <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">y las personas con arreglo al derecho internacional</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, incluidos el derecho internacional humanitario y la normativa internacional de derechos humanos</span></span> y, en <mark class=\"m-personalizado\">particular</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">cuando sean aplicables,</span></span> la <mark class=\"m-personalizado\">Convención</mark> sobre el <mark class=\"m-destacable\">Estatuto de los Refugiados</mark> de 1951 y su <mark class=\"m-destacable\">Protocolo</mark> de 1967, así como <mark class=\"m-resp r-ia\" data-q=\"2-ia-2314\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el principio de non-refoulement</mark> <mark class=\"m-personalizado\">consagrado</mark> en dichos <mark class=\"m-personalizado\">instrumentos</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-148\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 15.</b> 1. Los <mark class=\"m-autoridad\">Estados Parte</mark> <mark class=\"m-accion\">procurarán</mark> <mark class=\"m-personalizado\">solucionar</mark> toda <mark class=\"m-personalizado\">controversia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">relacionada con la interpretación o aplicación del presente Protocolo</span></span> <mark class=\"m-personalizado\">mediante</mark> la <mark class=\"m-resp\" data-q=\"2-66\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">negociación</mark>. 2. Toda <mark class=\"m-personalizado\">controversia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">entre dos o más Estados Parte acerca de la interpretación o la aplicación del presente Protocolo</span></span> que <u class=\"m-clave\">no</u> pueda <mark class=\"m-personalizado\">resolverse mediante la negociación</mark> dentro de un <mark class=\"m-destacable\">plazo</mark> <mark class=\"m-personalizado\">razonable</mark> <mark class=\"m-accion\">deberá</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, a solicitud de uno de esos Estados Parte,</span></span> <mark class=\"m-personalizado\">someterse</mark> a <mark class=\"m-destacable\">arbitraje</mark>. Si, <mark class=\"m-plazo\">seis meses</mark> <mark class=\"m-personalizado\">después</mark> de la fecha de la <mark class=\"m-destacable\">solicitud</mark> de <mark class=\"m-personalizado\">arbitraje</mark>, esos <mark class=\"m-autoridad\">Estados Parte</mark> <u class=\"m-clave\">no</u> han podido <mark class=\"m-personalizado\">ponerse</mark> de <mark class=\"m-destacable\">acuerdo</mark> sobre la <mark class=\"m-personalizado\">organización del arbitraje</mark>, <mark class=\"m-resp\" data-q=\"2-195\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cualquiera de esos Estados Parte podrá remitir la controversia a la Corte Internacional de Justicia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mediante solicitud conforme al Estatuto de la Corte</span></span>.</p><p data-ex=\"*\"><b>Reservas al art. 15.2:</b> <mark class=\"m-destacable\">Laos</mark>: para <mark class=\"m-personalizado\">someter una controversia a arbitraje</mark> o a la <mark class=\"m-autoridad\">Corte Internacional de Justicia</mark> <mark class=\"m-resp\" data-q=\"2-196,2-ia-1516\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">será necesario el consentimiento de todas las partes en la controversia</mark>. <mark class=\"m-resp r-vec\" data-q=\"2-196,2-ia-1516\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Túnez</mark>: las <mark class=\"m-personalizado\">controversias</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">relativas a la interpretación o a la aplicación del Protocolo</span></span> <mark class=\"m-accion\">podrán</mark> ser <mark class=\"m-personalizado\">sometidas</mark> a la <mark class=\"m-autoridad\">Corte Internacional de Justicia</mark> <mark class=\"m-resp r-vec\" data-q=\"2-196,2-ia-1516\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">únicamente después de que haya dado su consentimiento previo</mark>. (También <mark class=\"m-personalizado\">formularon reserva Ecuador y Lituania</mark>).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 16 a 20 — Firma, entrada en vigor, enmienda, denuncia y depositario · R33 R34 R35 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R34</span></div><div class=\"ex-fb\"><p><b>Art. 16.</b> 1. El presente Protocolo <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">abierto a la firma</mark> de todos los <mark class=\"m-autoridad\">Estados</mark> del <mark class=\"m-personalizado\">12 al 15 de diciembre de 2000 en Palermo</mark> (Italia) <mark class=\"m-personalizado\">y</mark> después de esa fecha en la <mark class=\"m-personalizado\">Sede de las Naciones Unidas en Nueva York</mark> <mark class=\"m-resp\" data-q=\"2-185,2-ia-1319,2-ia-1322,2-ia-2216,2-ia-2317,2-ia-2421,2-ia-2536\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">hasta el 12 de diciembre de 2002</mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">E\u0007 l presente Protocolo</span></span> <mark class=\"m-personalizado\">también</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">abierto a la firma</mark> de las <mark class=\"m-autoridad\">organizaciones regionales de integración económica</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2217\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">siempre que al menos uno de los Estados miembros de tales organizaciones haya firmado el presente Protocolo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de conformidad con lo dispuesto en el párrafo 1 del presente artículo</span></span>.</p><p data-ex=\"*\"><b>Art. 17.</b> 1. El presente Protocolo <mark class=\"m-accion\">entrará</mark> en vigor el nonagésimo día después de la fecha en que se haya depositado el <mark class=\"m-resp r-ia\" data-q=\"2-ia-2221\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuadragésimo instrumento</mark> de ratificación <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, aceptación, aprobación o adhesión</span></span>, <mark class=\"m-resp\" data-q=\"2-197,2-ia-2318\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">a condición de que no entre en vigor antes de la entrada en vigor de la Convención</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">A los efectos del presente párrafo, los instrumentos depositados por una organización regional de integración económica no se considerarán adicionales a los depositados por los Estados miembros de tal organización.</span></span></p><p data-r=\"R34\"><span class=\"ex-sello ex-sello-r\">R34</span> <b>Art. 18.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1134,2-ia-1313,2-ia-1941\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Cuando hayan transcurrido cinco años desde la entrada en vigor del presente Protocolo</mark>, <mark class=\"m-autoridad\">los Estados</mark> Parte en el Protocolo <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">proponer</mark> <mark class=\"m-destacable\">enmiendas</mark> <mark class=\"m-personalizado\">por escrito al</mark> <mark class=\"m-resp\" data-q=\"2-19,2-88,2-ia-2211\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretario General de las Naciones Unidas</mark>, <mark class=\"m-personalizado\">quien</mark> a continuación <mark class=\"m-accion\">comunicará</mark> toda enmienda propuesta <mark class=\"m-autoridad\">a los Estados Parte y a la Conferencia de las Partes</mark> <span class=\"hueco-txt\">en la Convención para que la examinen y decidan al respecto. Los Estados Parte en el presente Protocolo reunidos en la Conferencia de las Partes harán todo lo posible por lograr un consenso sobre cada enmienda. Si se han agotado todas las posibilidades de lograr un consenso y no se ha llegado a un acuerdo, la aprobación de la enmienda exigirá, en última instancia, una mayoría de dos tercios de los Estados Parte en el presente Protocolo presentes y votantes en la sesión de la Conferencia de las Partes</span>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Parte podrán proponer enmiendas por escrito al Secretario General de las Naciones Unidas, quien a continuación comunicará toda enmienda propuesta a los Estados Parte y a la Conferencia de las Partes en la Convención para que la examinen y decidan al respecto. Los Estados Parte en el presente Protocolo reunidos en la Conferencia de las Partes harán todo lo posible por lograr un consenso sobre cada enmienda. Si se han agotado todas las posibilidades de lograr un consenso y no se ha llegado a un acuerdo, la aprobación de la enmienda exigirá, en última instancia, una</span></span> <mark class=\"m-destacable\">mayoría de dos tercios</mark> de los <mark class=\"m-autoridad\">Estados</mark> Parte (…) <mark class=\"m-destacable\">presentes y votantes</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en la sesión de la Conferencia de las Partes</span></span>. 2. <mark class=\"m-autoridad\">Las organizaciones regionales de integración económica</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, en asuntos de su competencia,</span></span> <mark class=\"m-accion\">ejercerán</mark> <mark class=\"m-personalizado\">su derecho de voto</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con arreglo al presente artículo</span></span> <mark class=\"m-resp\" data-q=\"2-149,2-ia-2320,2-ia-2538\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">con un número de votos igual al número de sus Estados miembros que sean Partes en el presente Protocolo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Dichas organizaciones no ejercerán su derecho de voto si sus Estados miembros ejercen el suyo, y viceversa</span></span>. 4. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">\u0007Toda enmienda refrendada de conformidad con el párrafo 1 del presente artículo</span></span> <mark class=\"m-accion\">entrará</mark> en vigor respecto de un <mark class=\"m-autoridad\">Estado</mark> Parte noventa días después <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de la fecha en que éste deposite en poder del Secretario General de las Naciones Unidas un instrumento de ratificación, aceptación o aprobación de esa enmienda</span></span>.</p><p><b>Art. 19.</b> 1. (…) La denuncia <span class=\"m-caja\"><mark class=\"m-accion\">surtirá</mark></span> <span class=\"m-caja\"><mark class=\"m-plazo\">efecto</mark></span> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2321\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">un año después de la fecha en que el Secretario General haya recibido la notificación</mark>. 2. <mark class=\"m-autoridad\">Las organizaciones regionales de integración económica</mark> <mark class=\"m-accion\">dejarán</mark> <mark class=\"m-personalizado\">de ser Partes</mark> en el presente Protocolo <mark class=\"m-resp r-ia\" data-q=\"2-ia-1247\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando lo hayan denunciado todos sus Estados miembros</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1233\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>Art. 20.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-resp\" data-q=\"2-71,2-150\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">El Secretario General de las Naciones Unidas será el depositario</mark> del presente Protocolo. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">R35 2. El original del presente Protocolo, cuyos textos en árabe, chino, español, francés, inglés y ruso son igualmente auténticos, se depositará en poder del Secretario General de las Naciones Unidas.</span></span></p><p>El presente Convenio <mark class=\"m-accion\">entrará</mark> en <mark class=\"m-plazo\">vigor</mark> de forma general y <mark class=\"m-plazo\">para España el</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1320,2-ia-1324,2-ia-2322\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">25 de diciembre de 2003</mark> de conformidad con lo establecido en su <span class=\"ref-art\">artículo 17</span>.</p></div></div><div class=\"ex-linea\">Artículo 20 — <mark class=\"m-destacable\">Depositario</mark> e idiomas <span class=\"ex-sello ex-sello-r\">R35</span>: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2540\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta más de este artículo</mark></div><div class=\"bloque-titulo\">2.6 — <mark class=\"m-personalizado\">PROTOCOLO</mark> CONTRA <mark class=\"m-destacable\">EL TRÁFICO ILÍCITO</mark> <mark class=\"m-personalizado\">DE MIGRANTES</mark> POR TIERRA, <mark class=\"m-personalizado\">MAR Y</mark> AIRE, QUE <mark class=\"m-destacable\">COMPLEMENTA</mark> <mark class=\"m-personalizado\">LA CONVENCIÓN</mark> DE PALERMO (Nueva York, 15-11-2000)</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 1 a 5 — Relación con la Convención, finalidad, definiciones, ámbito y responsabilidad de los migrantes <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b>Art. 1.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. <mark class=\"m-personalizado\">El presente Protocolo</mark> <mark class=\"m-destacable\">complementa</mark> <mark class=\"m-personalizado\">la Convención</mark> (…) <mark class=\"m-personalizado\">y se</mark> <mark class=\"m-accion\">interpretará</mark> <mark class=\"m-personalizado\">juntamente</mark> con la Convención. 2. (…) <mark class=\"m-destacable\">mutatis mutandis</mark> (…). 3.</span></span> Los <mark class=\"m-personalizado\">delitos tipificados</mark> con arreglo al <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 6</span></mark> del presente Protocolo <mark class=\"m-resp r-ia\" data-q=\"2-ia-2230\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se considerarán delitos tipificados con arreglo a la Convención</mark>.</p><p><b>Art. 2.</b> <mark class=\"m-destacable\">El propósito del presente Protocolo es prevenir y combatir el tráfico ilícito de migrantes</mark>, <mark class=\"m-destacable\">así como promover la cooperación</mark> entre los <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-personalizado\">con</mark> ese fin,</span></span> protegiendo al mismo tiempo los <mark class=\"m-resp r-ia\" data-q=\"2-ia-2324\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">derechos de los migrantes objeto de dicho tráfico</mark>.</p><p data-ex=\"EXOF,*\"><b>Art. 3.</b> a) Por <mark class=\"m-destacable\">«tráfico ilícito de migrantes»</mark> <mark class=\"m-accion\">se entenderá</mark> la <mark class=\"m-personalizado\">facilitación <u class=\"m-clave\">de</u> la entrada ilegal</mark> de una persona <mark class=\"m-personalizado\">en un</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte del</mark> cual dicha persona <mark class=\"m-personalizado\">no sea nacional o residente permanente</mark> <mark class=\"m-resp\" data-q=\"2-116,2-ia-1852,2-ia-2201,2-ia-2325\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">con el fin de obtener, directa o indirectamente, un beneficio financiero u otro beneficio de orden material</mark>; b) por <mark class=\"m-destacable\">«entrada ilegal»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2326,2-ia-2417\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el paso de fronteras sin haber cumplido los requisitos necesarios para entrar legalmente en el Estado receptor</mark>; c) por <mark class=\"m-destacable\">«documento de identidad o de viaje falso»</mark> se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">cualquier documento</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de viaje o de identidad</span></span>: i) <mark class=\"m-personalizado\">elaborado o expedido de <u class=\"m-clave\">forma espuria</u></mark> o alterado <mark class=\"m-personalizado\">materialmente</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">por cualquiera que no sea la persona o entidad legalmente autorizada para producir o expedir el documento de viaje o de identidad en nombre de un Estado; o</span></span>; ii) <mark class=\"m-resp r-ia\" data-q=\"2-ia-1839\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">expedido u obtenido indebidamente mediante declaración falsa, corrupción o coacción</mark> <mark class=\"m-personalizado\">o de cualquier otra forma ilegal;</mark> o iii) <mark class=\"m-personalizado\"><u class=\"m-clave\">utilizado</u> por una persona que no sea su titular legítimo</mark>; d) por <mark class=\"m-destacable\">«buque»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2328\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualquier tipo de embarcación, con inclusión de las embarcaciones sin desplazamiento y los hidroaviones</mark>, que se utilice o pueda <mark class=\"m-personalizado\">utilizarse como medio de transporte sobre el agua,</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">excluidos</mark></span> los <mark class=\"m-personalizado\">buques de guerra</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, los buques auxiliares de la armada u otros buques que sean propiedad de un Estado o explotados por éste y que en ese momento se empleen únicamente en servicios oficiales no comerciales</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-1638,2-ia-2327\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>Art. 4.</b> (…) se <mark class=\"m-accion\">aplicará</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a la preven- ción, la investigación y el enjuiciamiento de:</span></span> <mark class=\"m-personalizado\">a los delitos</mark> tipificados con arreglo al <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 6</span></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Protocolo</span></span>, <mark class=\"m-resp\" data-q=\"2-143,2-ia-2507\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">cuando esos delitos sean de carácter transnacional y entrañen la participación de un grupo delictivo organizado</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, así como a la protección de los derechos de las personas que hayan sido objeto de tales delitos</span></span>.</p><p><b>Art. 5.</b> <mark class=\"m-destacable\">Los migrantes</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-1858,2-ia-1860,2-ia-2330,2-ia-2419\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no estarán sujetos a enjuiciamiento penal con arreglo al presente Protocolo por el hecho de haber sido objeto de alguna de las conductas enunciadas en el <span class=\"ref-art\">artículo 6</span></mark> del presente Protocolo.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 6</mark> — Penalización: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2331,2-ia-2334,2-ia-2407\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 3 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 7 y 8 — Tráfico ilícito de migrantes por mar · R36 R37 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R36</span> <span class=\"ex-sello ex-sello-r\">R37</span></div><div class=\"ex-fb\"><p data-r=\"R36\"><span class=\"ex-sello ex-sello-r\">R36</span> <b>Art. 7.</b> <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">cooperarán</mark> en la mayor medida posible <mark class=\"m-personalizado\">para</mark> <mark class=\"m-destacable\">prevenir</mark> y <mark class=\"m-destacable\">reprimir</mark> <mark class=\"m-personalizado\">el tráfico ilícito de migrantes por mar, de conformidad con el derecho internacional del</mark> <mark class=\"m-destacable\">mar</mark>. <mark class=\"m-resp ex-q\" data-q=\"2-151,2-ia-2336\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 8.</b> 2. <mark class=\"m-autoridad\">Todo Estado Parte</mark> que tenga <mark class=\"m-destacable\">motivos razonables</mark> para sospechar que <mark class=\"m-personalizado\">un buque que esté haciendo uso de la libertad de navegación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">con arreglo al derecho internacional</span></span> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">que enarbole el pabellón</mark> o lleve matrícula de otro <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-personalizado\">está involucrado en el tráfico</mark> ilícito de migrantes por mar <mark class=\"m-resp r-ia\" data-q=\"2-ia-2338,2-ia-2340\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">podrá notificarlo al Estado del pabellón, pedirle que confirme la matrícula y, si la confirma, solicitarle autorización para adoptar medidas apropiadas</mark> con respecto a ese buque. El <mark class=\"m-autoridad\">Estado</mark> del pabellón <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">autorizar</mark> al <mark class=\"m-autoridad\">Estado</mark> requirente, entre otras cosas, a: a) <mark class=\"m-resp\" data-q=\"2-152\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">visitar el buque</mark>; b) <mark class=\"m-resp\" data-q=\"2-152\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">registrar el buque</mark>; y c) <mark class=\"m-resp\" data-q=\"2-18,2-87,2-ia-2339,2-ia-2343\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">si se hallan pruebas <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de que el buque está involucrado en el tráfico ilícito de migrantes por mar</span></span>, adoptar medidas apropiadas con respecto al buque, así como a las personas y a la carga que se encuentren a bordo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, conforme le haya autorizado el Estado del pabellón</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2337\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>5.</b> (…) <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">adoptarán</mark> <mark class=\"m-personalizado\">otras <u class=\"m-clave\">medidas sin</u> la <u class=\"m-clave\">autorización</u> expresa del</mark> <mark class=\"m-autoridad\">Estado del pabellón</mark>, salvo las que sean necesarias <mark class=\"m-resp r-ia\" data-q=\"2-ia-2341\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">para eliminar un peligro inminente para la vida de las personas</mark> o <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">las que se <mark class=\"m-personalizado\">deriven de los <u class=\"m-clave\">acuerdos bilaterales</u> o multilaterales pertinentes</mark></span></span> .</p><p><b>6.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">designará</mark> a <mark class=\"m-autoridad\">una</mark> <mark class=\"m-destacable\">o</mark> (…) <mark class=\"m-autoridad\">varias autoridades</mark> <mark class=\"m-personalizado\">para recibir y atender las</mark> solicitudes de asistencia (…).</span></span> Esa designación <mark class=\"m-accion\">será</mark> dada a conocer, <mark class=\"m-resp r-ia\" data-q=\"2-ia-1241,2-ia-2342\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">por conducto del Secretario General, a todos los demás Estados Parte dentro del mes siguiente</mark> a la designación.</p><p data-ex=\"*\" data-r=\"R37\"><span class=\"ex-sello ex-sello-r\">R37</span> <b>7.</b> <mark class=\"m-autoridad\">Todo Estado Parte</mark> que <mark class=\"m-personalizado\">tenga motivos razonables para sospechar</mark> <u class=\"m-clave\">que</u> un buque <mark class=\"m-personalizado\">está involucrado</mark> en el tráfico ilícito de migrantes por <mark class=\"m-personalizado\">mar y</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2508\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">no posee nacionalidad</mark> <mark class=\"m-personalizado\">o se hace pasar por un buque sin</mark> <mark class=\"m-destacable\">nacionalidad</mark> <mark class=\"m-resp\" data-q=\"2-152\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">podrá visitar y registrar el buque</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Si se hallan pruebas que confirmen la sospecha, ese Estado Parte adoptará medidas apropiadas de conformidad con el derecho interno e internacional, según proceda.</span></span></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 9 — Cláusulas de protección <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> <mark class=\"m-personalizado\">Cuando</mark> <mark class=\"m-autoridad\">un Estado Parte</mark> <mark class=\"m-personalizado\">adopte medidas</mark> contra un buque con arreglo al <span class=\"ref-art\">artículo 8</span> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del presente Protocolo</span></span>: a) <mark class=\"m-resp\" data-q=\"2-28\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">garantizará la seguridad y el trato humano de las personas que se encuentren a bordo</mark>; b) <mark class=\"m-resp\" data-q=\"2-28\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">tendrá debidamente en cuenta la necesidad de no poner en peligro la seguridad del buque o de su carga</mark>; c) <mark class=\"m-accion\">tendrá</mark> debidamente en cuenta la necesidad de <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> perjudicar los intereses comerciales o jurídicos del</mark> <mark class=\"m-autoridad\">Estado del pabellón</mark> <mark class=\"m-destacable\">o</mark> de cualquier <mark class=\"m-autoridad\">otro Estado interesado</mark>; d) <mark class=\"m-resp\" data-q=\"2-28,2-ia-2401\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">velará, dentro de los medios disponibles, porque las medidas adoptadas con respecto al buque sean ecológicamente razonables</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2063\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Cuando <u class=\"m-clave\">las razones</u> que motivaron las medidas</mark> (…) no resulten <mark class=\"m-personalizado\"><u class=\"m-clave\">fundadas</u> y siempre que el buque no haya <u class=\"m-clave\">cometido</u> ningún acto que las justifique</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2402\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">dicho buque será indemnizado por todo perjuicio o daño sufrido</mark>.</p><p><b>3.</b> <mark class=\"m-destacable\">Toda medida</mark> (…) <mark class=\"m-accion\">tendrá</mark> debidamente <mark class=\"m-personalizado\">en cuenta</mark> la necesidad de <mark class=\"m-personalizado\">no interferir ni causar menoscabo en:</mark> a) <mark class=\"m-resp\" data-q=\"2-4,2-75\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">los derechos y las obligaciones de los Estados ribereños en el ejercicio de su jurisdicción</mark> de conformidad con el derecho internacional del mar; ni en b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2403\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la competencia del Estado del pabellón para ejercer la jurisdicción y el control en cuestiones administrativas, técnicas y sociales relacionadas con el buque</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2428\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>4.</b> Toda <mark class=\"m-personalizado\">medida</mark> que se adopte en el mar <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">en cumplimiento de lo dispuesto en el presente capítulo</span></span> <mark class=\"m-accion\">será</mark> ejecutada únicamente por <mark class=\"m-resp r-ia\" data-q=\"2-ia-2404\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">buques de guerra o aeronaves militares, o por otros buques o aeronaves que ostenten signos claros y sean identificables como buques o aeronaves al servicio de un gobierno</mark> y autorizados a tal fin.</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 10 a 14 — Información, medidas fronterizas, documentos y capacitación</div><div class=\"ex-fb\"><p><b>Art. 10.</b> 1. (…) <mark class=\"m-autoridad\">los Estados Parte</mark>, <mark class=\"m-personalizado\">en particular los que tengan fronteras comunes o estén situados en las rutas de tráfico ilícito de migrantes</mark>, <mark class=\"m-accion\">intercambiarán</mark> (…) <mark class=\"m-destacable\">información</mark> pertinente <mark class=\"m-personalizado\">sobre asuntos como:</mark> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2405\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los lugares de embarque y de destino, así como las rutas, los transportistas y los medios de transporte</mark> <mark class=\"m-personalizado\">a</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">los que (…) recurren los grupos delictivos organizados (…);</span></span>  b) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2405\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la identidad y los métodos de las organizaciones o los grupos delictivos organizados</mark> (…); <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(…) 2. El <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-personalizado\">receptor de dicha información</mark> <mark class=\"m-accion\">dará</mark> cumplimiento a toda solicitud (…) de imponer restricciones <mark class=\"m-destacable\">a su utilización</mark>.</span></span></p><p><b>Art. 11.</b> 1. <mark class=\"m-resp\" data-q=\"2-147\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Sin perjuicio de los compromisos internacionales relativos a la libre circulación de personas</mark>, <mark class=\"m-autoridad\">los Estados Parte</mark> <mark class=\"m-accion\">reforzarán</mark>, en la medida de lo posible, <mark class=\"m-personalizado\">los controles fronterizos</mark> (…). <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">3. (…) <mark class=\"m-personalizado\">obligación de los transportistas comerciales</mark> (…) de <mark class=\"m-personalizado\">cerciorarse</mark> de que todos los <mark class=\"m-personalizado\">pasajeros tengan en su poder los documentos de viaje requeridos</mark> (…).</span></span> 5. <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">considerará</mark> la posibilidad de <mark class=\"m-accion\">adoptar</mark> <mark class=\"m-personalizado\">medidas</mark> que permitan (…) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2310,2-ia-2333\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">denegar la entrada o revocar visados a personas implicadas en la comisión de delitos tipificados con arreglo al presente Protocolo</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2039,2-ia-2415\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 2 preguntas</mark></p><p><b>Art. 14.</b> 2. (…) Dicha capacitación <mark class=\"m-accion\">incluirá</mark>, entre <mark class=\"m-personalizado\">otras</mark> cosas: a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2409\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la mejora de la seguridad y la calidad de los documentos de viaje</mark>; <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">b) <mark class=\"m-personalizado\">el</mark> <mark class=\"m-destacable\">reconocimiento y la detección</mark> de los documentos de viaje o de identidad <mark class=\"m-personalizado\">falsificados</mark>; (…) e) <mark class=\"m-resp r-ia r-vec\" data-q=\"2-ia-2409\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el trato humano de los migrantes afectados</mark> y la <span class=\"m-caja\"><mark class=\"m-personalizado\">protección</mark></span> de <mark class=\"m-personalizado\">sus derechos</mark> (…).</span></span></p></div></div><div class=\"ex-linea\">Artículos 15, 16 y 18 — Prevención, <mark class=\"m-personalizado\">protección</mark> y <mark class=\"m-personalizado\">repatriación</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2131,2-ia-2412,2-ia-2416,2-ia-2418\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 4 preguntas más de este artículo</mark></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 19 a 25 — Salvaguardia, controversias, firma y enmiendas</div><div class=\"ex-fb\"><p><b>Art. 19.</b> 1. <mark class=\"m-personalizado\">Nada</mark> de lo dispuesto en el presente <mark class=\"m-personalizado\">Protocolo</mark> <mark class=\"m-accion\">afectará</mark> a los demás <mark class=\"m-personalizado\">derechos</mark>, <mark class=\"m-personalizado\">obligaciones</mark> y responsabilidades de los <mark class=\"m-autoridad\">Estados</mark> y las personas con arreglo al <mark class=\"m-personalizado\">derecho internacional</mark>, <mark class=\"m-personalizado\">incluidos</mark> <mark class=\"m-resp\" data-q=\"2-151\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">el derecho internacional humanitario y la normativa internacional de derechos humanos</mark> <mark class=\"m-personalizado\">y, en</mark> particular, (…) la <mark class=\"m-personalizado\">Convención</mark> sobre el Estatuto de los <mark class=\"m-personalizado\">Refugiados de</mark> 1951 y su Protocolo de 1967, <mark class=\"m-personalizado\">así como</mark> <mark class=\"m-destacable\">el</mark> principio de non-refoulement (…).</p><p><b>Art. 20.</b> (…) 2. (…) <mark class=\"m-personalizado\">arbitraje</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Si,</span></span> seis meses <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">después de la fecha de la solicitud de arbitraje, esos Estados Parte no han podido ponerse de acuerdo sobre la organización del arbitraje, cualquiera de esas Partes podrá remitir la controversia a la</span></span> <mark class=\"m-autoridad\">Corte</mark> Internacional de Justicia <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mediante solicitud conforme al Estatuto de la Corte</span></span>. 3. <mark class=\"m-autoridad\">Cada Estado</mark> Parte <mark class=\"m-accion\">podrá</mark>, <mark class=\"m-personalizado\">en el momento de la firma, ratificación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, aceptación o aprobación del presente Protocolo o adhesión a él</span></span>, <mark class=\"m-resp r-vec\" data-q=\"2-63\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">declarar que no se considera vinculado por el párrafo 2</mark> del presente artículo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">. Los demás Estados Parte no quedarán vinculados por el párrafo 2 del presente artículo respecto de todo Estado Parte que haya hecho esa reserva</span></span>. 4. El <mark class=\"m-autoridad\">Estado</mark> Parte que haya <mark class=\"m-personalizado\">hecho una reserva</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de conformidad con el párrafo 3 del presente artículo</span></span> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">en cualquier momento retirar esa reserva notificándolo al</mark> <mark class=\"m-resp\" data-q=\"2-63\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretario General de las Naciones Unidas</mark>.</p><p><b>Art. 23.</b> 4. Toda enmienda refrendada (…) <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor</mark> <mark class=\"m-autoridad\">respecto de un Estado</mark> <mark class=\"m-personalizado\">Parte</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2423\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">noventa días después de la fecha en que éste deposite</mark> en <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">poder del <mark class=\"m-autoridad\">Secretario General</mark> (…) un instrumento de ratificación (…) <mark class=\"m-personalizado\">de esa</mark> enmienda.</span></span></p><p><b><mark class=\"m-personalizado\">Art.</mark> 25.</b> <mark class=\"m-destacable\">El</mark> <mark class=\"m-resp\" data-q=\"2-3\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">Secretario General de las Naciones Unidas</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-destacable\">depositario</mark> del presente Protocolo. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">(Para pasar <mark class=\"m-personalizado\">a ser parte en un protocolo</mark> también hay que ser parte en <mark class=\"m-personalizado\">la Convención</mark>: <mark class=\"m-personalizado\"><span class=\"ref-art\">art. 37.2</span> de la</mark> Convención).</span></span></p></div></div><div class=\"bloque-titulo\">2.7 — <mark class=\"m-personalizado\">PROTOCOLO</mark> CONTRA LA <mark class=\"m-destacable\">FABRICACIÓN</mark> Y EL TRÁFICO ILÍCITOS DE ARMAS DE <u class=\"m-clave\">FUEGO</u>, <mark class=\"m-personalizado\">SUS PIEZAS Y COMPONENTES Y MUNICIONES</mark>, QUE <mark class=\"m-destacable\">COMPLEMENTA</mark> <mark class=\"m-personalizado\">LA CONVENCIÓN</mark> DE PALERMO (Nueva York, 31-5-2001)</div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 1 a 4 — Relación con la Convención, finalidad, definiciones y ámbito <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p><b><mark class=\"m-personalizado\">Art. 1.</mark></b> 3. <mark class=\"m-personalizado\">Los delitos</mark> tipificados con arreglo al <mark class=\"m-personalizado\"><span class=\"ref-art\">artículo 5</span> del presente Protocolo</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2230\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se considerarán delitos tipificados con arreglo a la Convención contra la Delincuencia Organizada Transnacional</mark>.</p><p data-ex=\"EXOF\"><b>Art. 2.</b> La <mark class=\"m-destacable\">finalidad</mark> del presente Protocolo es <mark class=\"m-resp\" data-q=\"2-117,2-ia-2231,2-ia-2427,2-ia-2430,2-ia-2532\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">promover, facilitar y reforzar la cooperación entre los Estados Parte con el propósito de prevenir, combatir y erradicar la fabricación y el tráfico ilícitos de armas de fuego</mark>, <mark class=\"m-plazo\">sus</mark> piezas y componentes y municiones.</p><p data-ex=\"EXOF,*\"><b>Art. 3.</b> a) Por <mark class=\"m-destacable\">«arma de fuego»</mark> <mark class=\"m-accion\">se entenderá</mark> toda arma <mark class=\"m-personalizado\"><u class=\"m-clave\">portátil</u></mark> que tenga cañón y <mark class=\"m-personalizado\">que lance, esté concebida para lanzar o pueda transformarse fácilmente para lanzar un balín, una bala o un proyectil por la acción de un <u class=\"m-clave\">explosivo</u></mark>, <span class=\"m-circulo\"><mark class=\"m-destacable\">excluidas</mark></span> las armas de fuego <mark class=\"m-personalizado\">antiguas o sus réplicas</mark>. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Las armas de fuego antiguas y sus réplicas se definirán de conformidad con el derecho interno.</span></span> <mark class=\"m-personalizado\">En ningún caso</mark>, sin embargo, <mark class=\"m-accion\">podrán</mark> incluir armas de fuego fabricadas <mark class=\"m-resp r-ia\" data-q=\"2-ia-2501\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">después de 1899</mark>; b) por <mark class=\"m-destacable\">«piezas y componentes»</mark> se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">todo <u class=\"m-clave\">elemento o</u></mark> elemento de <mark class=\"m-personalizado\"><u class=\"m-clave\">repuesto</u> específicamente concebido para un arma de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">fuego</u> e</mark> indispensable <mark class=\"m-personalizado\">para su funcionamiento</mark>, <mark class=\"m-personalizado\">incluidos el cañón, la caja o el cajón, el cerrojo o el tambor, el cierre o el bloqueo del cierre y todo dispositivo concebido o adaptado para disminuir el sonido</mark> causado por el disparo <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de un arma de fuego</span></span>; c) por «municiones» se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2503\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el cartucho completo o sus componentes, entre ellos las vainas, los cebos, la carga propulsora, las balas o proyectiles</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">utilizados en las armas de fuego</span></span>, siempre <mark class=\"m-personalizado\">que</mark> esos <mark class=\"m-personalizado\">componentes estén de por sí</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2503\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">sujetos a autorización</mark> en el respectivo <mark class=\"m-autoridad\">Estado</mark> Parte; d) por <mark class=\"m-destacable\">«fabricación ilícita»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-personalizado\">la fabricación o el montaje</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de armas de fuego, sus piezas y componentes o municiones</span></span>: i) a <mark class=\"m-personalizado\">partir de</mark> <mark class=\"m-destacable\">piezas y componentes</mark> que hayan sido <mark class=\"m-personalizado\">objeto de tráfico ilícito</mark>; ii) <mark class=\"m-resp\" data-q=\"2-118\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">sin licencia o autorización</mark> de una <mark class=\"m-autoridad\">autoridad</mark> competente <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">del Estado Parte en que se realice la fabricación o el montaje</span></span>; <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> iii) <mark class=\"m-resp\" data-q=\"2-118,2-ia-2504\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">sin marcar las armas de fuego en el momento de su fabricación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">, de conformidad con el artículo 8 del presente Protocolo; La concesión de licencia o autorización respecto de la fabricación de piezas y componentes se hará de conformidad con el derecho interno</span></span>; e) <mark class=\"m-personalizado\">por</mark> <mark class=\"m-destacable\">«tráfico ilícito»</mark> se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">la importación</mark>, <mark class=\"m-personalizado\">exportación</mark>, <mark class=\"m-personalizado\">adquisición</mark>, <mark class=\"m-personalizado\">venta, entrega</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">traslado o transferencia</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de armas de fuego, sus piezas y componentes y municiones desde o a través del territorio de un Estado Parte al de otro Estado Parte</span></span> <mark class=\"m-personalizado\">si cualquiera</mark> de los <mark class=\"m-autoridad\">Estados Partes</mark> interesados <mark class=\"m-personalizado\">no lo autoriza</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">conforme a lo dispuesto en el presente Protocolo</span></span> <mark class=\"m-personalizado\">o si las armas</mark> de fuego <mark class=\"m-personalizado\">no han sido marcadas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">conforme a lo dispuesto en el artículo 8 del presente Protocolo</span></span>; f) por <mark class=\"m-destacable\">«localización»</mark> se <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2505\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el rastreo sistemático de las armas de fuego</mark> y, <mark class=\"m-personalizado\">de ser posible</mark>, <mark class=\"m-personalizado\">de sus piezas y componentes y municiones</mark>, <mark class=\"m-resp\" data-q=\"2-25,2-ia-2410,2-ia-2502,2-ia-2506\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">desde el fabricante al comprador</mark>, con el <mark class=\"m-personalizado\">fin</mark> de ayudar <mark class=\"m-personalizado\">a las</mark> <mark class=\"m-autoridad\">autoridades</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">competentes de los Estados Parte</span></span> a detectar, <mark class=\"m-personalizado\"><u class=\"m-clave\">investigar y</u> analizar la fabricación y el tráfico ilícitos</mark>.</p><p><b>Art. 4.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. (…) cuando esos delitos sean de <mark class=\"m-personalizado\">carácter transnacional y</mark> entrañen la <mark class=\"m-personalizado\">participación de un grupo delictivo organizado</mark>. 2.</span></span> El presente Protocolo <mark class=\"m-destacable\"><u class=\"m-clave\">no se</u></mark> <mark class=\"m-accion\">aplicará</mark> <mark class=\"m-personalizado\">a las</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2033,2-ia-2408,2-ia-2508\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">transacciones entre Estados ni a las transferencias estatales cuando la aplicación del Protocolo pudiera perjudicar el derecho de un Estado Parte a adoptar medidas en aras de la seguridad nacional</mark> (…). <mark class=\"m-resp ex-q r-ia\" data-q=\"2-ia-2220\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 5 y 6 — Penalización y decomiso <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"EX\"><b>Art. 5.</b> 1. Cada <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">las medidas</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">legislativas o de otra índole que sean necesarias</span></span> para <mark class=\"m-personalizado\">tipificar como delito</mark> las siguientes conductas, cuando se <mark class=\"m-personalizado\">cometan</mark> <mark class=\"m-destacable\">intencionalmente</mark>: a) <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">fabricación</u></mark> ilícita <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de armas de fuego, sus piezas y componentes y municiones</span></span>; b) <mark class=\"m-destacable\">el <u class=\"m-clave\">tráfico ilícito</u></mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de armas de fuego, sus piezas y componentes y municiones</span></span>; c) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2509,2-ia-2518\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la falsificación o la obliteración, supresión o alteración ilícitas de la(s) marca(s) de un arma de fuego requerida(s) de conformidad con el <span class=\"ref-art\">artículo 8</span></mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">Cada Estado Parte adoptará asimismo las medidas legislativas y de otra índole que sean necesarias para tipificar como delito las siguientes conductas: \u0007</span></span> a) con sujeción a los conceptos básicos de su ordenamiento jurídico, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2510\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">la tentativa de comisión de un delito</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">tipificado con arreglo al párrafo 1 del presente artículo</span></span> o la participación en él como <mark class=\"m-destacable\">cómplice</mark>; <mark class=\"m-destacable\">y</mark> b) <mark class=\"m-destacable\">la organización</mark>, <mark class=\"m-destacable\">dirección</mark>, <mark class=\"m-destacable\">ayuda, incitación</mark>, <mark class=\"m-destacable\">facilitación o asesoramiento</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">para la comisión de un delito tipificado con arreglo al párrafo 1 del presente artículo</span></span>.</p><p><b>Art. 6.</b> 2. <mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">adoptarán</mark> (…) <mark class=\"m-personalizado\">las medidas necesarias para impedir</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que las armas de fuego (…) que hayan sido <mark class=\"m-personalizado\">objeto de</mark> fabricación o tráfico</span></span> ilícitos <mark class=\"m-personalizado\">caigan en manos de personas no autorizadas</mark>, <span class=\"m-caja\"><mark class=\"m-personalizado\">en</mark></span> <mark class=\"m-personalizado\">particular mediante la</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2511\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">incautación y destrucción</mark> de esas armas de fuego (…), <mark class=\"m-resp r-ia\" data-q=\"2-ia-2512\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a menos que se haya autorizado oficialmente otra forma de disposición</mark> (…).</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 7, 8 y 9 — Registros, marcación y desactivación <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"EXOF\"><b>Art. 7.</b> <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">garantizará</mark> <mark class=\"m-destacable\">el mantenimiento</mark>, por un período <mark class=\"m-resp\" data-q=\"2-24\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">no inferior a diez años</mark>, de <mark class=\"m-destacable\">la información</mark> relativa a las <mark class=\"m-personalizado\">armas de fuego y, cuando sea apropiado y factible</mark>, de la información relativa a <mark class=\"m-personalizado\">sus piezas y componentes y municiones</mark> que sea necesaria <mark class=\"m-personalizado\">para localizar e identificar las armas</mark> de fuego <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y, cuando sea apropiado y factible, sus piezas y componentes y municiones que hayan sido objeto de fabricación o tráfico ilícitos, así como para evitar y detectar esas actividades. Esa información incluirá</span></span>.</p><p><b>Art. 8.</b> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">1. <mark class=\"m-personalizado\">A los efectos de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">identificar</u></mark> y localizar <mark class=\"m-personalizado\">cada arma</mark> de fuego, <mark class=\"m-autoridad\">los Estados Parte</mark>:</span></span> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2515\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">en el momento de la fabricación de cada arma de fuego exigirán que ésta sea marcada con una marca distintiva que indique el nombre del fabricante, el país o lugar de fabricación y el número de serie</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-accion\">mantendrán</mark> cualquier <mark class=\"m-personalizado\">otra marca distintiva y fácil</mark> de emplear que <mark class=\"m-personalizado\">ostente</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2516\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">símbolos geométricos sencillos, junto con un código numérico y/o alfanumérico</mark>, <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">y que <mark class=\"m-personalizado\">permita a todos los</mark> <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-personalizado\">identificar sin dificultad el país de fabricación</mark>; <mark class=\"m-destacable\"><u class=\"m-clave\">b)</u></mark> <mark class=\"m-accion\">exigirán</mark> <mark class=\"m-personalizado\">que</mark> se aplique a toda <mark class=\"m-personalizado\">arma</mark> de fuego <mark class=\"m-personalizado\"><u class=\"m-clave\">importada</u></mark> <u class=\"m-clave\">una</u> <mark class=\"m-personalizado\"><u class=\"m-clave\">marca sencilla</u></mark> <mark class=\"m-destacable\">y apropiada</mark> que permita <mark class=\"m-personalizado\">identificar el país de importación</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">y,</mark></span> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">ser</u></mark> posible, <mark class=\"m-personalizado\">el año</mark> de ésta (…);</span></span>  c) <mark class=\"m-accion\">velarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">por</u></mark> que, <mark class=\"m-personalizado\"><u class=\"m-clave\">en el</u> momento en que se transfiera</mark> <u class=\"m-clave\">un arma</u> de fuego <mark class=\"m-personalizado\">de <u class=\"m-clave\">las existencias</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">estatales a</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u> utilización civil con carácter permanente</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2517\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">se aplique a dicha arma la marca distintiva apropiada que permita a todos los Estados Parte identificar el país que realiza la transferencia</mark>.</p><p data-ex=\"*\"><b>Art. 9.</b> (…) a) <mark class=\"m-resp\" data-q=\"2-198,2-ia-2519,2-ia-2520,2-ia-2521\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">todas las piezas esenciales de un arma de fuego desactivada se tornarán permanentemente inservibles y no susceptibles de ser retiradas, sustituidas o modificadas</mark> de cualquier forma <mark class=\"m-personalizado\">que</mark> pueda <mark class=\"m-personalizado\">permitir su reactivación</mark>; (…)</p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 10 — Requisitos generales para sistemas de licencias o autorizaciones <span class=\"ex-sello ex-sello-r\">R38</span></div><div class=\"ex-fb\"><p data-r=\"R38\"><span class=\"ex-sello ex-sello-r\">R38</span> <b>1.</b> <mark class=\"m-autoridad\">Cada Estado Parte</mark> <mark class=\"m-accion\">establecerá o mantendrá</mark> <mark class=\"m-personalizado\">un sistema eficaz de licencias o autorizaciones de exportación e importación, así como de medidas aplicables al tránsito internacional,</mark> para la transferencia de armas de fuego, sus piezas y componentes y municiones. <mark class=\"m-resp ex-q\" data-q=\"2-153,2-ia-2522\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 10 y 11 — Licencias de exportación, importación y tránsito y medidas de seguridad</div><div class=\"ex-fb\"><p><b>Art. 10.</b> 2. <mark class=\"m-personalizado\">Antes</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">de</mark></span> <mark class=\"m-personalizado\">emitir licencias o autorizaciones de exportación</mark> (…), <mark class=\"m-autoridad\">cada Estado Parte</mark> se <mark class=\"m-accion\">asegurará</mark> <mark class=\"m-personalizado\">de que:</mark> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2523\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los Estados importadores hayan emitido las correspondientes licencias o autorizaciones</mark>; <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">y</mark> b) <mark class=\"m-autoridad\">los Estados de tránsito</mark> <mark class=\"m-personalizado\">hayan</mark> al menos <mark class=\"m-personalizado\">comunicado por escrito</mark>, <mark class=\"m-personalizado\">con anterioridad</mark> a la expedición, que <mark class=\"m-personalizado\">no se oponen al</mark> tránsito (…).</span></span>  3. La <mark class=\"m-destacable\">licencia o autorización</mark> <mark class=\"m-personalizado\">de exportación e importación</mark> y la documentación que la acompañe <mark class=\"m-accion\">contendrán</mark> (…) como <mark class=\"m-personalizado\">mínimo</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2524\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el lugar y la fecha de emisión, la fecha de expiración</mark>, el <mark class=\"m-personalizado\">país de exportación</mark>, el <mark class=\"m-personalizado\">país de importación</mark>, <mark class=\"m-resp r-ia r-vec\" data-q=\"2-ia-2524\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">el destinatario final</mark>, una <mark class=\"m-personalizado\">descripción y la cantidad de las armas de</mark> fuego (…) <mark class=\"m-personalizado\">y, cuando haya tránsito</mark>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2523,2-ia-2524\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">los países de tránsito</mark>. (…)</p><p><b>Art. 11.</b> (…) <mark class=\"m-autoridad\">cada Estado</mark> Parte <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">medidas apropiadas para:</mark> a) <mark class=\"m-resp r-ia\" data-q=\"2-ia-2525,2-ia-2527,2-ia-2528\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">exigir que se garantice la seguridad de las armas de fuego, sus piezas y componentes y municiones en el curso de su fabricación, de su importación y exportación y de su tránsito</mark> <mark class=\"m-personalizado\">a</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">través de su territorio; <mark class=\"m-personalizado\">y</mark> b) <mark class=\"m-personalizado\">aumentar la eficacia de los controles de importación</mark>, <mark class=\"m-personalizado\">exportación y tránsito</mark> (…).</span></span></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 12, 13 y 15 — Información, cooperación y corredores <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R39</span></div><div class=\"ex-fb\"><p><b>Art. 12.</b> 5. (…) <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-resp r-ia r-vec\" data-q=\"2-ia-2529,2-ia-2530\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">garantizará la confidencialidad</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">acatará</mark> <mark class=\"m-personalizado\">las restricciones impuestas a la utilización de toda información que reciba de</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">otro Estado Parte</mark> (…), incluida información de</span></span> dominio privado sobre transacciones comerciales, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2529,2-ia-2530\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cuando así lo solicite el Estado Parte que facilita la información</mark>. (…)</p><p><b>Art. 13.</b> 2. (…) <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-accion\">designará</mark> <mark class=\"m-resp r-ia\" data-q=\"2-ia-2531\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">un órgano nacional o un punto de contacto central</mark> encargado de <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mantener el <mark class=\"m-personalizado\">enlace con los demás</mark> <mark class=\"m-autoridad\">Estados</mark> Parte en toda cuestión relativa al presente Protocolo.</span></span></p><p data-ex=\"EX\" data-r=\"R39\"><span class=\"ex-sello ex-sello-r\">R39</span> <b>Art. 15.</b> 1. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">ARTÍCULO 15. CORREDORES Y CORRETAJE. R39 1. \u0007Con miras a prevenir y combatir la fabricación y el tráfico ilícitos de armas de fuego, sus piezas y com- ponentes y municiones,</span></span> los <mark class=\"m-autoridad\">Estados</mark> Parte que aún no lo hayan hecho <mark class=\"m-resp r-ia\" data-q=\"2-ia-2533\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">considerarán la posibilidad de establecer un sistema de reglamentación</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">de las actividades de las personas dedicadas al corretaje. Ese sistema podría incluir una o varias de</span></span> las siguientes medidas: <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">a) Exigir la inscripción en un registro de los corredores que actúen en su territorio; b) Exigir una licencia o autorización para el ejercicio del corretaje; o c) \u0007Exigir que en las licencias o autorizaciones de importación y de exportación, o en la docu- mentación adjunta a la mercancía, se consigne el nombre y la ubicación de los corredores que intervengan en la transacción. 2. \u0007Se alienta a los Estados Parte que hayan establecido un sistema de autorización de las operaciones de corretaje como el descrito en el párrafo 1 del presente artículo a que incluyan datos sobre los corredores y las operaciones de corretaje en sus intercambios de información efectuados con arreglo al artículo 12 del presente Protocolo y a que mantengan un</span></span> registro de corredores <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">que actúen en su territorio; b) Exigir una licencia o autorización para el ejercicio del corretaje; o c) \u0007Exigir que en las</span></span>, licencias o autorizaciones de corretaje <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">como el descrito en el párrafo 1 del presente artículo a que incluyan datos sobre los corredores y las operaciones de corretaje en sus intercambios de información efectuados con arreglo al artículo 12 del presente Protocolo y a que mantengan un registro de corredores y de las operaciones de corretaje conforme a lo previsto en el artículo 7 del presente Protocolo</span></span>. <mark class=\"m-resp ex-q\" data-q=\"2-154\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículo 14 — Capacitación y asistencia técnica <span class=\"ex-sello\">✱</span></div><div class=\"ex-fb\"><p data-ex=\"*\"><mark class=\"m-autoridad\">Los Estados Parte</mark> <mark class=\"m-accion\">cooperarán</mark> <mark class=\"m-personalizado\">entre sí y con las organizaciones internacionales pertinentes,</mark> según proceda, a fin de que los <mark class=\"m-autoridad\">Estados</mark> Parte que lo soliciten reciban la <mark class=\"m-destacable\">formación y asistencia</mark> técnica requeridas para <mark class=\"m-personalizado\">reforzar su capacidad de prevenir, combatir y erradicar</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">la fabricación y el tráfico ilícitos de armas de fuego, sus piezas y componentes y municiones</span></span> <mark class=\"m-resp ex-q\" data-q=\"2-199\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha\"><div class=\"ex-fh\">Artículos 16 a 18 — Controversias y entrada en vigor</div><div class=\"ex-fb\"><p><b>Art. 16.</b> 1. Los <mark class=\"m-autoridad\">Estados</mark> Parte <mark class=\"m-accion\">procurarán</mark> <mark class=\"m-destacable\">solucionar toda controversia</mark> relacionada con la <mark class=\"m-personalizado\">interpretación</mark> o aplicación del presente Protocolo mediante la <mark class=\"m-resp\" data-q=\"2-66\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas (hay oficiales)\">negociación</mark>. 2. <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">\u0007Toda controversia entre dos o más Estados Parte acerca de la interpretación o la aplicación del presente Protocolo que no pueda resolverse mediante la negociación dentro de un plazo razonable deberá, a solicitud de uno de esos Estados Parte, someterse a</span></span></span> arbitraje. Si, <mark class=\"m-personalizado\">seis meses después de</mark> <mark class=\"m-autoridad\">la fecha de</mark> la solicitud <mark class=\"m-personalizado\">de arbitraje</mark>, <mark class=\"m-personalizado\">esos</mark> <mark class=\"m-autoridad\">Estados</mark> Parte no han <mark class=\"m-personalizado\">podido ponerse de acuerdo</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">sobre la organización del arbitraje</span></span>, <mark class=\"m-resp r-ia\" data-q=\"2-ia-2535\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">cualquiera de esos Estados Parte podrá remitir la controversia a la Corte Internacional de Justicia</mark> <span class=\"ex-plg\" tabindex=\"0\" title=\"Pulsa para ver el texto omitido\" onclick=\"if(event.target===this)this.classList.toggle('on')\"><span class=\"ex-plg-t\">mediante solicitud conforme al Estatuto de la Corte</span></span>.</p><p><b>Art. <mark class=\"m-personalizado\">18.</mark></b> 1. El presente Protocolo <mark class=\"m-accion\">entrará</mark> en vigor el <mark class=\"m-resp r-ia\" data-q=\"2-ia-2422\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">nonagésimo día después de la fecha en que se haya depositado el cuadragésimo instrumento</mark> de ratificación (…), <mark class=\"m-resp r-ia\" data-q=\"2-ia-2209,2-ia-2537\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">a condición de que no entre en vigor antes de la entrada en vigor de la Convención</mark>. (…) El <mark class=\"m-destacable\">depositario</mark> es el <mark class=\"m-resp r-ia\" data-q=\"2-ia-2218\" title=\"Doble clic (doble toque en el móvil) para repasar sus preguntas\">Secretario General de las Naciones Unidas</mark>.</p></div></div>","cob":[{"nombre":"2.1 Ley 19/2003","total":111,"ok":111,"pct":100},{"nombre":"2.2 Convenio 196","total":120,"ok":120,"pct":100},{"nombre":"2.3 Ley 10/2010","total":374,"ok":370,"pct":98},{"nombre":"2.4 Palermo","total":168,"ok":168,"pct":100},{"nombre":"2.5 Trata","total":86,"ok":86,"pct":100},{"nombre":"2.6 Migrantes","total":50,"ok":50,"pct":100},{"nombre":"2.7 Armas","total":48,"ok":48,"pct":100}]};
